__CR('t:mobile',[{"t":"앱 개발 기초","l":[{"t":"플랫폼과 언어","q":[{"t":"choice","k":"개념","q":"구글이 만든 모바일 운영체제는?","o":["안드로이드","리눅스폰","윈도우폰","iOS"],"a":0,"ex":"안드로이드는 세계에서 가장 많이 쓰이는 모바일 OS 입니다."},{"t":"choice","k":"언어","q":"iOS(아이폰) 앱 개발의 주력 언어는?","o":["Go","C#","Kotlin","Swift"],"a":3,"ex":"애플은 Swift 를 iOS 개발 언어로 씁니다."},{"t":"choice","k":"개념","q":"애플 아이폰의 운영체제는?","o":["watchOS","macOS","iOS","안드로이드"],"a":2,"ex":"iOS 는 아이폰·아이패드의 운영체제입니다."},{"t":"choice","k":"언어","q":"안드로이드 앱 개발의 주력 언어는?","o":["PHP","Kotlin","Ruby","Swift"],"a":1,"ex":"현재 안드로이드는 Kotlin 을 주로 씁니다(과거엔 Java)."}],"th":{"sum":"모바일은 구글의 **Android**와 애플의 **iOS** 두 플랫폼으로 나뉘며, 각각 `Kotlin`과 `Swift`가 주력 언어이고, 하나의 코드로 둘 다 만드는 크로스 플랫폼 도구도 있다.","body":[{"h":"플랫폼과 언어","t":"구글이 만든 모바일 운영체제는 Android, 애플 아이폰의 운영체제는 iOS다. 안드로이드 앱 개발의 주력 언어는 Kotlin(이전에는 Java), iOS 앱 개발의 주력 언어는 Swift(이전에는 Objective-C)다. 각 플랫폼은 고유의 SDK와 개발 도구(Android Studio, Xcode)를 쓴다."},{"h":"크로스 플랫폼과 배포","t":"하나의 코드베이스로 안드로이드와 iOS를 모두 만드는 대표 크로스 플랫폼 프레임워크는 Flutter(그 외 React Native)다. 개발한 앱은 스토어를 통해 배포하는데, 안드로이드 앱은 구글의 Google Play(플레이 스토어), 아이폰 앱은 애플의 App Store에 올린다."}],"key":["Android = 구글 OS(주력 Kotlin), iOS = 애플 OS(주력 Swift)","한 코드로 양쪽 = Flutter(크로스 플랫폼)","배포: 안드로이드 = Google Play, 아이폰 = App Store"],"code":{"c":"모바일 앱은 OS가 생명주기를 통제한다 — 콜백에서 상태를 저장/복원한다.\n\n  실행    onCreate / viewDidLoad      1회: 화면 구성\n  표시    onStart·onResume           포그라운드 진입: 갱신 재개\n  가림    onPause·onStop             전화·홈 이동: 저장·타이머 정지\n  종료    onDestroy                  리소스 해제\n\n주의점\n  - 백그라운드 앱은 OS가 메모리 회수를 위해 임의로 종료할 수 있다\n    → 저장하지 않은 입력은 사라진다(onPause에서 저장)\n  - 화면 회전 등 구성 변경 시 액티비티가 재생성될 수 있다\n  - 네트워크·위치 같은 작업은 화면이 가려지면 반드시 정리해\n    배터리와 데이터를 낭비하지 않게 한다","cap":"생명주기 콜백에서 저장·정리하지 않으면 데이터와 배터리를 잃는다."}}},{"t":"개발 개념","q":[{"t":"choice","k":"개념","q":"안드로이드 앱을 배포하는 구글의 스토어는?","o":["App Store","Steam","Play 스토어","GitHub"],"a":2,"ex":"구글 Play 스토어에 앱을 올립니다."},{"t":"choice","k":"개념","q":"아이폰 앱을 배포하는 애플의 스토어는?","o":["Play 스토어","Microsoft Store","npm","App Store"],"a":3,"ex":"애플 App Store 에 심사를 거쳐 올립니다."},{"t":"choice","k":"개념","q":"하나의 코드로 안드로이드·iOS 를 모두 만드는 대표 프레임워크는?","o":["React Native / Flutter","jQuery","Bootstrap","Express"],"a":0,"ex":"크로스플랫폼 프레임워크로 개발 비용을 줄입니다."},{"t":"choice","k":"개념","q":"화면을 구성하는 버튼·텍스트 같은 각 구성요소를 뭐라 부르나요?","o":["드라이버","UI 위젯/컴포넌트","커널","패킷"],"a":1,"ex":"위젯(컴포넌트)을 조합해 화면을 만듭니다."}],"th":{"sum":"모바일은 구글의 **Android**와 애플의 **iOS** 두 플랫폼으로 나뉘며, 각각 `Kotlin`과 `Swift`가 주력 언어이고, 하나의 코드로 둘 다 만드는 크로스 플랫폼 도구도 있다.","body":[{"h":"플랫폼과 언어","t":"구글이 만든 모바일 운영체제는 Android, 애플 아이폰의 운영체제는 iOS다. 안드로이드 앱 개발의 주력 언어는 Kotlin(이전에는 Java), iOS 앱 개발의 주력 언어는 Swift(이전에는 Objective-C)다. 각 플랫폼은 고유의 SDK와 개발 도구(Android Studio, Xcode)를 쓴다."},{"h":"크로스 플랫폼과 배포","t":"하나의 코드베이스로 안드로이드와 iOS를 모두 만드는 대표 크로스 플랫폼 프레임워크는 Flutter(그 외 React Native)다. 개발한 앱은 스토어를 통해 배포하는데, 안드로이드 앱은 구글의 Google Play(플레이 스토어), 아이폰 앱은 애플의 App Store에 올린다."}],"key":["Android = 구글 OS(주력 Kotlin), iOS = 애플 OS(주력 Swift)","한 코드로 양쪽 = Flutter(크로스 플랫폼)","배포: 안드로이드 = Google Play, 아이폰 = App Store"],"code":{"c":"모바일 앱은 OS가 생명주기를 통제한다 — 콜백에서 상태를 저장/복원한다.\n\n  실행    onCreate / viewDidLoad      1회: 화면 구성\n  표시    onStart·onResume           포그라운드 진입: 갱신 재개\n  가림    onPause·onStop             전화·홈 이동: 저장·타이머 정지\n  종료    onDestroy                  리소스 해제\n\n주의점\n  - 백그라운드 앱은 OS가 메모리 회수를 위해 임의로 종료할 수 있다\n    → 저장하지 않은 입력은 사라진다(onPause에서 저장)\n  - 화면 회전 등 구성 변경 시 액티비티가 재생성될 수 있다\n  - 네트워크·위치 같은 작업은 화면이 가려지면 반드시 정리해\n    배터리와 데이터를 낭비하지 않게 한다","cap":"생명주기 콜백에서 저장·정리하지 않으면 데이터와 배터리를 잃는다."}}},{"t":"직접 짜 보기 — 화면 하나가 뜨기까지","th":{"sum":"모바일 앱은 **화면이 쌓이고 걷히는 더미**다. 뒤로 가기는 그 더미에서 하나를 걷어내는 일이다.","body":[{"h":"화면은 스택으로 쌓인다","t":"새 화면을 열면 위에 쌓이고, 뒤로 가면 걷힌다. 마지막 화면에서 뒤로 가면 앱이 종료된다 — 이 규칙을 모르면 '뒤로 가기가 이상하다' 는 버그를 잡을 수 없다."},{"h":"네이티브·크로스플랫폼·웹뷰","t":"네이티브는 가장 빠르고 기기 기능을 다 쓰지만 두 벌을 만들어야 한다. 크로스플랫폼(React Native·Flutter)은 한 벌로 두 곳에 내지만 새 OS 기능이 늦다. 웹뷰는 가장 싸지만 느리고 기기 기능이 제한된다."},{"h":"화면 크기는 하나가 아니다","t":"같은 앱이 작은 폰과 큰 태블릿에서 돈다. 픽셀 대신 밀도 독립 단위를 쓰고, 넓어지면 배치를 바꾼다 — 고정 크기로 짜면 어느 기기에선가 반드시 깨진다."},{"h":"메인 스레드를 막지 않는다","t":"화면을 그리는 스레드에서 네트워크나 파일 작업을 하면 앱이 얼어붙는다. 몇 백 밀리초만 막혀도 사용자는 '고장' 으로 느낀다."}],"code":{"c":"스택: [홈] → [목록] → [상세]\n뒤로 → [홈, 목록]\n뒤로 → [홈]\n뒤로 → 앱 종료\n\n무거운 일은 메인 스레드 밖에서","cap":"쌓고 걷어낸다"},"key":["화면은 스택","메인 스레드를 막지 않는다","고정 크기로 짜지 않는다"]},"q":[{"k":"back · 뒤로 가면 무엇이 남나","cat":"internals","q":"화면 스택과 뒤로 가기 횟수를 받아 <b>남은 스택</b>을 돌려주세요. 다 걷히면 <b>빈 목록</b>(앱 종료)입니다.","src":"def back(stack, n):\n    return stack[:-n]\n","sol":"def back(stack, n):\n    if n >= len(stack):\n        return []\n    return stack[:len(stack) - n]\n","ex":"`stack[:-0]` 은 빈 목록이 아니라 **전체**입니다 — 뒤로 가기 0번이 전부 지우는 것으로 보이면 반대로 동작해요. 그리고 남은 것보다 많이 걷으려 하면 음수 슬라이스가 되어 엉뚱한 결과가 나옵니다.","t":"py","tests":[{"in":"back(['홈', '목록', '상세'], 1)","out":"['홈', '목록']"},{"in":"back(['홈', '목록'], 2)","out":"[]"},{"in":"back(['홈'], 3)","out":"[]"}],"edge":[{"in":"back(['홈', '목록'], 0)","out":"['홈', '목록']"},{"in":"back([], 1)","out":"[]"}]},{"k":"dp_to_px · 기기마다 다른 픽셀","cat":"internals","q":"밀도 독립 단위와 배율을 받아 <b>실제 픽셀</b>을 돌려주세요. 반올림하고, 결과는 <b>최소 1</b>입니다.","src":"def dp_to_px(dp, scale):\n    return int(dp * scale)\n","sol":"def dp_to_px(dp, scale):\n    v = int(round(dp * scale))\n    return v if v >= 1 else 1\n","ex":"`int()` 는 버리기라 1.5dp 짜리 구분선이 0픽셀이 되어 **사라집니다** — 저밀도 기기에서만 선이 안 보이는, 재현하기 어려운 버그예요. 반올림하고 최소 1을 보장하면 어느 기기에서도 보입니다.","t":"py","tests":[{"in":"dp_to_px(10, 2.0)","out":"20"},{"in":"dp_to_px(10, 1.5)","out":"15"},{"in":"dp_to_px(1, 0.4)","out":"1"}],"edge":[{"in":"dp_to_px(0, 3.0)","out":"1"},{"in":"dp_to_px(3, 1.6)","out":"5"}]},{"k":"main_thread_ok · 이 일을 여기서 해도 되나","cat":"internals","q":"작업 이름과 예상 소요 시간(ms)을 받아, <b>16ms 이하</b>일 때만 메인 스레드에서 해도 된다고 True 를 돌려주세요. 이름이 <code>'network'</code>·<code>'disk'</code> 면 시간과 무관하게 False 입니다.","src":"def main_thread_ok(kind, ms):\n    return ms <= 16\n","sol":"def main_thread_ok(kind, ms):\n    if kind in ('network', 'disk'):\n        return False\n    return ms <= 16\n","ex":"네트워크는 지금 1ms 여도 지하철에서 30초가 됩니다 — 걸린 시간으로 판단하면 개발자 책상에서만 멀쩡해요. 시간이 **예측 불가능한** 종류의 작업은 아예 메인 스레드에 올리지 않습니다. 16ms 는 60fps 한 프레임의 예산입니다.","t":"py","tests":[{"in":"main_thread_ok('compute', 5)","out":"True"},{"in":"main_thread_ok('compute', 100)","out":"False"},{"in":"main_thread_ok('network', 1)","out":"False"}],"edge":[{"in":"main_thread_ok('disk', 0)","out":"False"},{"in":"main_thread_ok('compute', 16)","out":"True"}]}]}],"ord":1},{"t":"생명주기와 상태 저장","l":[{"t":"생명주기 콜백 읽기","q":[{"t":"choice","k":"mob-bundle-size","q":"안드로이드 onSaveInstanceState의 Bundle에 넣기에 적절한 데이터는?","ex":"Bundle은 프로세스 간 전달되는 작은 상태 저장소라 큰 데이터를 넣으면 TransactionTooLargeException 등 문제가 생긴다.\n💡 개념: 큰 데이터는 다시 불러올 수 있도록 ID나 키만 저장하는 것이 정석이다.\n🛠 실무: 목록은 ID만 저장하고 복원 시 캐시나 DB에서 다시 읽는다.","o":["서버에서 받은 수천 건의 목록 전체","사용자가 선택한 탭 인덱스와 입력 중인 짧은 텍스트","전체 데이터베이스 스냅샷","고화질 비트맵 이미지"],"a":1},{"t":"choice","k":"mob-rotate-default","q":"안드로이드에서 별도 설정 없이 화면을 회전하면 기본적으로 어떤 일이 일어나는가?","ex":"회전은 구성 변경이라 기본 동작으로 Activity를 파괴하고 재생성하며, 그래서 상태를 저장하지 않으면 사라진다.\n💡 개념: 다크 모드 전환, 언어 변경도 같은 구성 변경이다.\n🛠 실무: 회전 테스트는 상태 저장 버그를 잡는 가장 값싼 QA 시나리오다.","o":["Activity가 파괴되고 다시 생성된다","Activity가 그대로 유지되고 레이아웃만 다시 계산된다","아무 일도 일어나지 않는다","앱 프로세스가 종료된다"],"a":0},{"t":"choice","k":"mob-viewmodel-scope","q":"안드로이드 ViewModel의 생존 범위를 정확히 설명한 것은?","ex":"ViewModel은 구성 변경 동안 유지되지만 프로세스 종료에는 살아남지 못한다.\n💡 개념: 그래서 프로세스 종료 복원용으로는 SavedStateHandle이나 영속 저장소가 필요하다.\n🛠 실무: '회전은 ViewModel, 프로세스 종료는 SavedState/DB'로 역할을 나눠 기억하면 편하다.","o":["앱을 지워도 남는다","프로세스가 죽어도 자동 복원된다","onPause마다 초기화된다","화면 회전 같은 구성 변경은 견디지만 프로세스가 종료되면 사라진다"],"a":3},{"t":"choice","k":"mob-onpause-work","q":"안드로이드에서 사용자가 홈 버튼을 눌러 앱이 가려질 때 '반드시 저장해야 할 것'을 처리하기에 가장 적절한 시점은?","ex":"onPause/onStop은 화면이 가려질 때 확실히 호출되지만 onDestroy는 프로세스가 강제 종료되면 호출되지 않을 수 있다.\n💡 개념: 생명주기 후반으로 갈수록 호출 보장이 약해진다.\n🛠 실무: 임시 저장(자동 저장 초안)은 onPause에서 처리하는 것이 안전하다.","o":["onCreate","onDestroy만","onPause 또는 onStop","onResume"],"a":2},{"t":"input","k":"mob-config-change-term","q":"안드로이드에서 화면 회전, 다크 모드 전환, 언어 변경처럼 Activity 재생성을 유발하는 사건을 통칭해 무엇이라 하는가? (한글 또는 영문)","ex":"정답은 구성 변경(configuration change)이다.\n💡 개념: 재생성을 전제로 UI 상태를 설계해야 한다.\n🛠 실무: android:configChanges로 직접 처리할 수도 있지만 리소스 재적용을 놓치기 쉬워 권장되지 않는다.","a":["구성 변경","설정 변경","configuration change","config change"]}],"th":{"sum":"모바일 앱은 사용자가 아니라 OS가 화면을 만들고 없애기 때문에 생명주기를 이해해야 한다. 언제든 중단되고 재생성될 수 있다는 전제 아래 상태를 저장하고 복원해야 한다.","body":[{"h":"OS가 주도하는 생명주기","t":"안드로이드 Activity는 onCreate, onStart, onResume, onPause, onStop, onDestroy 순서로 콜백을 받고, iOS는 not running, inactive, active, background, suspended 상태를 오간다. 전화가 오거나 다른 앱으로 전환되면 앱은 언제든 백그라운드로 밀려난다. 화면이 가려지는 순간(onPause/onStop, iOS의 scenePhase 변화)에 저장해야 할 것을 저장하는 것이 원칙이다."},{"h":"구성 변경과 재생성","t":"안드로이드에서 화면 회전, 다크 모드 전환, 언어 변경 같은 구성 변경(configuration change)이 일어나면 기본 동작은 Activity를 파괴하고 다시 만드는 것이다. 그래서 회전 한 번에 입력값이 사라지는 버그가 흔하다. onSaveInstanceState에 담아둔 작은 UI 상태는 재생성 시 Bundle로 되돌아온다."},{"h":"어디에 무엇을 저장할까","t":"onSaveInstanceState의 Bundle은 스크롤 위치나 입력 중인 텍스트처럼 작은 UI 상태용이며 큰 데이터를 넣으면 예외가 나거나 성능이 나빠진다. ViewModel은 구성 변경을 견디지만 프로세스가 종료되면 함께 사라진다. 사용자가 잃으면 안 되는 데이터는 DB나 파일 등 영속 저장소에 써야 한다."},{"h":"백그라운드는 특권이 아니다","t":"메모리가 부족하면 OS는 백그라운드 앱의 프로세스를 예고 없이 종료할 수 있다. 되돌아왔을 때 처음 화면이 아니라 사용자가 있던 자리로 복원하는 것이 좋은 앱의 조건이다. 오래 걸리는 작업은 화면에 매달지 말고 WorkManager(안드로이드)나 백그라운드 태스크 API에 맡긴다."}],"code":{"c":"안드로이드 Activity 생명주기\nonCreate -> onStart -> onResume  (사용자와 상호작용)\n   화면 가림: onPause -> onStop\n   복귀:      onRestart -> onStart -> onResume\n   종료/재생성: onDestroy\n\n// 회전에도 살아남을 작은 UI 상태\noverride fun onSaveInstanceState(outState: Bundle) {\n    super.onSaveInstanceState(outState)\n    outState.putString(\"draft\", editText.text.toString())\n}","cap":"화면이 가려지는 시점에 저장하고, 재생성 시 복원한다."},"key":["안드로이드 화면 회전은 기본적으로 Activity를 파괴하고 재생성한다","Bundle은 작은 UI 상태용, ViewModel은 구성 변경까지만, 영구 데이터는 저장소에","백그라운드 프로세스는 언제든 종료될 수 있으므로 복원 시나리오를 항상 가정한다"]}},{"t":"상태 복원과 백그라운드","q":[{"t":"choice","k":"mob-process-death","q":"백그라운드에 있던 앱으로 돌아왔더니 로그인 화면부터 다시 시작됐다. 가장 흔한 원인은?","ex":"OS는 메모리가 부족하면 백그라운드 프로세스를 종료하며, 복원 로직이 없으면 처음 화면부터 시작된다.\n💡 개념: 프로세스 종료는 예외가 아니라 정상 시나리오다.\n🛠 실무: 개발자 옵션의 '백그라운드 프로세스 제한'이나 adb로 강제 종료해 복원 흐름을 테스트한다.","o":["화면 밝기가 바뀌어서","메모리 압박으로 OS가 프로세스를 종료했고 앱이 상태 복원을 구현하지 않아서","앱 용량이 커서","네트워크가 끊겨서"],"a":1},{"t":"choice","k":"mob-deep-link-restore","q":"사용자가 상세 화면을 보다가 앱이 종료된 뒤 다시 열었을 때 좋은 UX는?","ex":"복원 가능한 최소 정보(화면 식별자, 항목 ID, 스크롤 위치)를 저장해 두면 이어보기가 가능하다.\n💡 개념: 좋은 모바일 앱은 중단을 전제로 '이어서'를 설계한다.\n🛠 실무: 화면 상태를 저장 가능한 데이터 클래스로 모델링하면 복원 구현이 쉬워진다.","o":["오류 화면을 띄운다","앱을 재설치하라고 안내한다","보던 화면과 스크롤 위치를 복원해 이어서 보게 한다","항상 홈 화면으로 보낸다"],"a":2},{"t":"choice","k":"mob-background-work","q":"주기적으로 서버와 동기화하는 작업을 안드로이드에서 구현할 때 권장되는 방식은?","ex":"OS의 배터리 최적화(Doze 등)와 공존하려면 시스템 스케줄러에 위임하고 네트워크·충전 같은 제약 조건을 지정하는 것이 맞다.\n💡 개념: 화면에 매달린 작업은 화면이 사라지면 함께 죽는다.\n🛠 실무: 재시도와 백오프까지 스케줄러가 관리해 주므로 코드가 단순해진다.","o":["onResume마다 스레드를 새로 만들어 계속 돌린다","서비스에서 wake lock을 영구히 잡는다","Activity 안에서 무한 루프를 돌린다","WorkManager 같은 시스템 스케줄러에 제약 조건과 함께 맡긴다"],"a":3},{"t":"choice","k":"mob-anr-lifecycle","q":"안드로이드에서 onCreate 안에 동기 네트워크 호출을 넣으면 생기는 문제는?","ex":"생명주기 콜백은 메인 스레드에서 실행되므로 그 안에서 블로킹 I/O를 하면 UI가 멈추고 ANR이 발생할 수 있다.\n💡 개념: 메인 스레드는 오직 UI 갱신과 짧은 작업만 담당해야 한다.\n🛠 실무: 코루틴이나 비동기 API로 옮기고 로딩 상태를 UI에 표시한다.","o":["메인 스레드가 막혀 화면이 멈추고 ANR로 이어질 수 있다","앱이 자동으로 백그라운드로 간다","권한이 자동 승인된다","네트워크 속도가 두 배 빨라진다"],"a":0},{"t":"choice","k":"mob-ios-states","q":"iOS 앱 상태에 대한 설명으로 옳은 것은?","ex":"iOS 앱은 백그라운드로 간 뒤 짧은 정리 시간을 거쳐 suspended 되며 그 상태에서 코드는 실행되지 않고 메모리에만 남아 있다가 필요하면 종료된다.\n💡 개념: 장시간 작업은 백그라운드 태스크나 서버 푸시로 설계해야 한다.\n🛠 실무: 전환 시점에 저장하지 않으면 suspended 이후 종료될 때 데이터가 사라진다.","o":["백그라운드로 간 뒤 곧 suspended 상태가 되어 코드 실행이 멈추고, 메모리 압박 시 종료될 수 있다","앱은 항상 active 상태로만 존재한다","suspended 상태에서는 메모리에서 즉시 지워진다","백그라운드에서도 무제한으로 코드를 계속 실행할 수 있다"],"a":0}],"th":{"sum":"모바일 앱은 사용자가 아니라 OS가 화면을 만들고 없애기 때문에 생명주기를 이해해야 한다. 언제든 중단되고 재생성될 수 있다는 전제 아래 상태를 저장하고 복원해야 한다.","body":[{"h":"OS가 주도하는 생명주기","t":"안드로이드 Activity는 onCreate, onStart, onResume, onPause, onStop, onDestroy 순서로 콜백을 받고, iOS는 not running, inactive, active, background, suspended 상태를 오간다. 전화가 오거나 다른 앱으로 전환되면 앱은 언제든 백그라운드로 밀려난다. 화면이 가려지는 순간(onPause/onStop, iOS의 scenePhase 변화)에 저장해야 할 것을 저장하는 것이 원칙이다."},{"h":"구성 변경과 재생성","t":"안드로이드에서 화면 회전, 다크 모드 전환, 언어 변경 같은 구성 변경(configuration change)이 일어나면 기본 동작은 Activity를 파괴하고 다시 만드는 것이다. 그래서 회전 한 번에 입력값이 사라지는 버그가 흔하다. onSaveInstanceState에 담아둔 작은 UI 상태는 재생성 시 Bundle로 되돌아온다."},{"h":"어디에 무엇을 저장할까","t":"onSaveInstanceState의 Bundle은 스크롤 위치나 입력 중인 텍스트처럼 작은 UI 상태용이며 큰 데이터를 넣으면 예외가 나거나 성능이 나빠진다. ViewModel은 구성 변경을 견디지만 프로세스가 종료되면 함께 사라진다. 사용자가 잃으면 안 되는 데이터는 DB나 파일 등 영속 저장소에 써야 한다."},{"h":"백그라운드는 특권이 아니다","t":"메모리가 부족하면 OS는 백그라운드 앱의 프로세스를 예고 없이 종료할 수 있다. 되돌아왔을 때 처음 화면이 아니라 사용자가 있던 자리로 복원하는 것이 좋은 앱의 조건이다. 오래 걸리는 작업은 화면에 매달지 말고 WorkManager(안드로이드)나 백그라운드 태스크 API에 맡긴다."}],"code":{"c":"안드로이드 Activity 생명주기\nonCreate -> onStart -> onResume  (사용자와 상호작용)\n   화면 가림: onPause -> onStop\n   복귀:      onRestart -> onStart -> onResume\n   종료/재생성: onDestroy\n\n// 회전에도 살아남을 작은 UI 상태\noverride fun onSaveInstanceState(outState: Bundle) {\n    super.onSaveInstanceState(outState)\n    outState.putString(\"draft\", editText.text.toString())\n}","cap":"화면이 가려지는 시점에 저장하고, 재생성 시 복원한다."},"key":["안드로이드 화면 회전은 기본적으로 Activity를 파괴하고 재생성한다","Bundle은 작은 UI 상태용, ViewModel은 구성 변경까지만, 영구 데이터는 저장소에","백그라운드 프로세스는 언제든 종료될 수 있으므로 복원 시나리오를 항상 가정한다"]}},{"t":"직접 짜 보기 — 언제 저장하고 언제 되살리나","th":{"sum":"모바일 앱은 **언제든 뒤로 밀려나고, 언제든 죽을 수 있다**. 그래서 저장 시점이 중요하다.","body":[{"h":"화면이 가려지면 곧 죽을 수 있다","t":"전화가 오거나 홈으로 나가면 앱이 배경으로 밀린다. 메모리가 부족하면 OS 가 조용히 죽인다 — 배경으로 갈 때 저장해 두지 않으면 사용자가 쓰던 글이 사라진다."},{"h":"화면 회전도 재생성이다","t":"안드로이드는 회전할 때 화면을 다시 만든다. 메모리에만 들고 있던 값은 사라지므로, 상태를 따로 저장하고 복원해야 한다 — '회전하면 입력이 지워진다' 는 버그의 정체다."},{"h":"저장은 작게, 자주","t":"번들에 넣는 상태는 몇 KB 를 넘기면 안 된다. 큰 데이터는 파일이나 DB 에 두고, 번들에는 '무엇을 보고 있었나' 만 남긴다."},{"h":"복원은 없을 수도 있다","t":"처음 실행이면 저장된 상태가 없다. 복원 코드는 언제나 '없으면 기본값' 을 다뤄야 한다."}],"code":{"c":"onPause / onStop  → 저장 (곧 죽을 수 있다)\nonCreate          → 복원 (없으면 기본값)\n\n번들에는 작은 것만 — 큰 것은 DB 로","cap":"가려질 때 저장, 만들 때 복원"},"key":["배경으로 갈 때 저장한다","회전도 재생성이다","복원은 없을 수 있다"]},"q":[{"k":"should_save · 지금 저장해야 하나","cat":"internals","q":"생명주기 이벤트 이름을 받아, <code>'pause'</code>·<code>'stop'</code>·<code>'rotate'</code> 일 때 True 를 돌려주세요.","src":"def should_save(event):\n    return event == 'destroy'\n","sol":"def should_save(event):\n    return event in ('pause', 'stop', 'rotate')\n","ex":"`destroy` 를 기다리면 늦습니다 — 메모리가 부족해 OS 가 죽일 때는 그 콜백이 안 불릴 수도 있어요. 화면이 가려지는 순간(pause/stop)이 마지막으로 보장되는 시점입니다.","t":"py","tests":[{"in":"should_save('pause')","out":"True"},{"in":"should_save('rotate')","out":"True"},{"in":"should_save('resume')","out":"False"}],"edge":[{"in":"should_save('destroy')","out":"False"},{"in":"should_save('')","out":"False"}]},{"k":"restore · 없으면 기본값","cat":"internals","q":"저장된 상태 사전과 기본값 사전을 받아, <b>저장된 값이 있으면 그것</b>, 없으면 기본값을 쓴 사전을 돌려주세요. <b>기본값에 있는 키만</b> 남깁니다.","src":"def restore(saved, defaults):\n    return dict(saved)\n","sol":"def restore(saved, defaults):\n    return {k: saved.get(k, v) for k, v in defaults.items()}\n","ex":"저장된 것을 그대로 쓰면 첫 실행에서 빈 사전이 나와, 아래 코드가 없는 키를 읽다 터집니다. 그리고 앱을 업데이트해 새 설정이 생겨도 옛 저장본에는 그 키가 없어요 — 기본값을 바탕에 깔고 덮어쓰면 두 문제가 함께 해결됩니다.","t":"py","tests":[{"in":"restore({'page': 3}, {'page': 1, 'sort': 'new'})","out":"{'page': 3, 'sort': 'new'}"},{"in":"restore({}, {'page': 1})","out":"{'page': 1}"},{"in":"restore({'x': 9}, {'page': 1})","out":"{'page': 1}"}],"edge":[{"in":"restore({}, {})","out":"{}"},{"in":"restore({'page': 0}, {'page': 1})","out":"{'page': 0}"}]},{"k":"bundle_ok · 번들에 넣어도 되는 크기인가","cat":"internals","q":"저장할 값들의 <b>총 바이트</b>가 <code>limit</code> <b>이하</b>면 True 를 돌려주세요. 각 값의 크기는 문자열 길이로 셉니다.","src":"def bundle_ok(values, limit):\n    return len(values) <= limit\n","sol":"def bundle_ok(values, limit):\n    return sum(len(str(v)) for v in values) <= limit\n","ex":"개수만 세면 100KB 짜리 문자열 하나를 '한 개니까 괜찮다' 로 봅니다. 번들이 상한을 넘으면 안드로이드는 앱을 죽여 버려요 — 사용자에게는 '가끔 앱이 꺼진다' 로만 보이는, 원인 찾기 어려운 사고입니다.","t":"py","tests":[{"in":"bundle_ok(['abc', 'de'], 5)","out":"True"},{"in":"bundle_ok(['abc', 'de'], 4)","out":"False"},{"in":"bundle_ok([], 0)","out":"True"}],"edge":[{"in":"bundle_ok(['x' * 100], 50)","out":"False"},{"in":"bundle_ok([1, 22], 3)","out":"True"}]}]}],"ord":2},{"t":"네트워크·오프라인·캐시 전략","l":[{"t":"오프라인 우선과 동기화","q":[{"t":"choice","k":"mob-write-queue","q":"오프라인 상태에서 사용자가 글을 작성했다. 가장 좋은 처리 방식은?","ex":"로컬 저장 + 대기 큐 + 연결 복구 시 전송이 표준 패턴이다.\n💡 개념: 사용자 입력은 절대 잃지 않는 것이 원칙이다.\n🛠 실무: 큐에 있는 항목은 '전송 중' 표시를 주어 상태를 투명하게 보여준다.","o":["작성을 막고 오류를 띄운다","서버가 응답할 때까지 화면을 잠근다","로컬에 저장하고 전송 대기 큐에 넣은 뒤 연결이 돌아오면 자동으로 보낸다","무한 루프로 계속 재시도한다"],"a":2},{"t":"choice","k":"mob-conflict","q":"오프라인 편집 내용을 동기화할 때 last-write-wins 전략의 대표적 단점은?","ex":"단순하지만 늦게 도착한 쓰기가 앞선 변경을 덮어써 데이터 유실이 생길 수 있다.\n💡 개념: 버전(ETag)이나 타임스탬프로 충돌을 감지하면 병합이나 사용자 선택이 가능하다.\n🛠 실무: 노트·문서처럼 손실이 치명적인 도메인에서는 충돌 감지를 반드시 구현한다.","o":["구현이 지나치게 복잡하다","동시에 수정된 다른 쪽 변경이 조용히 사라질 수 있다","서버 저장 공간을 두 배로 쓴다","네트워크를 두 배로 쓴다"],"a":1},{"t":"choice","k":"mob-idempotent","q":"네트워크가 불안정해 같은 결제 요청이 두 번 전송될 수 있다. 서버 API 설계에서 필요한 성질은?","ex":"클라이언트 재시도를 안전하게 만들려면 요청 키(idempotency key) 기반의 멱등 처리가 필요하다.\n💡 개념: 모바일에서는 '응답을 못 받았지만 서버는 처리했다'는 상황이 흔하다.\n🛠 실무: 클라이언트가 생성한 UUID를 요청 키로 보내 서버가 중복을 흡수하게 한다.","o":["비동기성","압축","무상태성만으로 충분","멱등성(같은 요청을 여러 번 보내도 결과가 한 번 보낸 것과 같음)"],"a":3},{"t":"input","k":"mob-backoff-term","q":"재시도 간격을 2배씩 늘려가며 서버 부하와 배터리 소모를 줄이는 재시도 전략을 무엇이라 하는가? (한글 또는 영문)","ex":"정답은 지수 백오프(exponential backoff)이며 보통 지터를 함께 쓴다.\n💡 개념: 지터가 없으면 모든 기기가 같은 순간에 재시도해 서버를 덮친다.\n🛠 실무: 최대 지연 상한과 최대 재시도 횟수를 함께 정해 무한 재시도를 막는다.","a":["지수 백오프","지수백오프","exponential backoff","backoff"]},{"t":"choice","k":"mob-offline-first","q":"오프라인 우선(offline-first) 설계의 핵심 원칙은?","ex":"화면이 로컬을 보고 그리면 네트워크 상태와 무관하게 즉시 렌더링되고, 동기화는 배경에서 이뤄진다.\n💡 개념: 네트워크 실패가 빈 화면이 아니라 '오래된 데이터'로 다뤄진다.\n🛠 실무: 마지막 동기화 시각을 표시해 사용자에게 신선도를 알려주면 신뢰가 올라간다.","o":["UI는 로컬 저장소를 진실 공급원으로 읽고, 네트워크는 로컬을 갱신하는 역할을 한다","네트워크가 없으면 앱을 종료한다","캐시를 절대 쓰지 않는다","모든 데이터를 매번 서버에서 새로 받는다"],"a":0}],"th":{"sum":"모바일 네트워크는 느리고 끊기며 요금과 배터리가 든다. 그래서 요청을 줄이고, 로컬에 캐시하고, 끊겨도 동작하는 오프라인 우선 설계를 택한다.","body":[{"h":"모바일 네트워크의 현실","t":"지하철, 엘리베이터, 기지국 전환처럼 연결이 자주 끊기고 지연도 크게 튄다. 요청 하나의 왕복 지연이 수백 밀리초에 이르므로 요청 개수를 줄이는 것이 대역폭을 줄이는 것보다 효과적일 때가 많다. 셀룰러 데이터는 요금과 배터리 소모로도 이어진다."},{"h":"오프라인 우선 설계","t":"화면은 서버가 아니라 로컬 저장소(예: Room, SQLite, Core Data)를 읽고, 네트워크는 그 저장소를 갱신하는 역할만 맡는다. 이렇게 하면 비행기 모드에서도 앱이 즉시 뜨고, 요청 실패가 빈 화면이 아니라 '조금 오래된 데이터'로 나타난다. 쓰기 작업은 큐에 넣어 두었다가 연결이 돌아오면 전송한다."},{"h":"동기화 충돌","t":"오프라인에서 수정한 내용과 서버의 변경이 부딪히면 규칙이 필요하다. 마지막 쓰기 우선(last-write-wins)은 단순하지만 데이터를 잃을 수 있고, 버전이나 타임스탬프로 충돌을 감지해 병합하거나 사용자에게 물어보는 방법이 더 안전하다. 중복 전송에 대비해 서버 API는 멱등하게 설계하는 것이 좋다."},{"h":"재시도와 캐시 헤더","t":"실패했다고 즉시 반복해서 재시도하면 서버와 배터리를 함께 태운다. 지수 백오프에 무작위 지터를 더해 재시도 시점을 흩뜨려야 동시 몰림(thundering herd)을 막는다. HTTP 캐시는 Cache-Control로 유효 기간을, ETag와 If-None-Match로 조건부 요청을 만들어 변경이 없으면 304로 본문 없이 끝낼 수 있다."}],"code":{"c":"오프라인 우선 데이터 흐름\n[UI] <- 관찰 - [로컬 DB(진실 공급원)] <- 갱신 - [네트워크]\n                    ^\n            대기 큐 |  (연결 복구 시 전송)\n\n// 지수 백오프 + 지터 (개념)\ndelay = min(maxDelay, base * 2^attempt)\ndelay = delay * random(0.5, 1.5)\n\n// 조건부 요청\nGET /items   If-None-Match: \"v42\"\n304 Not Modified  -> 본문 전송 없음","cap":"화면은 로컬을 읽고, 네트워크는 로컬을 갱신한다."},"key":["오프라인 우선 설계는 로컬 저장소를 진실 공급원으로 삼는다","재시도는 지수 백오프에 지터를 더해 동시 몰림을 막는다","ETag 조건부 요청은 변경이 없을 때 304로 본문 전송을 없앤다"]}},{"t":"캐시와 데이터 절약","q":[{"t":"choice","k":"mob-etag","q":"HTTP 응답의 ETag와 요청의 If-None-Match를 함께 쓰면 얻는 이점은?","ex":"조건부 요청은 리소스가 그대로면 304 Not Modified로 본문 없이 끝나 트래픽을 줄인다.\n💡 개념: 왕복은 발생하지만 페이로드가 사라진다.\n🛠 실무: 목록·이미지 등 잘 안 바뀌는 리소스에 특히 효과가 크다.","o":["인증이 자동으로 처리된다","항상 최신 데이터를 두 배 빠르게 받는다","서버가 데이터를 압축해 준다","변경이 없으면 서버가 304를 반환해 본문 전송을 생략하므로 데이터와 배터리를 아낀다"],"a":3},{"t":"choice","k":"mob-image-cache","q":"목록에서 같은 썸네일을 스크롤할 때마다 다시 내려받는 문제를 해결하는 방법은?","ex":"2단 캐시(메모리+디스크)와 적정 크기 리사이즈가 이미지 로딩의 기본이다.\n💡 개념: 화면보다 큰 이미지는 메모리만 잡아먹고 화질 이득이 없다.\n🛠 실무: Coil, Glide, SDWebImage 같은 라이브러리가 이 전략을 기본 제공한다.","o":["스크롤을 막는다","이미지를 원본 해상도로 다운로드한다","메모리 캐시와 디스크 캐시를 함께 두고 화면 크기에 맞춰 리사이즈된 이미지를 재사용한다","이미지를 Base64로 JSON에 넣어 함께 받는다"],"a":2},{"t":"choice","k":"mob-metered","q":"셀룰러(종량제) 네트워크에서 대용량 동기화를 다루는 바람직한 정책은?","ex":"종량제 네트워크에서는 사용자의 데이터 요금과 배터리를 고려해 제약 조건을 걸어야 한다.\n💡 개념: 시스템 스케줄러는 네트워크 종류와 충전 상태를 조건으로 지정할 수 있다.\n🛠 실무: 대용량 미디어 프리로드는 Wi-Fi 조건으로 제한하는 것이 일반적이다.","o":["사용자에게 묻지 않고 백그라운드에서 무제한으로 받는다","Wi-Fi 연결 또는 충전 중일 때로 미루고, 셀룰러에서는 꼭 필요한 것만 받는다","항상 즉시 전부 내려받는다","동기화를 아예 하지 않는다"],"a":1},{"t":"choice","k":"mob-timeout","q":"불안정한 모바일 네트워크를 고려한 타임아웃 설정으로 적절한 것은?","ex":"무한 대기는 화면을 영원히 로딩 상태로 만들고, 지나치게 짧은 타임아웃은 정상 요청까지 실패시킨다.\n💡 개념: 타임아웃, 재시도, 사용자 피드백은 한 세트로 설계한다.\n🛠 실무: 연결·읽기 타임아웃을 나눠 설정하고 재시도 가능한 오류만 재시도한다.","o":["합리적인 타임아웃을 두고 실패 시 백오프 재시도와 사용자 안내를 제공한다","타임아웃 대신 앱을 재시작한다","타임아웃을 두지 않고 무한정 기다린다","타임아웃을 0.1초로 둔다"],"a":0},{"t":"choice","k":"mob-request-count","q":"모바일에서 목록 화면 하나를 그리려고 API를 30번 호출하고 있다. 개선 방향으로 가장 적절한 것은?","ex":"모바일에서는 왕복 지연이 커서 요청 개수를 줄이는 것이 체감 성능에 크게 기여한다.\n💡 개념: 화면 단위로 필요한 데이터를 한 번에 주는 BFF나 GraphQL 방식이 자주 쓰인다.\n🛠 실무: 응답에서 쓰지 않는 필드를 빼는 것만으로도 파싱 비용과 트래픽이 줄어든다.","o":["요청을 병렬로 60개 보낸다","이미지 해상도를 두 배로 올린다","요청을 하나로 묶거나 필요한 필드만 담은 집계 API를 만들어 왕복 횟수를 줄인다","타임아웃을 늘린다"],"a":2}],"th":{"sum":"모바일 네트워크는 느리고 끊기며 요금과 배터리가 든다. 그래서 요청을 줄이고, 로컬에 캐시하고, 끊겨도 동작하는 오프라인 우선 설계를 택한다.","body":[{"h":"모바일 네트워크의 현실","t":"지하철, 엘리베이터, 기지국 전환처럼 연결이 자주 끊기고 지연도 크게 튄다. 요청 하나의 왕복 지연이 수백 밀리초에 이르므로 요청 개수를 줄이는 것이 대역폭을 줄이는 것보다 효과적일 때가 많다. 셀룰러 데이터는 요금과 배터리 소모로도 이어진다."},{"h":"오프라인 우선 설계","t":"화면은 서버가 아니라 로컬 저장소(예: Room, SQLite, Core Data)를 읽고, 네트워크는 그 저장소를 갱신하는 역할만 맡는다. 이렇게 하면 비행기 모드에서도 앱이 즉시 뜨고, 요청 실패가 빈 화면이 아니라 '조금 오래된 데이터'로 나타난다. 쓰기 작업은 큐에 넣어 두었다가 연결이 돌아오면 전송한다."},{"h":"동기화 충돌","t":"오프라인에서 수정한 내용과 서버의 변경이 부딪히면 규칙이 필요하다. 마지막 쓰기 우선(last-write-wins)은 단순하지만 데이터를 잃을 수 있고, 버전이나 타임스탬프로 충돌을 감지해 병합하거나 사용자에게 물어보는 방법이 더 안전하다. 중복 전송에 대비해 서버 API는 멱등하게 설계하는 것이 좋다."},{"h":"재시도와 캐시 헤더","t":"실패했다고 즉시 반복해서 재시도하면 서버와 배터리를 함께 태운다. 지수 백오프에 무작위 지터를 더해 재시도 시점을 흩뜨려야 동시 몰림(thundering herd)을 막는다. HTTP 캐시는 Cache-Control로 유효 기간을, ETag와 If-None-Match로 조건부 요청을 만들어 변경이 없으면 304로 본문 없이 끝낼 수 있다."}],"code":{"c":"오프라인 우선 데이터 흐름\n[UI] <- 관찰 - [로컬 DB(진실 공급원)] <- 갱신 - [네트워크]\n                    ^\n            대기 큐 |  (연결 복구 시 전송)\n\n// 지수 백오프 + 지터 (개념)\ndelay = min(maxDelay, base * 2^attempt)\ndelay = delay * random(0.5, 1.5)\n\n// 조건부 요청\nGET /items   If-None-Match: \"v42\"\n304 Not Modified  -> 본문 전송 없음","cap":"화면은 로컬을 읽고, 네트워크는 로컬을 갱신한다."},"key":["오프라인 우선 설계는 로컬 저장소를 진실 공급원으로 삼는다","재시도는 지수 백오프에 지터를 더해 동시 몰림을 막는다","ETag 조건부 요청은 변경이 없을 때 304로 본문 전송을 없앤다"]}},{"t":"직접 짜 보기 — 끊겨도 쓸 수 있게","th":{"sum":"모바일에서 네트워크는 **있다가 없다가 하는 것**이다. 끊김을 예외가 아니라 기본으로 다룬다.","body":[{"h":"캐시 먼저 보여 주고 뒤에서 갱신","t":"저장해 둔 것을 즉시 띄우고, 새 데이터가 오면 바꿔 준다. 화면이 비어 있는 시간이 사라져 체감 속도가 크게 좋아진다."},{"h":"쓰기는 큐에 넣는다","t":"오프라인에서 누른 '좋아요' 를 버리지 않고 큐에 쌓았다가, 연결되면 순서대로 보낸다. 사용자에게는 이미 눌린 것으로 보여 준다(낙관적 UI)."},{"h":"재시도에는 지터를 섞는다","t":"끊겼다 돌아오면 모든 기기가 동시에 재시도해 서버를 밀어붙인다. 대기 시간에 무작위를 조금 섞으면 이 몰림이 흩어진다."},{"h":"캐시에는 유효기간이 있어야 한다","t":"언제까지 믿을지 정해 두지 않으면, 며칠 지난 값을 계속 보여 준다. 신선도를 넘으면 화면에 띄우되 '갱신 중' 을 함께 보여 주는 것이 보통이다."}],"code":{"c":"1) 캐시 즉시 표시\n2) 네트워크 요청\n3) 오면 갱신\n\n오프라인 쓰기 → 큐 → 연결되면 순서대로\n재시도 대기 = base * 2^n + 무작위","cap":"끊김이 기본이다"},"key":["캐시 먼저, 갱신은 뒤에","쓰기는 큐에 쌓는다","재시도에 지터를 섞는다"]},"q":[{"k":"cache_state · 이 캐시를 쓸 수 있나","cat":"internals","q":"저장 시각·현재 시각·유효기간을 받아 <code>'신선'</code>(기간 안), <code>'낡음'</code>(기간을 넘었지만 <code>stale</code> 안), <code>'버림'</code> 을 돌려주세요.","src":"def cache_state(saved, now, ttl, stale):\n    return '신선' if now - saved <= ttl else '버림'\n","sol":"def cache_state(saved, now, ttl, stale):\n    age = now - saved\n    if age <= ttl:\n        return '신선'\n    if age <= stale:\n        return '낡음'\n    return '버림'\n","ex":"신선하지 않으면 곧바로 버리면, 지하철에서 화면이 텅 빕니다. 조금 낡은 데이터라도 보여 주면서 뒤에서 갱신하는 편이 훨씬 나아요 — '낡음' 이라는 중간 상태가 오프라인 경험을 만듭니다.","t":"py","tests":[{"in":"cache_state(0, 5, 10, 100)","out":"'신선'"},{"in":"cache_state(0, 50, 10, 100)","out":"'낡음'"},{"in":"cache_state(0, 500, 10, 100)","out":"'버림'"}],"edge":[{"in":"cache_state(0, 10, 10, 100)","out":"'신선'"},{"in":"cache_state(0, 100, 10, 100)","out":"'낡음'"}]},{"k":"flush_queue · 순서대로 보내기","cat":"internals","q":"대기 큐와 <b>연결 여부</b>를 받아 <code>(보낸 것, 남은 것)</code> 을 돌려주세요. 연결이 없으면 <b>아무것도 못 보냅니다</b>. 한 번에 최대 <code>n</code>개입니다.","src":"def flush_queue(queue, online, n):\n    return (queue[:n], queue[n:])\n","sol":"def flush_queue(queue, online, n):\n    if not online:\n        return ([], list(queue))\n    return (queue[:n], queue[n:])\n","ex":"연결이 없는데 보낸 것으로 처리하면 큐에서 사라집니다 — 사용자가 오프라인에서 쓴 글이 영영 안 올라가요. 게다가 화면에는 성공으로 보이니 아무도 모릅니다. 보낼 수 없으면 큐에 그대로 남겨 둡니다.","t":"py","tests":[{"in":"flush_queue(['a', 'b', 'c'], True, 2)","out":"(['a', 'b'], ['c'])"},{"in":"flush_queue(['a', 'b'], False, 2)","out":"([], ['a', 'b'])"},{"in":"flush_queue([], True, 2)","out":"([], [])"}],"edge":[{"in":"flush_queue(['a'], True, 5)","out":"(['a'], [])"},{"in":"flush_queue(['a'], False, 0)","out":"([], ['a'])"}]},{"k":"backoff_jitter · 동시에 몰리지 않게","cat":"internals","q":"시도 횟수·기본 대기·<b>지터 비율</b>·무작위값(0~1)을 받아 대기 시간을 돌려주세요. <code>base * 2**n</code> 에 <code>(1 - jitter + 2*jitter*r)</code> 을 곱합니다.","src":"def backoff_jitter(n, base, jitter, r):\n    return base * (2 ** n)\n","sol":"def backoff_jitter(n, base, jitter, r):\n    return base * (2 ** n) * (1 - jitter + 2 * jitter * r)\n","ex":"지터가 없으면 끊겼던 기기 수만 대가 **정확히 같은 순간**에 재시도합니다 — 서버가 막 살아나려는 참에 다시 쓰러져요. 대기 시간을 조금씩 흩뜨리는 곱셈 하나가 그 몰림을 막습니다.","t":"py","tests":[{"in":"backoff_jitter(0, 100, 0.0, 0.5)","out":"100.0"},{"in":"backoff_jitter(1, 100, 0.5, 0.5)","out":"200.0"},{"in":"backoff_jitter(0, 100, 0.5, 0.0)","out":"50.0"}],"edge":[{"in":"backoff_jitter(0, 100, 0.5, 1.0)","out":"150.0"},{"in":"backoff_jitter(2, 10, 0.0, 0.9)","out":"40.0"}]}]}],"ord":3},{"t":"성능·배터리·권한과 프라이버시","l":[{"t":"프레임 예산과 메인 스레드","q":[{"t":"choice","k":"mob-frame-budget","q":"60fps로 부드럽게 동작하려면 한 프레임을 그리는 데 쓸 수 있는 시간은 대략 얼마인가?","ex":"1초를 60으로 나누면 약 16.7밀리초다.\n💡 개념: 120Hz 화면에서는 예산이 약 8.3밀리초로 절반이 된다.\n🛠 실무: 프로파일러에서 프레임 시간이 예산을 넘는 구간을 먼저 잡는다.","o":["약 160밀리초","약 1.6밀리초","약 60밀리초","약 16.7밀리초"],"a":3},{"t":"choice","k":"mob-image-memory","q":"모바일 앱에서 OutOfMemory 크래시를 일으키는 대표적 원인은?","ex":"고해상도 원본을 그대로 비트맵으로 펼치면 수십 메가바이트가 순식간에 소모된다.\n💡 개념: 비트맵 메모리는 픽셀 수에 비례해 늘어난다.\n🛠 실무: 화면 표시 크기에 맞춰 다운샘플링하고 캐시 크기 상한을 둔다.","o":["다크 모드 지원","작은 JSON 응답","화면 크기보다 훨씬 큰 원본 이미지를 그대로 디코딩해 메모리에 올리는 것","로그를 남기는 것"],"a":2},{"t":"choice","k":"mob-anr-cause","q":"안드로이드에서 ANR(Application Not Responding)이 발생하는 전형적인 원인은?","ex":"ANR은 메인 스레드가 일정 시간 이상 응답하지 못할 때 시스템이 띄운다.\n💡 개념: 백그라운드 작업 자체는 ANR을 유발하지 않는다.\n🛠 실무: 메인 스레드에서 디스크·네트워크 접근을 감지하는 StrictMode를 개발 빌드에 켜두면 좋다.","o":["권한을 많이 선언해서","메인(UI) 스레드가 오래 블로킹되어 입력에 응답하지 못해서","백그라운드 스레드에서 계산을 많이 해서","앱 용량이 커서"],"a":1},{"t":"choice","k":"mob-list-recycle","q":"긴 목록 화면에서 RecyclerView(안드로이드)나 UITableView(iOS)가 뷰를 재사용하는 이유는?","ex":"화면에 보이는 항목 수만큼만 뷰를 만들고 스크롤 시 재활용하면 항목이 수만 개라도 메모리와 생성 비용이 일정하게 유지된다.\n💡 개념: 이 재사용 때문에 바인딩 시 이전 상태를 반드시 초기화해야 한다.\n🛠 실무: 재사용 뷰의 이미지·체크 상태를 지우지 않으면 스크롤 시 엉뚱한 값이 보인다.","o":["보이는 만큼만 뷰를 만들고 재사용해 메모리와 생성 비용을 줄이기 위해","권한 요청을 줄이기 위해","코드가 짧아져서","네트워크 요청을 줄이기 위해"],"a":0},{"t":"input","k":"mob-mainthread-term","q":"모바일에서 UI를 갱신할 수 있는 유일한 스레드이며 블로킹하면 화면이 멈추는 이 스레드를 무엇이라 하는가? (한글 또는 영문)","ex":"정답은 메인 스레드(UI 스레드)다.\n💡 개념: 무거운 작업은 백그라운드로, 결과 반영만 메인에서 한다.\n🛠 실무: 코루틴 디스패처나 GCD 큐로 스레드 전환을 명시적으로 관리한다.","a":["메인 스레드","UI 스레드","main thread","ui thread"]}],"th":{"sum":"모바일에서는 프레임 예산, 배터리, 권한이 모두 사용자 경험이자 신뢰의 문제다. 메인 스레드를 비우고, 깨어 있는 시간을 줄이고, 권한은 최소한만 요청해야 한다.","body":[{"h":"프레임 예산","t":"60fps 화면에서는 한 프레임을 그릴 시간이 약 16.7밀리초뿐이고, 120Hz 화면이면 약 8.3밀리초로 줄어든다. 이 예산을 넘기면 프레임을 놓쳐 스크롤이 끊겨 보인다. 레이아웃 중첩을 줄이고 무거운 계산을 프레임 밖으로 빼는 것이 기본이다."},{"h":"메인 스레드는 비워라","t":"UI 갱신은 메인(UI) 스레드에서만 할 수 있으므로 이 스레드가 막히면 화면 전체가 멈춘다. 네트워크, 파일, DB, JSON 파싱, 이미지 디코딩은 백그라운드로 옮긴다. 안드로이드에서 메인 스레드가 오래 막히면 시스템이 ANR 대화상자를 띄운다."},{"h":"배터리를 먹는 것들","t":"화면, 셀룰러 통신, GPS가 대표적인 전력 소비원이다. wake lock을 오래 잡거나 위치를 고정밀로 자주 요청하거나 짧은 주기로 폴링하면 배터리가 빠르게 준다. 작업을 모아서 한 번에 처리(배칭)하고, 폴링 대신 푸시 알림을 쓰고, 정확도가 덜 필요한 곳에서는 저전력 위치를 쓰는 것이 좋다."},{"h":"권한과 최소 수집","t":"안드로이드 6.0(API 23)부터 위험 권한은 실행 중에 요청하고 사용자는 언제든 취소할 수 있으므로, 권한이 없는 경우의 대체 흐름을 항상 준비해야 한다. 권한은 필요한 순간에 이유를 설명하며 요청할 때 승인률이 높다. 수집하는 데이터는 최소화하고 저장·전송 시 보호하며, 스토어의 개인정보 처리방침과 데이터 안전 정보에 정확히 밝혀야 한다."}],"code":{"c":"프레임 예산\n60Hz  -> 1000 / 60  = 약 16.7ms / 프레임\n90Hz  -> 1000 / 90  = 약 11.1ms\n120Hz -> 1000 / 120 = 약 8.3ms\n\n// 나쁜 예: 메인 스레드에서 블로킹 I/O\nval json = URL(url).readText()   // UI 멈춤 -> ANR 위험\n\n// 좋은 예: 백그라운드에서 처리 후 UI 갱신\nval data = withContext(Dispatchers.IO) { api.load() }\nrender(data)","cap":"프레임 예산을 넘기는 작업은 메인 스레드 밖으로 보낸다."},"key":["60fps의 프레임 예산은 약 16.7ms, 120Hz는 약 8.3ms다","메인 스레드에서의 네트워크·디스크 작업은 버벅임과 ANR의 주범이다","위험 권한은 런타임에 요청되고 언제든 취소될 수 있으니 거부 시 흐름을 준비한다"]}},{"t":"배터리와 권한·프라이버시","q":[{"t":"choice","k":"mob-wakelock","q":"백그라운드 동기화를 위해 wake lock을 오래 잡아두면 생기는 문제는?","ex":"wake lock은 기기가 잠들지 못하게 막으므로 오래 잡으면 배터리를 크게 소모한다.\n💡 개념: 시스템 스케줄러에 맡기면 OS가 알아서 적절한 시점에 묶어서 실행한다.\n🛠 실무: 꼭 필요하면 짧게 잡고 finally에서 반드시 해제한다.","o":["네트워크가 느려진다","앱 용량이 커진다","CPU가 계속 깨어 있어 배터리 소모가 급격히 늘고 사용자 불만·강제 종료로 이어진다","권한이 자동 취소된다"],"a":2},{"t":"choice","k":"mob-location-power","q":"지도 앱이 아닌 일반 앱에서 위치를 다룰 때 배터리 친화적인 선택은?","ex":"고정밀 GPS의 잦은 갱신은 대표적인 배터리 소모원이므로 정확도와 주기를 낮추고 필요할 때만 구독한다.\n💡 개념: 대략적 위치로 충분한 기능이 많다.\n🛠 실무: 화면이 사라지면 위치 업데이트 구독을 해제하는 것이 기본이다.","o":["백그라운드에서 상시 위치를 수집한다","항상 최고 정확도로 1초마다 GPS를 갱신한다","위치 권한을 무조건 항상 허용으로 요구한다","필요한 정확도만 요청하고 갱신 주기를 늘리며, 화면이 보일 때만 위치를 받는다"],"a":3},{"t":"choice","k":"mob-runtime-perm","q":"안드로이드 6.0(API 23) 이후 위험 권한 처리에 대한 설명으로 옳은 것은?","ex":"런타임 권한은 사용 시점에 요청하고, 이후에도 사용자가 취소할 수 있어 매 사용 전 확인이 필요하다.\n💡 개념: 오래 쓰지 않은 앱은 시스템이 권한을 자동 회수하기도 한다.\n🛠 실무: 권한이 없을 때의 대체 UX(수동 입력 등)를 반드시 준비한다.","o":["실행 중에 요청하며 사용자가 언제든 설정에서 취소할 수 있으므로 매번 보유 여부를 확인해야 한다","한 번 승인되면 영구히 유지된다","설치 시 한 번에 모두 승인되므로 실행 중 확인이 필요 없다","앱이 코드로 강제 승인할 수 있다"],"a":0},{"t":"choice","k":"mob-perm-timing","q":"카메라 권한을 요청하기 가장 좋은 시점과 방식은?","ex":"맥락이 분명한 순간에 이유와 함께 요청하면 승인률이 높고 사용자 신뢰도 지킬 수 있다.\n💡 개념: 첫 실행 시 권한 폭탄은 거부율을 크게 높인다.\n🛠 실무: 거부당해도 기능 일부는 동작하도록 설계해 이탈을 줄인다.","o":["권한 없이 몰래 카메라를 사용","사용자가 사진 촬영 기능을 누른 순간, 왜 필요한지 설명하며 요청","앱 첫 실행 시 모든 권한을 한꺼번에 요청","사용자가 거부하면 앱을 종료"],"a":1},{"t":"choice","k":"mob-privacy-minimal","q":"모바일 앱의 개인정보 처리 원칙으로 가장 적절한 것은?","ex":"최소 수집과 목적 명시, 보호 조치는 개인정보 보호의 기본 원칙이며 앱 스토어 심사 항목이기도 하다.\n💡 개념: 수집하지 않은 데이터는 유출될 수도 없다.\n🛠 실무: 스토어의 데이터 안전(개인정보 라벨) 항목과 실제 코드 동작이 일치해야 심사를 통과한다.","o":["광고 식별자는 아무 제약 없이 공유해도 된다","나중에 쓸지 모르니 최대한 많이 수집해 둔다","개인정보 처리방침은 필요할 때만 작성한다","목적에 필요한 최소한만 수집하고, 목적과 보관 기간을 명시하며 저장·전송 시 보호한다"],"a":3}],"th":{"sum":"모바일에서는 프레임 예산, 배터리, 권한이 모두 사용자 경험이자 신뢰의 문제다. 메인 스레드를 비우고, 깨어 있는 시간을 줄이고, 권한은 최소한만 요청해야 한다.","body":[{"h":"프레임 예산","t":"60fps 화면에서는 한 프레임을 그릴 시간이 약 16.7밀리초뿐이고, 120Hz 화면이면 약 8.3밀리초로 줄어든다. 이 예산을 넘기면 프레임을 놓쳐 스크롤이 끊겨 보인다. 레이아웃 중첩을 줄이고 무거운 계산을 프레임 밖으로 빼는 것이 기본이다."},{"h":"메인 스레드는 비워라","t":"UI 갱신은 메인(UI) 스레드에서만 할 수 있으므로 이 스레드가 막히면 화면 전체가 멈춘다. 네트워크, 파일, DB, JSON 파싱, 이미지 디코딩은 백그라운드로 옮긴다. 안드로이드에서 메인 스레드가 오래 막히면 시스템이 ANR 대화상자를 띄운다."},{"h":"배터리를 먹는 것들","t":"화면, 셀룰러 통신, GPS가 대표적인 전력 소비원이다. wake lock을 오래 잡거나 위치를 고정밀로 자주 요청하거나 짧은 주기로 폴링하면 배터리가 빠르게 준다. 작업을 모아서 한 번에 처리(배칭)하고, 폴링 대신 푸시 알림을 쓰고, 정확도가 덜 필요한 곳에서는 저전력 위치를 쓰는 것이 좋다."},{"h":"권한과 최소 수집","t":"안드로이드 6.0(API 23)부터 위험 권한은 실행 중에 요청하고 사용자는 언제든 취소할 수 있으므로, 권한이 없는 경우의 대체 흐름을 항상 준비해야 한다. 권한은 필요한 순간에 이유를 설명하며 요청할 때 승인률이 높다. 수집하는 데이터는 최소화하고 저장·전송 시 보호하며, 스토어의 개인정보 처리방침과 데이터 안전 정보에 정확히 밝혀야 한다."}],"code":{"c":"프레임 예산\n60Hz  -> 1000 / 60  = 약 16.7ms / 프레임\n90Hz  -> 1000 / 90  = 약 11.1ms\n120Hz -> 1000 / 120 = 약 8.3ms\n\n// 나쁜 예: 메인 스레드에서 블로킹 I/O\nval json = URL(url).readText()   // UI 멈춤 -> ANR 위험\n\n// 좋은 예: 백그라운드에서 처리 후 UI 갱신\nval data = withContext(Dispatchers.IO) { api.load() }\nrender(data)","cap":"프레임 예산을 넘기는 작업은 메인 스레드 밖으로 보낸다."},"key":["60fps의 프레임 예산은 약 16.7ms, 120Hz는 약 8.3ms다","메인 스레드에서의 네트워크·디스크 작업은 버벅임과 ANR의 주범이다","위험 권한은 런타임에 요청되고 언제든 취소될 수 있으니 거부 시 흐름을 준비한다"]}},{"t":"직접 짜 보기 — 아껴 쓰고, 물어보고 쓰기","th":{"sum":"모바일에서는 **배터리도 자원이고, 사용자의 허락도 자원**이다. 둘 다 함부로 쓰면 앱이 지워진다.","body":[{"h":"깨우는 횟수가 배터리를 먹는다","t":"무선 통신 모듈은 한 번 깨어나면 잠시 켜져 있는다. 1분마다 한 번씩 보내면 하루 종일 깨어 있는 셈이라, 데이터를 모아 뭉쳐 보내는 편이 훨씬 낫다."},{"h":"화면 밖은 그리지 않는다","t":"목록에서 화면에 보이는 것만 그리고 나머지는 재활용한다. 천 개짜리 목록을 다 만들면 메모리와 배터리가 함께 날아간다."},{"h":"권한은 필요한 순간에 이유와 함께","t":"앱을 켜자마자 전부 요구하면 대부분 거절한다. 그 기능을 쓰려는 순간에, 왜 필요한지 보여 주고 물으면 허락률이 크게 오른다."},{"h":"거절을 정상 경로로 다룬다","t":"위치를 거절해도 앱은 동작해야 한다. 직접 입력 같은 대안을 두지 않으면, 한 번 거절한 사용자는 앱을 지운다."}],"code":{"c":"// 나쁨: 1분마다 한 번씩\n// 좋음: 모았다가 15분마다 한 번\n\n권한: 그 기능을 쓰는 순간 + 이유 설명\n거절: 기능만 줄이고 앱은 계속 동작","cap":"깨우지 말고, 미리 묻지 말고"},"key":["깨우는 횟수를 줄인다","권한은 그 순간에 묻는다","거절도 정상 경로다"]},"q":[{"k":"wakeups · 뭉쳐 보내면 몇 번 깨나","cat":"internals","q":"이벤트 개수·묶음 크기를 받아 <b>깨우는 횟수</b>를 돌려주세요. 자투리도 한 번으로 셉니다. 묶음이 1 미만이면 0 입니다.","src":"def wakeups(events, batch):\n    return events\n","sol":"def wakeups(events, batch):\n    if batch < 1:\n        return 0\n    return -(-events // batch)\n","ex":"이벤트마다 보내면 100번 깨우고, 30개씩 묶으면 4번입니다 — 배터리 소모가 스물다섯 배 차이예요. 통신 모듈은 한 번 깨면 잠시 켜져 있기 때문에, 횟수가 곧 비용입니다.","t":"py","tests":[{"in":"wakeups(100, 10)","out":"10"},{"in":"wakeups(100, 30)","out":"4"},{"in":"wakeups(0, 10)","out":"0"}],"edge":[{"in":"wakeups(1, 10)","out":"1"},{"in":"wakeups(10, 0)","out":"0"}]},{"k":"ask_when · 언제 물어볼까","cat":"internals","q":"화면 이름·필요한 권한·이미 가진 권한 집합을 받아, <b>지금 물어야 하면</b> True 를 돌려주세요. 이미 있거나 이 화면에 필요 없으면 False 입니다.","src":"def ask_when(screen, needed, granted):\n    return screen == 'launch'\n","sol":"def ask_when(screen, needed, granted):\n    want = needed.get(screen, set())\n    return bool(want - granted)\n","ex":"앱을 켜자마자 전부 물으면 사용자는 이유를 몰라 거절합니다. 그리고 한 번 거절하면 다시 묻기 어려워요 — 지도 화면에 들어간 순간 물으면 '아, 그래서 필요하구나' 가 되어 허락률이 크게 오릅니다.","t":"py","tests":[{"in":"ask_when('map', {'map': {'location'}}, set())","out":"True"},{"in":"ask_when('map', {'map': {'location'}}, {'location'})","out":"False"},{"in":"ask_when('home', {'map': {'location'}}, set())","out":"False"}],"edge":[{"in":"ask_when('map', {}, set())","out":"False"},{"in":"ask_when('map', {'map': set()}, set())","out":"False"}]},{"k":"on_deny · 거절해도 앱은 돌아간다","cat":"internals","q":"권한 이름과 대체 수단 사전을 받아, 거절되었을 때 <b>쓸 대체 수단</b>을 돌려주세요. 대체가 없으면 <code>None</code> 입니다.","src":"def on_deny(perm, fallbacks):\n    raise PermissionError(perm)\n","sol":"def on_deny(perm, fallbacks):\n    return fallbacks.get(perm)\n","ex":"거절을 예외로 던지면 앱이 그 자리에서 죽습니다. 사용자는 '허락 안 하면 못 쓰는 앱' 으로 여기고 지워요 — 위치를 거절해도 주소를 직접 입력할 수 있으면 앱은 계속 쓸모가 있습니다.","t":"py","tests":[{"in":"on_deny('location', {'location': '직접 입력'})","out":"'직접 입력'"},{"in":"on_deny('camera', {'location': '직접 입력'})","out":"None"},{"in":"on_deny('camera', {'camera': '갤러리에서 고르기'})","out":"'갤러리에서 고르기'"}],"edge":[{"in":"on_deny('x', {})","out":"None"},{"in":"on_deny('location', {'location': None})","out":"None"}]}]}],"ord":4},{"t":"앱을 내보내는 일 — 빌드·서명·출시","g":"🚀","l":[{"t":"출시 I","q":[{"t":"choice","k":"서명 키를 잃어버리면","cat":"ops","q":"앱 서명에 쓰던 키스토어 파일과 비밀번호를 모두 잃어버렸다. 이미 수십만 명이 쓰고 있는 앱이다. 무슨 일이 벌어지는가?","code":"v1.0  ─ 키 A 로 서명 → 스토어 등록\nv1.1  ─ 키 B 로 서명 → 업데이트로 인정되지 않음","o":["같은 키로 서명해야만 업데이트로 인정되므로 <b>그 앱은 더 이상 업데이트할 수 없다</b>. 다른 이름의 새 앱으로 올려 설치 수·리뷰·순위를 처음부터 쌓는 수밖에 없다 — 스토어에 서명 키를 맡기는 방식이 권장되는 이유다","기존 사용자는 그대로 쓸 수 있고 신규 설치만 막히므로, 신규 유입이 없는 앱이면 영향이 없다","스토어에 신분을 증명하면 새 키로 바꿔 준다. 하루 이틀이면 정상화된다","패키지 이름이 같으면 서명이 달라도 업데이트로 인정되므로 새 키를 만들어 그대로 올리면 된다"],"a":0,"ex":"모바일에서 가장 되돌리기 힘든 사고다.\n💡 개념: OS 는 '패키지 이름 + 서명' 을 앱의 신원으로 본다. 서명이 다르면 전혀 다른 앱이라 덮어쓸 수 없고, 사용자가 기존 앱을 지우고 새로 깔아야 하는데 그러면 로컬 데이터도 함께 사라진다.\n🛠 실무: 스토어가 최종 서명 키를 보관하고 개발자는 <b>업로드 키</b>로만 올리는 방식을 쓰면, 업로드 키를 잃어도 재발급받을 수 있다. 자체 서명을 고집한다면 키스토어를 오프라인 백업 두 곳 이상에 두고 비밀번호를 별도 금고에 보관한다."},{"t":"choice","k":"버전 코드와 버전 이름","q":"출시 직후 심각한 버그를 발견해 <b>직전 버전의 빌드를 그대로 다시 올리려</b> 한다. 버전 표기를 어떻게 해야 하는가?","code":"v2.3.0  버전코드 141   ← 방금 올린 것(버그)\nv2.2.9  버전코드 140   ← 되돌리고 싶은 코드","o":["버전 이름만 2.2.9 로 되돌리면 되고 버전 코드는 아무 값이나 상관없다","버전 코드는 <b>반드시 이전보다 커야</b> 하므로 140 을 다시 올릴 수 없다. 옛 소스로 빌드하되 버전 코드를 142 로 올려 <b>새 버전으로</b> 내보낸다 — 사람이 보는 이름은 2.3.1 처럼 붙인다","버전 코드 140 을 그대로 다시 올리면 스토어가 이전 빌드로 되돌려 준다","스토어 콘솔에서 직전 버전을 '활성' 으로 다시 선택하면 이미 업데이트한 사용자도 자동으로 내려간다"],"a":1,"ex":"'롤백' 이라는 말이 앱에서는 사실 '옛 코드로 만든 새 출시' 를 뜻한다.\n💡 개념: 버전 코드(또는 빌드 번호)는 <b>단조 증가하는 정수</b>로 어느 쪽이 새것인지 판단하는 값이고, 버전 이름은 사람에게 보여 주는 문자열일 뿐이다. 둘을 헷갈리면 '올렸는데 업데이트가 안 뜬다' 가 된다.\n🛠 실무: 되돌린 빌드에도 새 버전 코드를 주고, 무엇을 되돌렸는지 릴리스 노트와 태그에 남긴다. 그리고 이미 버그 버전을 받은 사용자는 <b>새 버전을 받기 전까지 계속 버그를 겪는다</b> — 그래서 서버 쪽에서 막을 방법을 먼저 찾는다."},{"t":"choice","k":"최소 지원 버전 정하기","cat":"design","q":"새 기능이 최신 OS API 를 필요로 한다. 최소 지원 OS 버전을 올릴지 판단하는 근거로 가장 적절한 것은?","code":"우리 앱 사용자 OS 분포\n  최신-1 이상 : 88%\n  그 아래     : 12%   ← 이 중 결제 사용자 3%","o":["최소 버전을 올리면 옛 버전 사용자도 자동으로 최신 앱을 받으므로 잃는 사용자는 없다","OS 제조사가 지원을 끝낸 버전은 즉시 끊는 것이 원칙이므로 분포와 무관하게 올린다","전체 시장 점유율이 아니라 <b>우리 앱의 실제 사용자 분포</b>, 그중에서도 매출·핵심 지표에 기여하는 비중을 본다. 12% 를 끊는 결정과 그 안의 결제 사용자 3% 를 잃는 결정은 무게가 다르다","개발 편의가 가장 중요하므로 팀이 다루기 번거로운 버전은 끊는다"],"a":2,"ex":"숫자 하나가 실제 사람 수와 매출로 환산된다.\n💡 개념: 최소 지원 버전을 올리면 그 아래 기기는 <b>스토어에서 업데이트를 받지 못한다</b>. 앱이 지워지지는 않지만 그 버전에 영원히 묶이고, 새 기능도 버그 수정도 닿지 않는다.\n🛠 실무: 끊기 전에 그 구간 사용자에게 '곧 지원이 끝난다' 를 앱 안에서 미리 알리고, 대안이 필요한 기능은 조건 분기로 남겨 둔다. 전체 시장 통계는 참고만 한다 — 앱마다 사용자층이 크게 다르다."},{"t":"choice","k":"앱은 롤백이 없다","q":"서버 배포와 앱 출시의 가장 큰 차이는 무엇이며, 그 차이가 설계에 어떤 영향을 주는가?","code":"서버  배포 → 이상 → 롤백            분 단위\n앱    출시 → 이상 → 수정 → 심사 → 확산   일 단위","o":["앱은 사용자가 항상 최신 버전을 자동으로 받으므로 오히려 서버보다 되돌리기 쉽다","앱은 심사가 있다는 점만 다르고, 심사만 통과하면 서버와 똑같이 즉시 롤백할 수 있다","차이는 배포 속도뿐이며 설계 방식은 서버와 같게 가져가는 것이 옳다","앱은 이미 설치된 버전을 <b>개발자가 회수할 수 없다</b>. 그래서 위험한 기능은 앱에 넣되 <b>서버가 켜고 끌 수 있는 스위치</b> 뒤에 두어, 문제가 생기면 출시 없이 끄도록 설계한다"],"a":3,"ex":"이 한 가지가 모바일 릴리스 관행의 대부분을 설명한다.\n💡 개념: 스토어에서 버전을 내려도 <b>이미 받은 기기에서는 그대로 돈다</b>. 고친 버전을 올려도 사용자가 업데이트해야 반영되고, 자동 업데이트를 꺼 둔 사람도 많다. 즉 '문제 있는 코드가 도는 시간' 을 개발자가 통제하지 못한다.\n🛠 실무: 새 결제 흐름, 새 추천 알고리즘처럼 위험한 것은 원격 스위치 뒤에 두고 꺼진 상태로 출시한다. 켜는 것은 출시가 끝난 뒤 서버에서 천천히 한다 — 문제가 생기면 끄면 끝이다."}],"th":{"sum":"서버는 잘못 올리면 되돌리면 그만입니다. 앱은 다릅니다 — 한 번 사용자 기기에 들어간 버전은 <b>내가 지울 수 없고</b>, 고친 버전이 퍼지는 데는 며칠이 걸립니다. 모바일 배포의 거의 모든 관행이 이 한 가지에서 나옵니다.","body":[{"h":"출시는 되돌릴 수 없다","t":"스토어에서 새 버전을 내려도 <b>이미 받은 사람의 기기에서는 사라지지 않습니다</b>. 서버 배포처럼 '이전 버전으로 롤백' 이라는 것이 없어요. 할 수 있는 건 <b>더 나은 버전을 다시 올려 퍼지기를 기다리는 것</b>뿐이고, 심사까지 끼면 며칠입니다. 그래서 위험한 기능은 앱이 아니라 <b>서버가 켜고 끌 수 있는 스위치</b> 뒤에 둡니다."},{"h":"서명 키가 곧 앱의 신원이다","t":"같은 앱의 업데이트로 인정받으려면 <b>같은 키로 서명</b>되어야 합니다. 키를 잃어버리면 그 앱은 더 이상 업데이트할 수 없고, 이름을 바꿔 새 앱으로 올리는 수밖에 없습니다 — 설치 수도 리뷰도 처음부터입니다. 그래서 요즘은 스토어가 서명 키를 맡아 두고 개발자는 <b>업로드 키</b>만 쓰는 방식을 권합니다."},{"h":"옛 버전은 영원히 남는다","t":"강제 업데이트를 걸지 않는 한, 1년 전 버전을 쓰는 사용자는 계속 있습니다. 서버 API 를 바꿀 때 <b>가장 오래된 지원 버전이 무엇을 보내는지</b>를 기준으로 삼아야 하는 이유이고, 응답에 필드를 <b>더하는 것은 되지만 빼거나 뜻을 바꾸는 것은 안 되는</b> 이유입니다."}],"code":{"t":"서버 배포와 앱 출시의 차이","c":"서버   배포 → 문제 발견 → 롤백          (몇 분)\n앱     출시 → 문제 발견 → 수정 → 심사 → 단계적 확대 → 사용자가 업데이트\n                                                  (며칠 ~ 몇 주)\n\n그래서 앱에서는\n    위험한 코드는 넣되  ─ 서버가 켜고 끄는 스위치 뒤에\n    단계적 출시로       ─ 1% → 5% → 20% → 100%\n    최소 지원 버전은    ─ 서버가 내려 주는 값으로"},"key":["출시는 롤백이 없다 — 더 나은 버전을 다시 퍼뜨리는 것뿐","서명 키를 잃으면 그 앱은 다시는 업데이트할 수 없다","위험한 기능은 서버가 끌 수 있는 스위치 뒤에 둔다","옛 버전은 계속 남는다 — API 는 뒤로 호환되게"]}},{"t":"출시 II","q":[{"t":"choice","k":"단계적 출시","cat":"ops","q":"새 버전을 1% 사용자에게만 먼저 여는 단계적 출시를 하고 있다. 1% 구간에서 <b>반드시 확인해야 할 것</b>과, 문제가 보였을 때 할 수 있는 일은?","code":"1%  →  5%  →  20%  →  50%  →  100%","o":["크래시율·ANR 같은 <b>안정성 지표를 이전 버전과 견주어</b> 본다. 문제가 보이면 확대를 <b>중단</b>해 더 이상 퍼지지 않게 막을 수 있지만, <b>이미 받은 1% 는 되돌릴 수 없다</b>","문제가 보이면 확대를 중단하는 순간 이미 받은 사용자도 이전 버전으로 자동 복구된다","1% 구간에서는 표본이 작아 볼 것이 없으므로 바로 100% 로 올린 뒤 지표를 본다","단계적 출시의 목적은 서버 부하 분산이므로 지표가 아니라 트래픽만 보면 된다"],"a":0,"ex":"단계적 출시는 '되돌리기' 가 아니라 <b>피해 범위를 제한하는 장치</b>다.\n💡 개념: 확대를 멈추면 아직 안 받은 사람은 보호되지만, 이미 받은 사람은 그 버전에 남는다. 그래서 1% 라도 '되돌릴 수 없는 1%' 라고 생각하고 지표를 봐야 한다.\n🛠 실무: 새 버전만의 지표를 버전별로 나눠 보고, 판단할 만큼 표본이 쌓일 때까지 하루 이상 기다린다. 크래시율은 사용자 수 기준으로 보고, 신규 크래시가 하나라도 상위에 올라오면 확대를 멈춘다."},{"t":"choice","k":"강제 업데이트 게이트","cat":"design","q":"보안 문제로 특정 버전 미만은 반드시 업데이트하게 만들어야 한다. 이 장치를 <b>어디에 두어야</b> 하는가?","code":"앱 시작 → 서버에 설정 요청 → { minVersion: 143, message: \"...\" }\n                              현재 버전 &lt; minVersion 이면 차단 화면","o":["스토어의 '강제 업데이트' 설정을 켜면 OS 가 알아서 막아 주므로 앱은 아무것도 하지 않아도 된다","최소 버전을 <b>서버가 내려 주고</b> 앱은 그 값과 자기 버전을 비교한다. 앱에 숫자를 박아 두면 그 판단 자체를 바꾸려고 또 출시해야 하므로 아무 소용이 없다","앱 안에 최소 버전 상수를 박아 두고 빌드할 때마다 갱신한다","푸시 알림으로 업데이트를 안내하는 것으로 충분하며 별도 차단은 과하다"],"a":1,"ex":"'못 쓰게 막는 판단' 을 앱 안에 두면 그 판단을 고칠 방법이 없어진다.\n💡 개념: 강제 업데이트는 되돌릴 수 없는 출시의 유일한 탈출구다. 그런데 기준값을 앱에 박아 두면 기준을 바꾸려고 다시 출시해야 하고, 그 출시가 퍼지는 데 또 며칠이 걸린다. 서버가 값을 쥐고 있어야 즉시 켜고 끌 수 있다.\n🛠 실무: 차단 화면에는 스토어로 가는 버튼과 이유를 함께 보여 준다. 그리고 <b>서버 설정을 못 받았을 때</b>(오프라인, 서버 장애)의 기본 동작을 반드시 정한다 — 보통은 '막지 않음' 이 안전하다. 잘못 막으면 앱 전체가 벽돌이 된다."},{"t":"choice","k":"심사를 기다리는 동안","cat":"ops","q":"마케팅이 정한 기능 공개일이 다음 주 화요일인데, 스토어 심사에 며칠이 걸릴지 알 수 없다. 가장 안전한 계획은?","code":"제출 → 심사(1일? 5일?) → 승인 → 단계적 출시 → 사용자 업데이트\n         ↑ 여기가 예측이 안 된다","o":["공개일에 맞춰 제출하고 심사가 늦어지면 스토어에 긴급 심사를 요청한다","심사 기간을 최대치로 잡아 넉넉히 먼저 제출하고, 승인되는 즉시 100% 로 연다","기능을 <b>꺼진 상태로 미리 넣어</b> 출시해 두고, 공개일에 <b>서버 스위치만 켠다</b>. 심사가 언제 끝나든 공개 시점은 우리가 정한다","기능이 든 버전을 공개일 당일에 올리면 스토어가 그날 자동으로 노출해 준다"],"a":2,"ex":"심사 일정과 공개 일정을 <b>분리</b>하는 것이 핵심이다.\n💡 개념: 심사 기간은 우리가 통제할 수 없는 변수다. 여기에 공개일을 묶으면 매번 도박이 된다. 코드는 미리 사용자 기기에 보내 두고 '언제 보일지' 만 서버가 쥐면, 통제할 수 없는 변수가 일정에서 빠진다.\n🛠 실무: 스위치가 꺼진 상태에서도 앱이 정상 동작하는지 반드시 확인한다. 그리고 켠 뒤 문제가 생기면 바로 끄고, 앱을 다시 올리지 않아도 되도록 되돌리는 경로를 미리 시험해 둔다."},{"t":"choice","k":"옛 버전은 계속 남는다","cat":"design","q":"서버 API 응답에서 더 이상 쓰지 않는 필드를 지우려 한다. 앱에서 특히 조심해야 하는 이유는?","code":"{ \"id\": 1, \"name\": \"A\", \"legacyLabel\": \"구형\" }\n                              ↑ 지워도 될까?","o":["스토어에서 옛 버전을 내리면 그 버전을 쓰는 기기도 함께 동작을 멈추므로 문제가 없다","필드를 지워도 앱은 없는 값을 <code>null</code> 로 받으므로 어떤 앱도 깨지지 않는다","앱은 자동 업데이트가 기본이라 며칠이면 모두 최신이 되므로 일주일만 기다리면 안전하다","강제 업데이트를 걸지 않는 한 <b>1년 전 버전을 쓰는 사용자가 계속 남는다</b>. 그 버전이 이 필드를 필수로 읽고 있으면 필드를 지우는 순간 옛 앱들이 깨진다 — 지원하는 가장 오래된 버전이 무엇을 읽는지가 기준이다"],"a":3,"ex":"서버는 하나지만 그 서버에 붙는 앱은 <b>여러 버전이 동시에</b> 살아 있다.\n💡 개념: 웹은 새로고침하면 최신 코드가 오지만 앱은 아니다. 자동 업데이트를 꺼 둔 사람, 저장 공간이 없어 못 받는 사람, 지원이 끝난 OS 에 묶인 사람이 늘 있다. API 변경은 그 전부를 상대로 하는 일이다.\n🛠 실무: 필드는 <b>더하는 것만</b> 자유롭게 하고, 빼거나 뜻을 바꿀 때는 새 필드를 추가해 옮겨 간 뒤 옛 필드 사용률이 0 에 가까워지면 지운다. 버전별 호출 비율을 계측해 두면 '언제 지워도 되는지' 를 감이 아니라 숫자로 정할 수 있다."}],"th":{"sum":"서버는 잘못 올리면 되돌리면 그만입니다. 앱은 다릅니다 — 한 번 사용자 기기에 들어간 버전은 <b>내가 지울 수 없고</b>, 고친 버전이 퍼지는 데는 며칠이 걸립니다. 모바일 배포의 거의 모든 관행이 이 한 가지에서 나옵니다.","body":[{"h":"출시는 되돌릴 수 없다","t":"스토어에서 새 버전을 내려도 <b>이미 받은 사람의 기기에서는 사라지지 않습니다</b>. 서버 배포처럼 '이전 버전으로 롤백' 이라는 것이 없어요. 할 수 있는 건 <b>더 나은 버전을 다시 올려 퍼지기를 기다리는 것</b>뿐이고, 심사까지 끼면 며칠입니다. 그래서 위험한 기능은 앱이 아니라 <b>서버가 켜고 끌 수 있는 스위치</b> 뒤에 둡니다."},{"h":"서명 키가 곧 앱의 신원이다","t":"같은 앱의 업데이트로 인정받으려면 <b>같은 키로 서명</b>되어야 합니다. 키를 잃어버리면 그 앱은 더 이상 업데이트할 수 없고, 이름을 바꿔 새 앱으로 올리는 수밖에 없습니다 — 설치 수도 리뷰도 처음부터입니다. 그래서 요즘은 스토어가 서명 키를 맡아 두고 개발자는 <b>업로드 키</b>만 쓰는 방식을 권합니다."},{"h":"옛 버전은 영원히 남는다","t":"강제 업데이트를 걸지 않는 한, 1년 전 버전을 쓰는 사용자는 계속 있습니다. 서버 API 를 바꿀 때 <b>가장 오래된 지원 버전이 무엇을 보내는지</b>를 기준으로 삼아야 하는 이유이고, 응답에 필드를 <b>더하는 것은 되지만 빼거나 뜻을 바꾸는 것은 안 되는</b> 이유입니다."}],"code":{"t":"서버 배포와 앱 출시의 차이","c":"서버   배포 → 문제 발견 → 롤백          (몇 분)\n앱     출시 → 문제 발견 → 수정 → 심사 → 단계적 확대 → 사용자가 업데이트\n                                                  (며칠 ~ 몇 주)\n\n그래서 앱에서는\n    위험한 코드는 넣되  ─ 서버가 켜고 끄는 스위치 뒤에\n    단계적 출시로       ─ 1% → 5% → 20% → 100%\n    최소 지원 버전은    ─ 서버가 내려 주는 값으로"},"key":["출시는 롤백이 없다 — 더 나은 버전을 다시 퍼뜨리는 것뿐","서명 키를 잃으면 그 앱은 다시는 업데이트할 수 없다","위험한 기능은 서버가 끌 수 있는 스위치 뒤에 둔다","옛 버전은 계속 남는다 — API 는 뒤로 호환되게"]}},{"t":"출시 III","q":[{"t":"choice","k":"푸시 토큰의 수명","cat":"debug","q":"푸시 발송 성공률이 몇 달에 걸쳐 서서히 떨어지고, 서버 로그에는 '등록되지 않은 토큰' 응답이 쌓인다. 원인과 처리는?","code":"발송 응답\n  200 OK                        88%\n  404 NotRegistered / 410 Gone  12%   ← 계속 증가","o":["푸시 토큰은 <b>영구적이지 않다</b> — 앱 재설치, 데이터 삭제, 기기 복원 등에서 바뀐다. 앱이 켜질 때마다 현재 토큰을 서버에 알리고, <b>무효 응답을 받은 토큰은 서버에서 즉시 지워야</b> 한다","사용자가 알림을 끈 것이므로 앱 안에서 다시 켜 달라고 요청하면 된다","토큰은 한 번 받으면 바뀌지 않으므로 서버에 잘못 저장된 것이며 전체를 다시 받아야 한다","발송량이 늘어 한도에 걸린 것이므로 발송 속도를 낮추면 성공률이 회복된다"],"a":0,"ex":"치우지 않으면 죽은 토큰이 계속 쌓여 지표를 흐린다.\n💡 개념: 토큰은 '이 기기의 이 앱 설치' 를 가리키는 값이라 설치가 바뀌면 무효가 된다. 앱을 지웠다 다시 깐 사용자에게는 새 토큰이 생기고, 옛 토큰은 발송할 때마다 실패로 돌아온다.\n🛠 실무: 앱 시작 시 토큰을 서버에 올려 갱신하고, 발송 응답이 '등록되지 않음' 이면 그 자리에서 삭제한다. 이 정리를 하지 않으면 성공률이 실제 도달률을 반영하지 못해 문제를 늦게 발견한다. <b>알림이 안 보이는 것</b>과 <b>토큰이 죽은 것</b>은 다른 문제이니 지표도 나눠 본다."},{"t":"choice","k":"조용한 푸시는 보장되지 않는다","q":"화면에 표시하지 않고 백그라운드에서 데이터만 갱신하는 '조용한 푸시' 로 실시간 동기화를 구현하려 한다. 설계에서 전제하면 안 되는 것은?","code":"서버 → 조용한 푸시 → 앱이 깨어나 동기화\n                       ↑ 항상 즉시 도착할까?","o":["권한만 허용되어 있으면 배달은 OS 가 보장하므로 재시도 설계는 불필요하다","<b>모든 조용한 푸시가 즉시, 반드시 배달된다</b>고 전제하면 안 된다. OS 는 배터리·사용 패턴에 따라 미루거나 합치거나 아예 버릴 수 있으므로, 놓쳐도 다음 실행 때 따라잡는 <b>보정 동기화</b>가 있어야 한다","배달이 불확실하므로 조용한 푸시는 어떤 경우에도 쓰면 안 된다","조용한 푸시는 화면을 건드리지 않으므로 표시 푸시보다 더 확실하게 배달된다"],"a":1,"ex":"'보통은 온다' 와 '항상 온다' 사이의 차이가 버그가 된다.\n💡 개념: 표시되는 알림과 달리 조용한 푸시는 사용자에게 보이지 않으므로 OS 가 배터리를 위해 조절할 여지가 크다. 자주 안 쓰는 앱일수록, 절전 모드일수록 더 미뤄진다.\n🛠 실무: 푸시는 <b>'지금 갱신하면 좋다' 는 힌트</b>로만 쓰고, 정확성은 앱이 앞으로 올 때 하는 동기화로 보장한다. 푸시에 데이터를 통째로 싣기보다 '무엇이 바뀌었다' 만 보내고 실제 값은 앱이 서버에서 가져오게 하면, 놓쳐도 결과가 어긋나지 않는다."},{"t":"choice","k":"링크가 앱으로 열리려면","cat":"ops","q":"우리 도메인 주소를 눌렀을 때 브라우저 대신 앱이 열리게 하려 한다. 단순히 앱에 해당 주소 패턴을 등록하는 것만으로 부족한 이유는?","code":"https://example.com/order/123  →  앱으로?  브라우저로?","o":["패턴 등록만으로 충분하며, 열리지 않는다면 앱을 다시 설치하면 해결된다","스토어에 도메인을 등록하는 별도 심사 절차를 거쳐야 한다","아무 앱이나 남의 도메인을 가로채지 못하도록, OS 가 <b>그 도메인의 서버에 놓인 검증 파일</b>을 확인해 앱과 도메인의 소유 관계를 확인한다. 이 파일이 없거나 지문이 어긋나면 그냥 브라우저로 열린다","사용자가 설정에서 기본 앱을 직접 지정하는 방법밖에 없다"],"a":2,"ex":"검증이 없으면 아무 앱이나 은행 주소를 가로챌 수 있다.\n💡 개념: OS 는 앱이 주장하는 도메인을 그대로 믿지 않는다. 그 도메인의 정해진 경로에 놓인 파일에 <b>앱의 패키지 이름과 서명 지문</b>이 적혀 있어야 연결을 인정한다. 즉 도메인 서버를 통제하는 쪽만 그 도메인의 링크를 가져갈 수 있다.\n🛠 실무: 서명 지문은 <b>실제 출시에 쓰이는 키</b>의 것이어야 한다 — 스토어가 재서명하는 방식이라면 스토어가 알려 주는 지문을 넣어야 하고, 디버그 키 지문만 넣어 두면 개발 중에는 되고 출시 후에 안 된다. 파일이 리다이렉트 없이 그대로 응답되는지도 확인한다."},{"t":"choice","k":"링크로 들어온 사용자의 뒤로 가기","cat":"debug","q":"알림을 눌러 주문 상세 화면으로 바로 들어온 사용자가 뒤로 가기를 누르면 <b>앱이 그대로 종료된다</b>는 제보가 온다. 무엇이 빠졌는가?","code":"정상 진입:  홈 → 주문목록 → 주문상세   (뒤로 = 주문목록)\n링크 진입:  주문상세                   (뒤로 = 종료)","o":["상세 화면을 새 작업으로 띄우지 말고 브라우저로 열면 자연스럽게 해결된다","뒤로 가기 버튼을 가로채 항상 홈으로 보내면 해결된다 — 스택은 건드릴 필요가 없다","알림에서 여는 화면은 원래 종료되는 것이 표준 동작이므로 고칠 것이 없다","링크로 바로 진입하면 화면 스택에 그 화면 하나만 쌓인다. 상세로 보낼 때 <b>홈·목록 같은 상위 화면을 함께 스택에 만들어 주어야</b> 뒤로 가기가 앱 안에서 자연스럽게 이어진다"],"a":3,"ex":"링크로 들어온 사용자는 <b>앱을 처음 여는 사용자</b>이기도 하다.\n💡 개념: 뒤로 가기는 화면 스택을 하나씩 걷어 내는 동작이다. 스택에 하나뿐이면 걷어 낼 것이 없어 앱이 닫힌다. 정상 경로로 들어온 사람과 같은 경험을 주려면 그 경로에 있었을 화면들을 만들어 줘야 한다.\n🛠 실무: 플랫폼마다 상위 화면 스택을 만들어 주는 방법이 있다. 뒤로 가기를 가로채 홈으로 보내는 방식은 한 단계는 해결되지만 그다음 뒤로 가기에서 다시 종료되고, 여러 단계 깊은 화면에서는 맥락이 어긋난다. 알림·검색·공유 등 <b>바깥에서 들어오는 모든 경로</b>를 같은 방식으로 처리한다."}],"th":{"sum":"서버는 잘못 올리면 되돌리면 그만입니다. 앱은 다릅니다 — 한 번 사용자 기기에 들어간 버전은 <b>내가 지울 수 없고</b>, 고친 버전이 퍼지는 데는 며칠이 걸립니다. 모바일 배포의 거의 모든 관행이 이 한 가지에서 나옵니다.","body":[{"h":"출시는 되돌릴 수 없다","t":"스토어에서 새 버전을 내려도 <b>이미 받은 사람의 기기에서는 사라지지 않습니다</b>. 서버 배포처럼 '이전 버전으로 롤백' 이라는 것이 없어요. 할 수 있는 건 <b>더 나은 버전을 다시 올려 퍼지기를 기다리는 것</b>뿐이고, 심사까지 끼면 며칠입니다. 그래서 위험한 기능은 앱이 아니라 <b>서버가 켜고 끌 수 있는 스위치</b> 뒤에 둡니다."},{"h":"서명 키가 곧 앱의 신원이다","t":"같은 앱의 업데이트로 인정받으려면 <b>같은 키로 서명</b>되어야 합니다. 키를 잃어버리면 그 앱은 더 이상 업데이트할 수 없고, 이름을 바꿔 새 앱으로 올리는 수밖에 없습니다 — 설치 수도 리뷰도 처음부터입니다. 그래서 요즘은 스토어가 서명 키를 맡아 두고 개발자는 <b>업로드 키</b>만 쓰는 방식을 권합니다."},{"h":"옛 버전은 영원히 남는다","t":"강제 업데이트를 걸지 않는 한, 1년 전 버전을 쓰는 사용자는 계속 있습니다. 서버 API 를 바꿀 때 <b>가장 오래된 지원 버전이 무엇을 보내는지</b>를 기준으로 삼아야 하는 이유이고, 응답에 필드를 <b>더하는 것은 되지만 빼거나 뜻을 바꾸는 것은 안 되는</b> 이유입니다."}],"code":{"t":"서버 배포와 앱 출시의 차이","c":"서버   배포 → 문제 발견 → 롤백          (몇 분)\n앱     출시 → 문제 발견 → 수정 → 심사 → 단계적 확대 → 사용자가 업데이트\n                                                  (며칠 ~ 몇 주)\n\n그래서 앱에서는\n    위험한 코드는 넣되  ─ 서버가 켜고 끄는 스위치 뒤에\n    단계적 출시로       ─ 1% → 5% → 20% → 100%\n    최소 지원 버전은    ─ 서버가 내려 주는 값으로"},"key":["출시는 롤백이 없다 — 더 나은 버전을 다시 퍼뜨리는 것뿐","서명 키를 잃으면 그 앱은 다시는 업데이트할 수 없다","위험한 기능은 서버가 끌 수 있는 스위치 뒤에 둔다","옛 버전은 계속 남는다 — API 는 뒤로 호환되게"]}},{"t":"출시 IV","q":[{"t":"choice","k":"읽을 수 없는 크래시 스택","cat":"debug","q":"출시 뒤 크래시 리포트를 열었더니 스택이 <code>a.b.c(Unknown Source)</code> 처럼 알아볼 수 없는 이름뿐이다. 원인과 해결은?","code":"at a.b.c(Unknown Source:12)\nat a.b.d(Unknown Source:3)","o":["릴리스 빌드가 이름을 짧게 바꿔 두었기 때문이다. 빌드할 때 나오는 <b>매핑 파일을 크래시 수집 도구에 함께 올려야</b> 원래 이름으로 복원된다 — 매핑 파일은 빌드마다 다르므로 <b>그 빌드의 것</b>이어야 한다","릴리스 빌드에서는 원래 스택을 알 수 없으므로 디버그 빌드로 재현하는 수밖에 없다","난독화를 끄는 것이 유일한 해결책이며, 앱 크기가 커지는 것은 감수해야 한다","크래시 도구의 버전이 낮아서이며 도구를 최신으로 올리면 자동으로 복원된다"],"a":0,"ex":"매핑 파일을 잃으면 <b>그 버전의 크래시는 영원히 읽을 수 없다</b>.\n💡 개념: 릴리스 빌드는 앱을 줄이려고 클래스·메서드 이름을 짧은 문자로 바꾼다. 매핑 파일은 '바뀐 이름 ↔ 원래 이름' 대응표이고, 빌드할 때마다 새로 만들어지므로 다른 빌드의 것으로는 복원되지 않는다.\n🛠 실무: 매핑 파일 업로드를 <b>빌드 파이프라인에 자동으로</b> 넣는다. 사람이 기억해서 올리는 방식은 반드시 언젠가 빠진다. 네이티브 코드가 있다면 디버그 심볼도 같은 방식으로 올린다. 매핑 파일은 버전별로 보관한다 — 몇 달 전 버전의 크래시가 지금 올라오기도 한다."},{"t":"choice","k":"크래시율을 무엇으로 세나","q":"'크래시율 0.5%' 라는 숫자를 볼 때, <b>세션 기준</b>과 <b>사용자 기준</b> 중 어느 쪽을 함께 봐야 하며 그 이유는?","code":"세션 기준  : 크래시 세션 수 / 전체 세션 수\n사용자 기준: 크래시 겪은 사용자 수 / 전체 사용자 수","o":["사용자 기준만 보면 된다. 세션 기준은 헤비 유저 때문에 언제나 부정확하다","둘 다 봐야 한다. 한 사람이 반복해서 겪는 크래시는 <b>세션 기준을 크게 부풀리지만 사용자 기준은 작게</b> 나오고, 넓게 얕게 퍼진 크래시는 반대다 — 두 값의 차이 자체가 문제의 성격을 알려 준다","세션 기준만 보면 된다. 사용자 기준은 같은 정보를 다르게 표현한 것뿐이다","두 값은 항상 비슷하게 나오므로 편한 쪽 하나만 보면 된다"],"a":1,"ex":"같은 0.5% 가 전혀 다른 상황일 수 있다.\n💡 개념: 특정 기기에서만 켤 때마다 죽는 버그는 사용자 수로는 1% 인데 세션 수로는 훨씬 높게 잡힌다. 반대로 드물게 아무에게나 한 번씩 나는 버그는 사용자 기준이 더 높게 나온다. 앞의 것은 그 사용자에게 <b>앱이 아예 못 쓰는 상태</b>이므로 숫자보다 심각하다.\n🛠 실무: 두 지표를 나란히 두고, 기기·OS 버전·앱 버전으로 쪼개 본다. 전체 평균은 특정 집단에서 벌어지는 심각한 문제를 가려 버린다."},{"t":"choice","k":"실험실 수치와 실제 수치","cat":"ops","q":"테스트 기기에서 앱 시작 시간은 늘 1.2초인데, 필드 지표에서는 상위 10% 사용자가 6초를 넘긴다. 이 차이를 어떻게 다뤄야 하는가?","code":"실험실  : 최신 기기 · 안정된 와이파이 · 캐시 예열됨\n실제    : 3년 된 보급형 · 불안정한 셀룰러 · 첫 실행","o":["평균값이 기준이므로 평균이 목표 안에 들면 상위 백분위는 신경 쓰지 않아도 된다","실제 기기를 모두 갖출 수 없으므로 필드 지표는 참고만 하고 실험실 수치로 목표를 정한다","실험실 수치는 <b>회귀를 잡는 데</b> 쓰고, 판단은 <b>실제 사용자 분포의 상위 백분위</b>로 한다. 평균이 아니라 느린 쪽 꼬리가 이탈과 직결되므로, 느린 기기·첫 실행 조건을 따로 재현해 개선 대상을 찾는다","테스트 기기 수치가 정확하므로 필드 지표의 상위 10% 는 측정 오류로 보고 무시한다"],"a":2,"ex":"개발자의 기기는 사용자의 기기 중 가장 빠른 축에 속한다.\n💡 개념: 실험실 측정은 조건이 고정되어 있어 <b>바뀌었는지</b>를 보기에 좋다. 하지만 실제 사용자는 기기·네트워크·저장 공간·백그라운드 앱이 제각각이라, 무엇을 고쳐야 하는지는 필드 분포에서만 보인다.\n🛠 실무: p50 이 아니라 p90·p95 를 목표로 잡고, 느린 구간을 기기 등급·OS·첫 실행 여부로 쪼개 원인을 좁힌다. 스토어도 이런 필드 지표를 품질 신호로 쓰므로 노출에도 영향을 준다."},{"t":"choice","k":"모바일에서 원격 스위치가 특히 중요한 이유","cat":"design","q":"서버에도 기능 플래그가 있지만, 모바일에서 원격 스위치가 <b>훨씬 더</b> 중요하게 다뤄지는 이유는?","code":"서버: 플래그 없이도 롤백 가능 → 플래그는 편의\n앱  : 롤백 불가            → 플래그가 사실상 유일한 되돌리기 수단","o":["모바일은 사용자 수가 많아 트래픽 조절이 필요하기 때문이다","모바일은 A/B 테스트를 서버보다 자주 하기 때문이며 안정성과는 무관하다","앱 스토어가 기능 플래그 사용을 심사 조건으로 요구하기 때문이다","서버는 플래그가 없어도 롤백이라는 되돌리기 수단이 있지만, 앱은 <b>플래그가 사실상 유일한 되돌리기 수단</b>이다. 스위치 뒤에 두지 않은 기능은 문제가 생겨도 새 버전이 퍼질 때까지 끌 방법이 없다"],"a":3,"ex":"서버에서 플래그는 있으면 좋은 것이고, 앱에서는 <b>없으면 안 되는 것</b>이다.\n💡 개념: 되돌리기 수단이 하나뿐이라는 것은 그 하나가 매우 튼튼해야 한다는 뜻이다. 스위치를 읽는 코드 자체가 실패하거나, 값을 못 받았을 때 기본값이 '켬' 이면 되돌리기가 작동하지 않는다.\n🛠 실무: 값을 못 받았을 때의 기본값은 <b>안전한 쪽(꺼짐)</b>으로 두고, 마지막에 받은 값을 캐시해 오프라인에서도 판단이 서게 한다. 스위치를 끄는 경로를 실제로 한 번 시험해 보고 출시한다 — 급할 때 처음 눌러 보는 버튼은 대개 작동하지 않는다."}],"th":{"sum":"서버는 잘못 올리면 되돌리면 그만입니다. 앱은 다릅니다 — 한 번 사용자 기기에 들어간 버전은 <b>내가 지울 수 없고</b>, 고친 버전이 퍼지는 데는 며칠이 걸립니다. 모바일 배포의 거의 모든 관행이 이 한 가지에서 나옵니다.","body":[{"h":"출시는 되돌릴 수 없다","t":"스토어에서 새 버전을 내려도 <b>이미 받은 사람의 기기에서는 사라지지 않습니다</b>. 서버 배포처럼 '이전 버전으로 롤백' 이라는 것이 없어요. 할 수 있는 건 <b>더 나은 버전을 다시 올려 퍼지기를 기다리는 것</b>뿐이고, 심사까지 끼면 며칠입니다. 그래서 위험한 기능은 앱이 아니라 <b>서버가 켜고 끌 수 있는 스위치</b> 뒤에 둡니다."},{"h":"서명 키가 곧 앱의 신원이다","t":"같은 앱의 업데이트로 인정받으려면 <b>같은 키로 서명</b>되어야 합니다. 키를 잃어버리면 그 앱은 더 이상 업데이트할 수 없고, 이름을 바꿔 새 앱으로 올리는 수밖에 없습니다 — 설치 수도 리뷰도 처음부터입니다. 그래서 요즘은 스토어가 서명 키를 맡아 두고 개발자는 <b>업로드 키</b>만 쓰는 방식을 권합니다."},{"h":"옛 버전은 영원히 남는다","t":"강제 업데이트를 걸지 않는 한, 1년 전 버전을 쓰는 사용자는 계속 있습니다. 서버 API 를 바꿀 때 <b>가장 오래된 지원 버전이 무엇을 보내는지</b>를 기준으로 삼아야 하는 이유이고, 응답에 필드를 <b>더하는 것은 되지만 빼거나 뜻을 바꾸는 것은 안 되는</b> 이유입니다."}],"code":{"t":"서버 배포와 앱 출시의 차이","c":"서버   배포 → 문제 발견 → 롤백          (몇 분)\n앱     출시 → 문제 발견 → 수정 → 심사 → 단계적 확대 → 사용자가 업데이트\n                                                  (며칠 ~ 몇 주)\n\n그래서 앱에서는\n    위험한 코드는 넣되  ─ 서버가 켜고 끄는 스위치 뒤에\n    단계적 출시로       ─ 1% → 5% → 20% → 100%\n    최소 지원 버전은    ─ 서버가 내려 주는 값으로"},"key":["출시는 롤백이 없다 — 더 나은 버전을 다시 퍼뜨리는 것뿐","서명 키를 잃으면 그 앱은 다시는 업데이트할 수 없다","위험한 기능은 서버가 끌 수 있는 스위치 뒤에 둔다","옛 버전은 계속 남는다 — API 는 뒤로 호환되게"]}}],"ord":6},{"t":"손안의 화면을 만드는 일 — 레이아웃·접근성·입력","g":"📱","l":[{"t":"화면 만들기 I","q":[{"t":"choice","k":"픽셀로 잡으면","cat":"debug","q":"버튼 높이를 <b>48픽셀</b>로 고정했더니 어떤 기기에서는 적당하고 어떤 기기에서는 너무 작아 누르기 힘들다. 원인은?","code":"48px 을 밀도별로 환산하면\n  ×1  → 48dp   적당\n  ×3  → 16dp   너무 작다","o":["기기마다 <b>1인치에 들어가는 픽셀 수</b>가 달라 같은 픽셀 수가 다른 물리적 크기가 되기 때문이다. 밀도 독립 단위로 잡아 시스템이 배율을 곱하게 해야 한다","기기마다 화면 비율이 달라서이며 비율을 고정하면 해결된다","픽셀 단위는 세로 모드에서만 유효하기 때문이다","고밀도 화면은 렌더링이 느려 버튼이 작게 그려지는 것이다"],"a":0,"ex":"모바일에서 픽셀을 직접 쓰면 거의 항상 이 문제를 만난다.\n💡 개념: 배율이 3인 화면에서 48픽셀은 밀도 독립 단위로 16 이다. 손가락으로 누르기에는 턱없이 작다. 밀도 독립 단위로 적으면 시스템이 기기 배율을 곱해 주므로 <b>물리적 크기가 어디서나 비슷</b>해진다.\n🛠 실무: 이미지도 같은 이유로 배율별 자산이 필요하다 — 하나만 넣으면 고밀도 화면에서 흐릿해진다. 벡터로 그릴 수 있는 아이콘은 벡터로 두는 것이 자산 개수를 줄이는 가장 쉬운 방법이다."},{"t":"choice","k":"가려지는 가장자리","cat":"design","q":"화면 맨 아래에 버튼을 붙였더니 일부 기기에서 <b>홈 제스처 영역과 겹쳐</b> 누르기 어렵다는 제보가 온다. 어떻게 다뤄야 하는가?","code":"화면 전체 영역\n  ├ 상단: 상태 표시줄 · 노치\n  ├ 가운데: 안전 영역\n  └ 하단: 홈 표시줄 · 제스처 영역","o":["가로 모드에서만 생기는 문제라 세로 모드로 고정하면 된다","기기가 알려 주는 <b>안전 영역</b> 안쪽에 내용을 배치한다 — 값은 기기와 방향에 따라 달라지므로 숫자를 직접 박지 말고 시스템이 주는 여백을 받아 쓴다","전체 화면 모드를 켜면 겹침이 사라진다","하단 여백을 20 정도로 고정해 두면 대부분의 기기에서 맞는다"],"a":1,"ex":"노치와 홈 제스처가 생긴 뒤로 '화면 끝 = 쓸 수 있는 끝' 이 아니게 됐다.\n💡 개념: 안전 영역은 <b>가려지거나 시스템이 쓰는 부분을 뺀 영역</b>이다. 노치 모양, 홈 표시줄 유무, 화면 방향에 따라 달라지므로 고정값으로 맞출 수 없다. 시스템이 알려 주는 여백을 그대로 반영해야 한다.\n🛠 실무: 배경은 화면 끝까지 채우되 <b>내용과 조작 요소만 안전 영역 안</b>에 두는 것이 보통이다. 그러면 가장자리까지 시원해 보이면서도 눌리는 것은 다 눌린다. 여러 기기 크기에서 확인하는 것 말고 대안이 없다."},{"t":"choice","k":"화면이 넓어지면","cat":"design","q":"폰용 화면을 태블릿에서 그대로 띄웠더니 <b>글이 화면 폭 전체로 늘어나</b> 읽기 힘들다. 무엇이 잘못됐는가?","code":"폰    ▮▮▮▮        한 줄 35자\n태블릿 ▮▮▮▮▮▮▮▮▮▮▮  한 줄 110자","o":["글꼴 크기를 화면 폭에 비례해 키우면 해결된다","태블릿에서는 가로 모드를 막으면 해결된다","폭에 맞춰 늘리기만 했기 때문이다. 글은 <b>한 줄 길이에 읽기 좋은 상한</b>이 있으므로, 넓어지면 늘리는 대신 <b>최대 폭을 두고 가운데 정렬하거나 단을 나누는</b> 식으로 배치를 바꿔야 한다","태블릿용 화면을 따로 만드는 것 말고는 방법이 없다"],"a":2,"ex":"'늘리기' 와 '다시 배치하기' 는 다른 일이다.\n💡 개념: 한 줄이 너무 길면 눈이 다음 줄 첫머리를 찾기 어려워 읽기가 힘들어진다. 그래서 넓은 화면에서는 폭을 제한하거나, 남는 공간에 <b>목록과 상세를 나란히</b> 놓는 식으로 정보를 더 보여 주는 쪽이 낫다.\n🛠 실무: 기기 종류로 갈라 판단하기보다 <b>지금 쓸 수 있는 폭</b>으로 판단하는 편이 안전하다 — 폴더블은 접었다 펴면 폭이 바뀌고, 태블릿에서도 화면을 반으로 나눠 쓰는 경우가 있다."},{"t":"choice","k":"어두운 화면 만들기","cat":"review","q":"다크 모드를 만들면서 밝은 화면의 <b>색을 그대로 반전</b>했다. 무엇이 문제인가?","code":"흰 배경 → 검은 배경   (괜찮다)\n검은 글씨 → 흰 글씨   (괜찮다)\n브랜드 파랑 → 반전된 주황?  ← ?","o":["다크 모드는 배경만 바꾸고 글자색은 그대로 두는 것이 표준이다","반전은 올바른 방법이며 대비만 다시 확인하면 된다","이미지까지 자동으로 반전되므로 이미지만 예외 처리하면 된다","반전은 <b>색이 가진 뜻을 망가뜨린다</b> — 경고의 빨강이나 브랜드 색이 엉뚱한 색이 되고, 대비도 다시 계산해야 한다. 색을 뒤집는 대신 <b>역할별로 두 벌의 색</b>을 정의해 두고 갈아 끼워야 한다"],"a":3,"ex":"다크 모드는 '어둡게 하기' 가 아니라 <b>두 번째 배색을 만드는 일</b>이다.\n💡 개념: 색에는 역할이 있다 — 배경, 표면, 본문, 보조 텍스트, 강조, 위험. 역할마다 밝은 모드 값과 어두운 모드 값을 정해 두면 화면 코드는 역할 이름만 쓰면 된다. 반전은 이 역할을 무시하고 수치만 뒤집는 것이다.\n🛠 실무: 어두운 배경에서는 <b>순수한 검정보다 살짝 밝은 회색</b>이 눈이 덜 피로하고, 그림자 대신 밝기 차이로 층을 표현한다. 그리고 두 모드 모두에서 대비를 다시 재야 한다 — 밝은 모드에서 충분했던 회색이 어두운 배경에서는 잘 안 보인다."}],"th":{"sum":"모바일 화면은 <b>내 기기 하나</b>가 아닙니다. 화면 크기도 밀도도 글꼴 크기도 사용자마다 다르고, 손가락은 마우스보다 훨씬 뭉툭해요. 개발 기기에서만 맞는 화면은 <b>거의 모두에게 조금씩 어긋납니다</b>.","body":[{"h":"픽셀이 아니라 밀도 독립 단위로","t":"같은 <b>100픽셀</b>이 어떤 기기에서는 손톱만 하고 어떤 기기에서는 손가락만 합니다. 화면마다 1인치에 들어가는 픽셀 수가 다르기 때문이에요. 그래서 <b>밀도와 무관한 단위</b>로 크기를 잡고, 시스템이 기기 배율을 곱해 실제 픽셀로 바꾸게 둡니다. 이미지도 배율별로 준비해야 흐릿해지지 않습니다."},{"h":"손가락은 커서가 아니다","t":"마우스는 1픽셀을 정확히 찍지만 손가락 끝은 <b>지름 1cm 쯤 되는 뭉툭한 원</b>입니다. 그래서 누를 수 있는 영역은 눈에 보이는 아이콘보다 커야 하고, 서로 다른 동작 사이에는 간격이 있어야 해요. 특히 <b>되돌릴 수 없는 동작</b>을 자주 누르는 버튼 옆에 두면 사고가 납니다."},{"h":"내 설정이 모두의 설정은 아니다","t":"글꼴을 크게 쓰는 사람, 색을 잘 구분하지 못하는 사람, 화면을 못 보고 소리로 듣는 사람이 있습니다. 이들을 위한 대응은 <b>따로 만드는 화면이 아니라</b> 원래 화면이 늘어나고 읽히게 만드는 일이에요 — 대개 <b>고정 크기를 쓰지 않는 것</b>에서 절반이 해결됩니다."}],"code":{"t":"같은 48, 다른 결과","c":"화면 밀도별 실제 픽셀 (1dp = 1px × 배율)\n    mdpi  ×1     48dp →  48px\n    hdpi  ×1.5   48dp →  72px\n    xhdpi ×2     48dp →  96px\n    xxhdpi ×3    48dp → 144px\n\n픽셀로 잡으면\n    48px 은 xxhdpi 에서 16dp — 손가락으로 누를 수 없다\n\n권장 최소 터치 영역\n    안드로이드 48dp · iOS 44pt   (보이는 아이콘은 더 작아도 된다)"},"key":["크기는 픽셀이 아니라 밀도 독립 단위로 잡는다","누를 수 있는 영역은 보이는 아이콘보다 크게","고정 크기를 쓰지 않으면 접근성 문제의 절반이 사라진다","색만으로 정보를 전달하지 않는다"]}},{"t":"화면 만들기 II","q":[{"t":"choice","k":"누를 수 있는 크기","q":"아이콘 버튼을 24 크기로 그렸다. 누르기 좋게 만들려면?","code":"보이는 아이콘  24\n권장 최소 터치 영역  안드로이드 48dp · iOS 44pt","o":["아이콘은 24 그대로 두고 <b>누를 수 있는 영역만 48 안팎으로 넓힌다</b> — 보이는 크기와 눌리는 크기는 달라도 되고, 아이콘을 키우면 화면이 답답해진다","버튼 주위에 테두리를 그려 시각적으로 크게 보이게 하면 된다","24 로도 충분하며 사용자가 정확히 누르면 된다","아이콘 자체를 48 로 키워야 한다"],"a":0,"ex":"'보이는 것' 과 '눌리는 것' 을 분리하는 것이 요령이다.\n💡 개념: 손가락 끝이 닿는 면적은 지름 1cm 쯤 된다. 그보다 작은 영역은 조준이 필요해지고, 조준은 사용자를 지치게 한다. 아이콘 주위에 보이지 않는 여백을 둬서 영역만 넓히면 화면 밀도를 해치지 않고 해결된다.\n🛠 실무: 영역을 넓힐 때 <b>옆 버튼과 겹치지 않는지</b>도 봐야 한다 — 겹치면 어느 쪽이 눌릴지 예측할 수 없다. 목록 행 전체를 누를 수 있게 하는 것도 같은 발상이고, 이 경우 행 안의 작은 버튼과 우선순위를 정해 둬야 한다."},{"t":"choice","k":"누르는 도중에 마음이 바뀌면","cat":"design","q":"버튼을 <b>누르는 순간</b> 동작을 실행하도록 만들었더니 '잘못 눌렀는데 취소가 안 된다' 는 제보가 온다. 표준적인 처리는?","code":"손가락 내려놓음 → ? → 손가락 뗌","o":["확인 대화상자를 항상 띄워 취소할 수 있게 한다","누른 순간에는 <b>눌렸다는 표시만</b> 하고, 손가락을 <b>버튼 안에서 뗐을 때</b> 실행한다 — 밖으로 끌고 나가 떼면 취소되므로 사용자가 마음을 바꿀 수 있다","실행 후 되돌리기 버튼을 제공하는 것 말고는 방법이 없다","누르는 순간 바로 실행하는 것이 반응이 빨라 더 좋은 방식이다"],"a":1,"ex":"누르는 순간과 떼는 순간 사이가 <b>사용자에게 주어진 취소 기회</b>다.\n💡 개념: 손가락은 뭉툭해서 옆 버튼을 잘못 짚는 일이 잦다. 뗄 때 실행하는 규칙이 있으면 잘못 짚었을 때 손가락을 밀어 빼는 것만으로 취소된다. 눌린 표시는 즉시 보여 줘야 반응이 느리다는 느낌이 안 든다.\n🛠 실무: 기본 버튼 컴포넌트는 대개 이렇게 되어 있다 — 직접 터치 이벤트를 다루기 시작할 때 깨진다. 스크롤 목록 안에서는 <b>살짝 움직이면 스크롤로 넘겨야</b> 하므로, 일정 거리 이상 움직이면 누름을 취소하는 처리도 함께 필요하다."},{"t":"choice","k":"스크롤 안의 스크롤","cat":"debug","q":"세로 스크롤 목록 안에 가로로 넘기는 카드를 넣었더니, 카드를 넘기려 할 때 <b>세로 스크롤이 먼저 반응</b>해 답답하다. 어떻게 다루는가?","code":"세로 목록 ↕\n  └ 가로 카드 ↔   ← 어느 쪽이 제스처를 가져갈까","o":["안쪽 카드의 스크롤을 끄고 좌우 버튼으로만 넘기게 한다","제스처 충돌은 운영체제가 알아서 처리하므로 코드로 다룰 수 없다","처음 움직인 <b>방향을 보고 누가 가져갈지 정한다</b> — 가로로 충분히 움직였으면 안쪽이, 세로면 바깥이 가져가고, 한 번 정해지면 그 제스처가 끝날 때까지 유지한다","바깥 목록의 스크롤을 카드 위에서만 잠시 끈다"],"a":2,"ex":"중첩 스크롤은 '누가 먼저 잡느냐' 를 정하는 문제다.\n💡 개념: 손가락이 움직이기 시작한 방향을 몇 픽셀만 보면 의도를 알 수 있다. 방향이 정해진 뒤에는 흔들려도 바꾸지 않아야 한다 — 중간에 주인이 바뀌면 화면이 튄다.\n🛠 실무: 대부분의 UI 프레임워크가 이 판정을 제공하므로 <b>직접 구현하기 전에 있는 것을 먼저 찾는다</b>. 그리고 같은 방향의 스크롤을 중첩하는 것(세로 안에 세로)은 되도록 피한다 — 규칙을 어떻게 정해도 사용자가 예측하기 어렵다."},{"t":"choice","k":"위험한 버튼의 자리","cat":"design","q":"목록의 각 행 오른쪽 끝에 <b>삭제</b> 버튼을 두었다. 실수로 삭제했다는 제보가 잦다. 무엇을 고쳐야 하는가?","code":"[  항목 이름            ]  [열기]  [삭제]\n                              ↑ 자주 누름  ↑ 되돌릴 수 없음","o":["삭제할 때마다 확인 대화상자를 띄우는 것이 언제나 최선이다","삭제 버튼을 빨간색으로 칠하면 실수가 사라진다","목록에서는 삭제 기능을 제공하지 않는 것이 원칙이다","되돌릴 수 없는 동작을 <b>자주 누르는 버튼 바로 옆</b>에 둔 것이 문제다 — 자리를 떼어 놓거나, 한 단계 안으로 숨기거나, 즉시 지우는 대신 <b>되돌리기를 몇 초 제공</b>한다"],"a":3,"ex":"실수는 사용자의 부주의가 아니라 <b>배치의 결과</b>인 경우가 많다.\n💡 개념: 손가락은 정확하지 않고 목록은 빠르게 훑는 화면이다. 자주 하는 동작과 되돌릴 수 없는 동작이 붙어 있으면 일정 비율로 반드시 사고가 난다.\n🛠 실무: 확인 대화상자는 몇 번 지나면 <b>읽지 않고 누르게</b> 되어 효과가 급격히 준다. 그보다 '지웠습니다 · 되돌리기' 를 몇 초 보여 주는 편이 실수도 막고 흐름도 안 끊는다. 정말 위험한 동작에만 확인을 남기고, 그때는 무엇이 지워지는지 이름을 적어 준다."}],"th":{"sum":"모바일 화면은 <b>내 기기 하나</b>가 아닙니다. 화면 크기도 밀도도 글꼴 크기도 사용자마다 다르고, 손가락은 마우스보다 훨씬 뭉툭해요. 개발 기기에서만 맞는 화면은 <b>거의 모두에게 조금씩 어긋납니다</b>.","body":[{"h":"픽셀이 아니라 밀도 독립 단위로","t":"같은 <b>100픽셀</b>이 어떤 기기에서는 손톱만 하고 어떤 기기에서는 손가락만 합니다. 화면마다 1인치에 들어가는 픽셀 수가 다르기 때문이에요. 그래서 <b>밀도와 무관한 단위</b>로 크기를 잡고, 시스템이 기기 배율을 곱해 실제 픽셀로 바꾸게 둡니다. 이미지도 배율별로 준비해야 흐릿해지지 않습니다."},{"h":"손가락은 커서가 아니다","t":"마우스는 1픽셀을 정확히 찍지만 손가락 끝은 <b>지름 1cm 쯤 되는 뭉툭한 원</b>입니다. 그래서 누를 수 있는 영역은 눈에 보이는 아이콘보다 커야 하고, 서로 다른 동작 사이에는 간격이 있어야 해요. 특히 <b>되돌릴 수 없는 동작</b>을 자주 누르는 버튼 옆에 두면 사고가 납니다."},{"h":"내 설정이 모두의 설정은 아니다","t":"글꼴을 크게 쓰는 사람, 색을 잘 구분하지 못하는 사람, 화면을 못 보고 소리로 듣는 사람이 있습니다. 이들을 위한 대응은 <b>따로 만드는 화면이 아니라</b> 원래 화면이 늘어나고 읽히게 만드는 일이에요 — 대개 <b>고정 크기를 쓰지 않는 것</b>에서 절반이 해결됩니다."}],"code":{"t":"같은 48, 다른 결과","c":"화면 밀도별 실제 픽셀 (1dp = 1px × 배율)\n    mdpi  ×1     48dp →  48px\n    hdpi  ×1.5   48dp →  72px\n    xhdpi ×2     48dp →  96px\n    xxhdpi ×3    48dp → 144px\n\n픽셀로 잡으면\n    48px 은 xxhdpi 에서 16dp — 손가락으로 누를 수 없다\n\n권장 최소 터치 영역\n    안드로이드 48dp · iOS 44pt   (보이는 아이콘은 더 작아도 된다)"},"key":["크기는 픽셀이 아니라 밀도 독립 단위로 잡는다","누를 수 있는 영역은 보이는 아이콘보다 크게","고정 크기를 쓰지 않으면 접근성 문제의 절반이 사라진다","색만으로 정보를 전달하지 않는다"]}},{"t":"화면 만들기 III","q":[{"t":"choice","k":"소리로 듣는 화면","q":"화면을 소리로 읽어 주는 기능을 켠 사용자에게 <b>아이콘만 있는 버튼</b>이 '버튼' 이라고만 읽힌다. 무엇이 빠졌는가?","code":"[🗑]  ← 화면에 글자가 없다","o":["그 버튼이 무엇을 하는지 알려 주는 <b>이름</b>이 빠졌다 — 화면에 글자가 없어도 보조 기술이 읽을 이름을 따로 붙여 줘야 한다","버튼 크기를 키우면 자동으로 인식된다","아이콘 이미지의 파일 이름을 의미 있게 바꾸면 읽어 준다","아이콘 버튼은 원래 읽히지 않으므로 글자 버튼으로 바꾸는 수밖에 없다"],"a":0,"ex":"가장 적은 노력으로 가장 큰 차이를 만드는 항목.\n💡 개념: 보조 기술은 화면에 그려진 그림이 아니라 <b>각 요소에 붙은 정보</b>를 읽는다. 글자가 있는 버튼은 그 글자를 읽지만 아이콘만 있으면 읽을 것이 없다. 그래서 '삭제' 같은 이름을 속성으로 붙여 준다.\n🛠 실무: 이름은 <b>보이는 것이 아니라 하는 일</b>로 적는다 — '휴지통 아이콘' 이 아니라 '삭제'. 순전히 장식인 이미지는 반대로 <b>읽지 않도록</b> 표시해서 소음을 줄인다. 실제로 켜 보고 화면을 끝까지 넘겨 보는 것이 가장 빠른 점검이다."},{"t":"choice","k":"색만으로 알리면","cat":"review","q":"주문 상태를 <b>초록 점과 빨간 점</b>으로만 구분해 보여 준다. 무엇이 문제인가?","code":"● 정상   ● 실패      ← 색만 다르다","o":["초록과 빨강 대신 파랑과 노랑을 쓰면 모든 문제가 사라진다","색을 구분하기 어려운 사람에게는 <b>두 상태가 같아 보인다</b> — 색과 함께 글자나 모양처럼 색 말고도 구분되는 단서를 하나 더 줘야 한다","점이 너무 작은 것이 문제이며 크기를 키우면 해결된다","색상 정보는 화면 확대로 해결되는 문제다"],"a":1,"ex":"빨강·초록 조합은 특히 구분이 어려운 대표적인 짝이다.\n💡 개념: 색은 보조 단서로는 훌륭하지만 <b>유일한 단서</b>가 되면 안 된다. 글자를 함께 적거나 모양을 다르게 하면(체크와 엑스) 색을 못 봐도 구분된다. 흑백으로 인쇄해 보면 문제가 바로 드러난다.\n🛠 실무: 그래프에서도 같다 — 선을 색으로만 구분하면 읽을 수 없는 사람이 생긴다. 선 모양을 다르게 하거나 값을 직접 라벨로 붙인다. 색만 쓴 자리를 찾는 가장 쉬운 방법은 <b>화면을 회색조로 바꿔 보는 것</b>이다."},{"t":"choice","k":"충분히 진한가","cat":"design","q":"밝은 회색 배경에 조금 더 진한 회색 글씨를 썼더니 '잘 안 보인다' 는 제보가 온다. 무엇을 기준으로 판단하는가?","code":"배경과 글자의 밝기 차이를 비로 계산한다\n일반 텍스트 4.5:1 이상 · 큰 텍스트 3:1 이상","o":["브랜드 색을 쓰는 경우에는 기준을 적용하지 않는다","다크 모드에서만 대비를 확인하면 된다","배경과 글자의 <b>대비비</b>를 계산해 일반 텍스트는 4.5:1, 큰 텍스트는 3:1 이상인지 본다 — 눈으로 '괜찮아 보인다' 는 실내 조명과 좋은 화면에서만 참이다","글자 크기가 충분히 크면 색 대비는 따지지 않아도 된다"],"a":2,"ex":"'보인다/안 보인다' 를 취향이 아니라 숫자로 판정할 수 있다.\n💡 개념: 대비비는 두 색의 밝기를 계산해 비로 나타낸 값이다. 기준이 있으니 논쟁할 필요가 없고 도구로 자동 검사할 수도 있다. 특히 <b>보조 텍스트로 쓰는 연한 회색</b>이 기준에 자주 걸린다.\n🛠 실무: 실내에서 밝기를 낮춰 보는 화면과, 햇빛 아래 야외에서 보는 화면은 전혀 다르다. 개발자는 대개 앞의 조건에서만 확인한다. 색을 정하는 단계에서 <b>역할별 색마다 대비를 재 두면</b> 나중에 화면마다 다시 따질 일이 없다."},{"t":"choice","k":"글꼴이 커지면","cat":"debug","q":"시스템 글꼴 크기를 크게 쓰는 사용자에게서 버튼 글자가 잘리거나 두 줄이 겹친다는 제보가 온다. 레이아웃에서 <b>구조적으로</b> 무엇을 바꿔야 하는가?","code":"height: 40   ← 고정\nheight: 최소 40, 내용에 따라 늘어남  ← ?","o":["글꼴 크기 설정을 무시하고 앱 안에서는 고정 크기를 쓴다","큰 글꼴 사용자를 위한 별도 화면을 따로 만든다","글자가 넘칠 때 자동으로 글꼴을 줄이는 것이 표준 해법이다","높이를 <b>고정하지 말고 최소값으로</b> 두어 내용에 따라 늘어나게 한다 — 글꼴이 커지면 줄 수와 높이가 함께 늘어야 하고, 옆으로도 잘리지 않게 줄바꿈을 허용해야 한다"],"a":3,"ex":"고정 높이 하나가 접근성 문제의 절반을 만든다.\n💡 개념: 화면을 만들 때 우리는 내 기기의 기본 글꼴로 보고 높이를 정한다. 그 높이는 <b>지금 이 글꼴에서만</b> 맞는 값이다. 내용에 따라 늘어나게 두면 글꼴이 커지든 번역돼서 길어지든 알아서 맞는다.\n🛠 실무: 글꼴을 자동으로 줄이는 방식은 <b>크게 보려던 사용자의 의도를 거스른다</b>. 설정을 무시하는 것은 더 나쁘다. 개발 중에 글꼴 크기를 최대로 올려 두고 한 바퀴 돌아보면 잘리는 곳이 한 번에 드러난다."}],"th":{"sum":"모바일 화면은 <b>내 기기 하나</b>가 아닙니다. 화면 크기도 밀도도 글꼴 크기도 사용자마다 다르고, 손가락은 마우스보다 훨씬 뭉툭해요. 개발 기기에서만 맞는 화면은 <b>거의 모두에게 조금씩 어긋납니다</b>.","body":[{"h":"픽셀이 아니라 밀도 독립 단위로","t":"같은 <b>100픽셀</b>이 어떤 기기에서는 손톱만 하고 어떤 기기에서는 손가락만 합니다. 화면마다 1인치에 들어가는 픽셀 수가 다르기 때문이에요. 그래서 <b>밀도와 무관한 단위</b>로 크기를 잡고, 시스템이 기기 배율을 곱해 실제 픽셀로 바꾸게 둡니다. 이미지도 배율별로 준비해야 흐릿해지지 않습니다."},{"h":"손가락은 커서가 아니다","t":"마우스는 1픽셀을 정확히 찍지만 손가락 끝은 <b>지름 1cm 쯤 되는 뭉툭한 원</b>입니다. 그래서 누를 수 있는 영역은 눈에 보이는 아이콘보다 커야 하고, 서로 다른 동작 사이에는 간격이 있어야 해요. 특히 <b>되돌릴 수 없는 동작</b>을 자주 누르는 버튼 옆에 두면 사고가 납니다."},{"h":"내 설정이 모두의 설정은 아니다","t":"글꼴을 크게 쓰는 사람, 색을 잘 구분하지 못하는 사람, 화면을 못 보고 소리로 듣는 사람이 있습니다. 이들을 위한 대응은 <b>따로 만드는 화면이 아니라</b> 원래 화면이 늘어나고 읽히게 만드는 일이에요 — 대개 <b>고정 크기를 쓰지 않는 것</b>에서 절반이 해결됩니다."}],"code":{"t":"같은 48, 다른 결과","c":"화면 밀도별 실제 픽셀 (1dp = 1px × 배율)\n    mdpi  ×1     48dp →  48px\n    hdpi  ×1.5   48dp →  72px\n    xhdpi ×2     48dp →  96px\n    xxhdpi ×3    48dp → 144px\n\n픽셀로 잡으면\n    48px 은 xxhdpi 에서 16dp — 손가락으로 누를 수 없다\n\n권장 최소 터치 영역\n    안드로이드 48dp · iOS 44pt   (보이는 아이콘은 더 작아도 된다)"},"key":["크기는 픽셀이 아니라 밀도 독립 단위로 잡는다","누를 수 있는 영역은 보이는 아이콘보다 크게","고정 크기를 쓰지 않으면 접근성 문제의 절반이 사라진다","색만으로 정보를 전달하지 않는다"]}},{"t":"화면 만들기 IV","q":[{"t":"choice","k":"기다리는 동안 보여 줄 것","cat":"design","q":"목록을 불러오는 동안 화면 가운데에 회전하는 표시만 띄운다. 더 나은 방법과 그 이유는?","code":"① 회전 표시 하나\n② 들어올 내용 모양의 회색 틀(스켈레톤)","o":["들어올 내용과 <b>같은 모양의 틀</b>을 보여 주면 기다림이 짧게 느껴지고, 내용이 도착했을 때 <b>화면이 덜 튄다</b> — 자리를 미리 잡아 두었기 때문이다","회전 표시가 표준이므로 바꿀 이유가 없다","아무것도 보여 주지 않는 편이 더 빠르게 느껴진다","예상 남은 시간을 초 단위로 보여 주는 것이 언제나 최선이다"],"a":0,"ex":"체감 속도는 실제 속도만큼이나 <b>기다리는 동안 무엇을 보느냐</b>에 달렸다.\n💡 개념: 빈 화면이나 회전 표시는 '아무 일도 안 일어난다' 는 느낌을 준다. 들어올 모양을 미리 그려 두면 진행 중이라는 것이 보이고, 실제 내용이 그 자리에 채워지므로 화면이 갑자기 재배치되지 않는다.\n🛠 실무: 아주 빠르게 끝나는 요청에는 오히려 <b>아무것도 안 보여 주는 편</b>이 낫다 — 깜빡임이 더 거슬린다. 보통 200~300밀리초쯤 지난 뒤에야 표시를 띄우고, 한 번 띄웠으면 너무 빨리 지우지 않는다."},{"t":"choice","k":"이미지가 도착하면 화면이 튄다","cat":"debug","q":"목록을 읽는 중에 이미지가 하나씩 도착하면서 <b>글이 아래로 밀려</b> 읽던 자리를 놓친다. 원인과 해결은?","code":"이미지 도착 전: 높이 0\n이미지 도착 후: 높이 200   ← 아래 내용이 밀린다","o":["이미지를 모두 받은 뒤에 화면을 그리는 수밖에 없다","이미지 자리를 <b>미리 잡아 두지 않아서</b>다 — 크기나 비율을 알고 있으면 도착 전에도 그만큼 자리를 비워 두어, 채워질 때 아래 내용이 움직이지 않는다","스크롤 위치를 매번 저장했다 복원하면 된다","이미지 크기를 줄이면 밀림이 사라진다"],"a":1,"ex":"읽고 있는데 글이 움직이는 것만큼 거슬리는 것도 없다.\n💡 개념: 높이를 모르는 요소는 도착하기 전에 0 으로 잡히고, 도착하는 순간 늘어나면서 아래를 밀어낸다. 크기나 가로세로 비율을 미리 알려 주면 자리를 먼저 확보할 수 있다.\n🛠 실무: 그래서 이미지 API 는 <b>가로·세로 값을 함께</b> 내려 주는 것이 좋다. 비율만 알아도 충분하다. 광고나 나중에 끼어드는 배너도 같은 문제를 만드니, 들어올 자리를 처음부터 비워 두거나 <b>보고 있는 영역 위쪽에는 끼워 넣지 않는다</b>."},{"t":"choice","k":"글자가 길어진다","cat":"design","q":"한국어로 만든 화면을 다른 언어로 번역했더니 버튼 글자가 넘친다. 설계 단계에서 무엇을 전제했어야 하는가?","code":"확인        (2글자)\nConfirm     (7글자)\nBestätigen  (10글자)","o":["번역할 때 원문과 글자 수를 맞추도록 요청하면 된다","넘치는 글자는 말줄임표로 잘라 표시하는 것이 표준이다","같은 뜻이라도 언어마다 <b>글자 수가 크게 다르다</b>는 것을 전제하고, 버튼 폭을 글자에 맞춰 늘어나게 하거나 줄바꿈을 허용해야 한다 — 한국어 기준으로 폭을 고정하면 대부분의 언어에서 넘친다","언어별로 화면을 따로 만드는 것이 유일한 방법이다"],"a":2,"ex":"한국어와 중국어는 짧은 축이라 <b>기준으로 삼으면 반드시 넘친다</b>.\n💡 개념: 짧은 단어일수록 언어별 차이가 크다. 그래서 폭을 내용에 맞춰 늘어나게 두고, 안 되면 줄바꿈을 허용한다. 말줄임으로 자르면 버튼 뜻을 알 수 없게 되므로 최후의 수단이다.\n🛠 실무: 글자 크기 문제와 같은 처방이다 — <b>고정 크기를 쓰지 않으면</b> 둘 다 해결된다. 번역 전에 확인하고 싶다면 모든 문구를 1.5배 길이의 가짜 문자열로 바꿔 한 바퀴 돌려 보는 방법이 있다."},{"t":"choice","k":"아무것도 없을 때","cat":"design","q":"목록이 비었을 때 화면에 <b>아무것도 안 보인다</b>. 사용자는 앱이 고장 났다고 생각한다. 어떻게 채워야 하는가?","code":"비어 있음 → ?\n오류      → ?\n검색 결과 없음 → ?","o":["'데이터 없음' 이라는 문구 하나면 세 경우 모두 충분하다","비어 있을 때는 아무것도 안 보여 주는 것이 깔끔하다","예시 데이터를 채워 넣어 비어 보이지 않게 한다","왜 비었는지와 <b>다음에 무엇을 하면 되는지</b>를 함께 보여 준다 — 처음이라 비었는지, 검색 결과가 없는지, 오류로 못 불러왔는지에 따라 안내가 달라야 한다"],"a":3,"ex":"빈 화면은 만들다 만 화면이 아니라 <b>설계해야 할 화면</b>이다.\n💡 개념: 같은 '비어 있음' 이라도 사용자가 해야 할 일이 다르다. 처음이라면 만드는 법을 알려 주고, 검색 결과가 없다면 조건을 바꿔 보라고 하고, 오류라면 다시 시도할 방법을 준다. 구분하지 않으면 어느 경우에도 도움이 안 된다.\n🛠 실무: 마지막 보기처럼 가짜 데이터를 채우면 <b>사용자가 진짜인 줄 알고</b> 행동하므로 더 나쁘다. 그리고 이 세 화면은 개발 중에 잘 안 보여서 늦게 발견된다 — 처음부터 만들어 두고 확인하는 목록에 넣어 둔다."}],"th":{"sum":"모바일 화면은 <b>내 기기 하나</b>가 아닙니다. 화면 크기도 밀도도 글꼴 크기도 사용자마다 다르고, 손가락은 마우스보다 훨씬 뭉툭해요. 개발 기기에서만 맞는 화면은 <b>거의 모두에게 조금씩 어긋납니다</b>.","body":[{"h":"픽셀이 아니라 밀도 독립 단위로","t":"같은 <b>100픽셀</b>이 어떤 기기에서는 손톱만 하고 어떤 기기에서는 손가락만 합니다. 화면마다 1인치에 들어가는 픽셀 수가 다르기 때문이에요. 그래서 <b>밀도와 무관한 단위</b>로 크기를 잡고, 시스템이 기기 배율을 곱해 실제 픽셀로 바꾸게 둡니다. 이미지도 배율별로 준비해야 흐릿해지지 않습니다."},{"h":"손가락은 커서가 아니다","t":"마우스는 1픽셀을 정확히 찍지만 손가락 끝은 <b>지름 1cm 쯤 되는 뭉툭한 원</b>입니다. 그래서 누를 수 있는 영역은 눈에 보이는 아이콘보다 커야 하고, 서로 다른 동작 사이에는 간격이 있어야 해요. 특히 <b>되돌릴 수 없는 동작</b>을 자주 누르는 버튼 옆에 두면 사고가 납니다."},{"h":"내 설정이 모두의 설정은 아니다","t":"글꼴을 크게 쓰는 사람, 색을 잘 구분하지 못하는 사람, 화면을 못 보고 소리로 듣는 사람이 있습니다. 이들을 위한 대응은 <b>따로 만드는 화면이 아니라</b> 원래 화면이 늘어나고 읽히게 만드는 일이에요 — 대개 <b>고정 크기를 쓰지 않는 것</b>에서 절반이 해결됩니다."}],"code":{"t":"같은 48, 다른 결과","c":"화면 밀도별 실제 픽셀 (1dp = 1px × 배율)\n    mdpi  ×1     48dp →  48px\n    hdpi  ×1.5   48dp →  72px\n    xhdpi ×2     48dp →  96px\n    xxhdpi ×3    48dp → 144px\n\n픽셀로 잡으면\n    48px 은 xxhdpi 에서 16dp — 손가락으로 누를 수 없다\n\n권장 최소 터치 영역\n    안드로이드 48dp · iOS 44pt   (보이는 아이콘은 더 작아도 된다)"},"key":["크기는 픽셀이 아니라 밀도 독립 단위로 잡는다","누를 수 있는 영역은 보이는 아이콘보다 크게","고정 크기를 쓰지 않으면 접근성 문제의 절반이 사라진다","색만으로 정보를 전달하지 않는다"]}}],"ord":5},{"t":"실행형 실전 — 불안정한 네트워크 위에서","l":[{"t":"무한 스크롤·오프라인 큐·이미지 캐시","xp":80,"th":{"sum":"모바일의 세 가지 현실 — **페이지는 겹치고, 네트워크는 끊기고, 메모리는 모자란다** — 에 각각 표준 패턴이 있다.","body":[{"h":"중복과 순서","t":"스크롤 중 새 글이 끼어들면 같은 항목이 다음 페이지에 또 온다 — id 로 **클라이언트에서 중복을 걸러야** 한다. hasMore 는 개수 추측이 아니라 서버의 nextCursor 로 정한다. 오프라인 큐는 사용자 의도의 순서라, 실패하면 **즉시 멈추고 남은 것을 통째로 보존**해야 다음에 이어 보낼 수 있다."},{"h":"캐시는 바이트로 센다","t":"이미지 캐시를 개수로 제한하면 OOM 을 못 막는다 — 썸네일과 원본은 수백 배 차이다. 용량 기준 LRU 에서 get 은 **최근 사용 갱신**까지 해야 한다. 안 하면 FIFO 가 되어 매 화면 쓰는 아이콘이 쫓겨난다. JS Map 은 삽입 순서를 보존해 '지우고 다시 넣기' 로 LRU 가 된다."}],"code":{"c":"// get 도 순서를 갱신해야 LRU 다\nconst size = m.get(key);\nm.delete(key); m.set(key, size);","cap":"갱신 없는 LRU 는 사실 FIFO 다"},"key":["중복 제거는 클라이언트의 방어선","hasMore 는 nextCursor 가 유일한 신호","큐 flush 는 실패 시 중단 + 순서 보존","캐시는 바이트 LRU, get 이 touch"]},"q":[{"t":"code","run":"js","k":"무한 스크롤 페이지 병합","cat":"internals","q":"무한 스크롤의 <b>페이지 병합</b>을 구현하세요. <code>appendPage(state, page)</code> 는 <code>{items, hasMore}</code> 상태에 <code>{items, nextCursor}</code> 응답을 합칩니다. <b>id 가 이미 있는 항목은 제외</b>(페이지 안의 중복 포함)하고, <code>hasMore</code> 는 <b><code>nextCursor !== null</code></b> 로 정합니다. 원본 상태는 바꾸지 마세요.","src":"function appendPage(state, page) {\n  // TODO: id 중복 제거 + hasMore 갱신\n  return { items: state.items.concat(page.items), hasMore: true };\n}","sol":"function appendPage(state, page) {\n  const seen = new Set(state.items.map((it) => it.id));\n  const fresh = [];\n  page.items.forEach((it) => {\n    if (!seen.has(it.id)) { seen.add(it.id); fresh.push(it); }\n  });\n  return { items: state.items.concat(fresh), hasMore: page.nextCursor !== null };\n}","tests":[{"in":"appendPage({items:[{id:1}],hasMore:true},{items:[{id:2}],nextCursor:'c'})","out":"{items:[{id:1},{id:2}],hasMore:true}"},{"in":"appendPage({items:[{id:1}],hasMore:true},{items:[{id:1},{id:2}],nextCursor:null})","out":"{items:[{id:1},{id:2}],hasMore:false}"},{"in":"(() => { const st={items:[{id:1}],hasMore:true}; appendPage(st,{items:[{id:2}],nextCursor:null}); return st.items.length; })()","out":"1"},{"in":"appendPage({items:[{id:1}],hasMore:true},{items:[],nextCursor:null})","out":"{items:[{id:1}],hasMore:false}"}],"edge":[{"in":"appendPage({items:[],hasMore:true},{items:[{id:9}],nextCursor:'x'})","out":"{items:[{id:9}],hasMore:true}"},{"in":"appendPage({items:[],hasMore:true},{items:[{id:1},{id:1}],nextCursor:null})","out":"{items:[{id:1}],hasMore:false}"}],"ex":"🎯 스크롤 중에 <b>새 글이 위에 끼어들면</b> 오프셋 기반 페이지네이션은 같은 항목을 다음 페이지에서 또 내려보냅니다. 중복 제거 없이 붙이면 리스트에 같은 카드가 두 번 보이고, key 중복으로 렌더링 경고까지 납니다.\n💡 그래서 모바일 피드는 <b>커서 기반</b>이 표준입니다. '몇 번째부터' 가 아니라 '이 항목 다음부터' 를 요청하므로 끼어듦에 강합니다 — 그래도 재시도·캐시 때문에 중복은 여전히 올 수 있어 <b>클라이언트 쪽 방어</b>가 필요합니다.\n⚠️ <code>hasMore</code> 를 <code>items.length &gt; 0</code> 으로 정하면 <b>마지막 페이지가 우연히 꽉 찼을 때</b> 판별할 수 없습니다. 서버가 명시한 <code>nextCursor</code> 의 null 여부가 유일하게 믿을 수 있는 신호입니다.\n🔧 상태를 새 객체로 돌려주는 것은 React Native 의 <code>FlatList</code> 가 <code>data</code> 참조 변화로 갱신을 감지하기 때문입니다 — 제자리에서 push 하면 화면이 안 바뀝니다."},{"t":"code","run":"js","k":"오프라인 큐 flush","cat":"internals","q":"오프라인에서 쌓인 작업 큐를 <b>순서대로 전송</b>하세요. <code>flush(queue, send)</code> 는 각 작업에 <code>send(action)</code> 을 호출해 <code>true</code>(성공)/<code>false</code>(실패)를 받습니다. <b>실패하면 즉시 멈추고</b>, <code>{sent, rest}</code> — 보낸 것들과 남은 것들(실패한 것 포함, 순서 보존) — 를 돌려줍니다. 원본 큐는 바꾸지 마세요.","src":"function flush(queue, send) {\n  // TODO: 실패 시 중단, {sent, rest}\n  queue.forEach(send);\n  return { sent: queue, rest: [] };\n}","sol":"function flush(queue, send) {\n  const sent = [];\n  for (let i = 0; i < queue.length; i++) {\n    if (!send(queue[i])) return { sent, rest: queue.slice(i) };\n    sent.push(queue[i]);\n  }\n  return { sent, rest: [] };\n}","tests":[{"in":"flush(['a','b'],()=>true)","out":"{sent:['a','b'],rest:[]}"},{"in":"flush(['a','b','c'],(x)=>x!=='b')","out":"{sent:['a'],rest:['b','c']}"},{"in":"(() => { const got=[]; flush(['x','y'],(a)=>{got.push(a); return true;}); return got; })()","out":"['x','y']"},{"in":"flush(['a'],()=>false)","out":"{sent:[],rest:['a']}"}],"edge":[{"in":"flush([],()=>true)","out":"{sent:[],rest:[]}"},{"in":"(() => { const memq=['a','b']; flush(memq,()=>false); return memq.length; })()","out":"2"}],"ex":"🎯 오프라인 우선 앱의 핵심 규칙은 <b>순서 보존</b>입니다. '수정 → 삭제' 를 '삭제 → 수정' 으로 보내면 서버에서 없는 문서를 수정하려다 실패합니다. 큐는 사용자의 <b>의도의 순서</b>를 담고 있습니다.\n💡 실패 시 <b>즉시 멈추는</b> 이유도 순서 때문입니다. 실패한 작업을 건너뛰고 다음을 보내면 뒤의 작업이 앞의 결과에 의존할 때 데이터가 꼬입니다. 실패 지점부터 통째로 남겨야 다음 flush 에서 <b>이어서</b> 보낼 수 있습니다.\n⚠️ 남긴 작업을 다시 보낼 것이므로 서버 API 는 <b>멱등</b>해야 합니다 — 같은 요청이 두 번 가도 결과가 하나여야 합니다. 클라이언트가 만든 요청 ID(idempotency key)가 그 장치입니다.\n🔧 원본 큐를 건드리지 않는 것은 flush 도중 앱이 죽어도 <b>저장된 큐가 온전</b>해야 하기 때문입니다. 성공 목록을 확인한 뒤에야 저장소에서 지우는 2단계가 안전합니다."},{"t":"code","run":"js","k":"이미지 캐시 — 용량 LRU","cat":"internals","q":"이미지 캐시를 <b>바이트 용량 기준 LRU</b> 로 구현하세요. <code>makeCache(cap)</code> 은 <code>{put, get}</code> 을 돌려줍니다. <code>put(key, size)</code> 는 공간이 모자라면 <b>가장 오래 안 쓴 항목부터 제거</b>하고 넣습니다(<b>항목 하나가 <code>cap</code> 을 넘으면 <code>false</code></b>). <code>get(key)</code> 은 적중 시 <code>true</code> 를 돌려주며 그 항목을 <b>최근 사용으로 갱신</b>합니다. 같은 키의 put 은 크기를 교체합니다.","src":"function makeCache(cap) {\n  const m = new Map();\n  return {\n    put(key, size) {\n      // TODO: 용량 초과 시 LRU 제거\n      m.set(key, size);\n      return true;\n    },\n    get(key) {\n      // TODO: 적중 시 최근 사용 갱신\n      return m.has(key);\n    },\n  };\n}","sol":"function makeCache(cap) {\n  const m = new Map();\n  let used = 0;\n  return {\n    put(key, size) {\n      if (size > cap) return false;\n      if (m.has(key)) { used -= m.get(key); m.delete(key); }\n      while (used + size > cap) {\n        const old = m.keys().next().value;\n        used -= m.get(old); m.delete(old);\n      }\n      m.set(key, size); used += size;\n      return true;\n    },\n    get(key) {\n      if (!m.has(key)) return false;\n      const size = m.get(key);\n      m.delete(key); m.set(key, size);\n      return true;\n    },\n  };\n}","tests":[{"in":"(() => { const c=makeCache(100); c.put('a',60); c.put('b',30); c.put('c',30); return [c.get('a'), c.get('b')]; })()","out":"[false,true]"},{"in":"(() => { const c=makeCache(100); c.put('a',60); c.put('b',30); c.get('a'); c.put('c',30); return [c.get('a'), c.get('b')]; })()","out":"[true,false]"},{"in":"(() => { const c=makeCache(50); return c.put('big',51); })()","out":"false"},{"in":"(() => { const c=makeCache(100); c.put('a',60); c.put('a',10); c.put('b',80); return c.get('a'); })()","out":"true"}],"edge":[{"in":"(() => { const c=makeCache(100); c.put('a',100); c.put('b',1); return c.get('a'); })()","out":"false"},{"in":"(() => { const c=makeCache(10); return c.get('nope'); })()","out":"false"}],"ex":"🎯 이미지 캐시는 <b>개수가 아니라 바이트</b>로 제한해야 합니다. 썸네일 100장과 원본 사진 100장은 메모리 사용량이 수백 배 차이라, 개수 제한은 OOM 을 막지 못합니다.\n💡 자바스크립트 <code>Map</code> 은 <b>삽입 순서를 보존</b>하므로, '지우고 다시 넣기' 로 최근 사용을 맨 뒤로 보내면 맨 앞이 항상 LRU 가 됩니다 — 별도 연결 리스트 없이 LRU 가 구현되는 우아한 트릭입니다.\n⚠️ <code>get</code> 이 순서를 갱신하지 않으면 LRU 가 아니라 <b>FIFO</b> 가 됩니다. 매 화면마다 쓰는 프로필 아이콘이 '오래 전에 넣었다' 는 이유로 쫓겨나 네트워크를 다시 타는 성능 버그가 조용히 생깁니다.\n🔧 실전 모바일 캐시는 이 구조의 2층입니다 — 메모리 LRU(빠름, 작음) 아래 디스크 LRU(느림, 큼)를 두고, 메모리에서 밀려난 것을 디스크에서 다시 찾습니다. Glide·Coil·SDWebImage 가 모두 이 구조입니다."}]}],"ord":8},{"t":"실무 디버깅 — 모바일에서 실제로 나는 문제","g":"🐛","l":[{"t":"디버깅 I","q":[{"t":"choice","k":"메인 스레드 네트워크","cat":"debug","q":"버튼을 누르면 화면이 3~5초 멈추고, 가끔 '앱이 응답하지 않습니다' 가 뜬다. 로그에는 <code>NetworkOnMainThreadException</code> 도 보인다. 원인과 해결은?","code":"fun onClick() {\n  val json = URL(api).readText()   // 메인 스레드\n  textView.text = parse(json)\n}","o":["네트워크 호출이 UI 스레드를 막고 있다. 코루틴(<code>Dispatchers.IO</code>)이나 별도 스레드에서 받아 오고 결과만 메인 스레드에서 반영한다","<code>readText()</code> 대신 <code>readBytes()</code> 를 쓰면 논블로킹이 되어 해결된다","매니페스트에 <code>largeHeap=\"true\"</code> 를 주면 응답 시간이 회복된다","<code>textView.text</code> 대입이 느린 것이므로 <code>post{}</code> 로 감싸면 된다"],"a":0,"ex":"UI 스레드에서 네트워크를 기다리면 그 시간 동안 화면이 통째로 멈춘다.\n💡 개념: 안드로이드는 메인 스레드가 약 5초 막히면 ANR 로 판단한다. 네트워크는 수백 ms~수 초라 예외로 아예 금지돼 있다.\n🛠 실무: I/O 는 코루틴·Executor 로 옮기고, 메인 스레드에서는 결과 반영만 한다. StrictMode 를 켜 두면 개발 중에 바로 잡힌다."},{"t":"choice","k":"뷰 재사용 상태 누수","cat":"debug","q":"리스트를 아래로 스크롤하면 <b>읽지 않은 항목이 아닌데도</b> 파란 배지가 붙어 있는 행이 나타난다. 위로 올렸다 내리면 위치가 또 바뀐다. 원인과 해결은?","code":"fun onBind(h: VH, item: Item) {\n  h.title.text = item.title\n  if (item.unread) h.badge.visibility = VISIBLE\n}","o":["배지 뷰를 재사용할 때 새로 그리지 않아서다. <code>notifyDataSetChanged()</code> 를 매번 부르면 해결된다","리스트 어댑터가 스레드 안전하지 않아서다. 바인딩을 <code>synchronized</code> 로 감싸야 한다","<code>if</code> 에 <code>else</code> 가 없어 재사용된 뷰의 이전 상태가 남는다. 두 경우를 모두 지정하거나 바인딩 시작에서 초기화한다","<code>item.unread</code> 가 항상 참이라서다. 데이터 계층의 필터를 고쳐야 한다"],"a":2,"ex":"재사용되는 뷰는 '이전 항목의 상태' 를 그대로 들고 온다.\n💡 개념: RecyclerView 는 화면 밖으로 나간 뷰 객체를 다시 쓴다. 바인딩에서 설정하지 않은 속성은 이전 값이 남는다.\n🛠 실무: 조건부 설정에는 반드시 else 를 두거나, 바인딩 첫 줄에서 뷰를 기본 상태로 되돌린다. 이미지·리스너·애니메이션도 같은 함정이다."},{"t":"choice","k":"정적 참조 누수","cat":"debug","q":"화면을 여러 번 열었다 닫으면 메모리 사용량이 계속 늘고, 힙 덤프에 닫힌 액티비티가 여러 개 남아 있다. 원인과 해결은?","code":"object Tracker {\n  var ctx: Context? = null\n}\n// onCreate 에서\nTracker.ctx = this","o":["액티비티가 <code>onDestroy</code> 에서 <code>finish()</code> 를 부르지 않아서다. 명시적으로 종료하면 회수된다","싱글턴이 액티비티 컨텍스트를 붙들고 있어 GC 가 회수하지 못한다. <code>applicationContext</code> 를 쓰거나 화면이 끝날 때 참조를 끊는다","이미지 캐시가 커서 생긴 일이므로 캐시 한도를 줄이면 된다","코틀린 <code>object</code> 는 원래 메모리를 많이 쓰므로 <code>class</code> 로 바꾸면 해결된다"],"a":1,"ex":"앱만큼 오래 사는 객체가 화면만큼만 살아야 할 것을 붙들면 누수가 된다.\n💡 개념: 액티비티는 화면 단위 수명이지만 싱글턴·정적 필드·동반 객체는 프로세스 수명이다. 참조가 한 줄이라도 남으면 전체 뷰 트리가 함께 남는다.\n🛠 실무: 오래 사는 곳에는 applicationContext 만 넘기고, 리스너·콜백은 onDestroy 에서 해제한다. LeakCanary 로 상시 감시한다."},{"t":"choice","k":"사라진 화면에 대한 콜백","cat":"debug","q":"네트워크가 느린 사용자에게서만 크래시가 보고된다. 스택에는 화면 갱신 코드가 있고 <code>IllegalStateException</code> 이나 <code>NullPointerException</code> 이 찍힌다. 원인과 해결은?","code":"api.load { result ->\n  binding.title.text = result.name   // 응답이 늦게 도착\n}","o":["응답 파싱이 실패한 것이므로 <code>try/catch</code> 로 감싸면 된다","느린 네트워크에서 타임아웃이 나는 것이므로 타임아웃을 늘리면 해결된다","메인 스레드가 아닌 곳에서 UI 를 만져서다. <code>runOnUiThread</code> 로 감싸면 끝난다","화면이 이미 사라진 뒤 콜백이 도착해 없는 뷰를 건드린다. 화면 수명에 묶인 스코프에서 실행하거나 콜백에서 생존 여부를 확인한다"],"a":3,"ex":"요청은 화면보다 오래 산다 — 늦게 온 응답이 이미 없는 뷰를 만진다.\n💡 개념: 사용자가 뒤로 가면 뷰는 파괴되지만 진행 중인 요청과 콜백은 남아 있다. 느릴수록 그 틈이 커져 느린 사용자에게만 보인다.\n🛠 실무: lifecycleScope·viewLifecycleOwner 처럼 화면 수명에 묶인 스코프에서 실행하고, 화면이 끝날 때 요청을 취소한다."}],"th":{"sum":"모바일 버그의 상당수는 '내 기기에서는 됐는데' 로 시작합니다. 화면이 죽었다 살아나고, 네트워크가 끊기고, 시스템이 앱을 재우고, 사용자가 글꼴을 키우기 때문입니다.","body":[{"h":"증상은 대개 원인에서 멀리 떨어져 나타난다","t":"리스트를 스크롤했더니 <b>엉뚱한 항목에 배지가 붙는</b> 것은 리스트 코드의 버그가 아니라 <b>뷰를 재사용하면서 이전 상태를 지우지 않은</b> 탓이고, '가끔 크래시' 는 대개 <b>화면이 사라진 뒤 도착한 콜백</b>입니다. 그래서 모바일 디버깅은 <b>무엇이 일어났나</b> 보다 <b>언제·어떤 생명주기에서 일어났나</b> 를 먼저 묻습니다."},{"h":"재현 조건을 만들어야 고칠 수 있다","t":"가장 강력한 도구는 <b>강제로 나쁜 상황을 만드는 것</b>입니다 — 개발자 옵션의 <b>'액티비티 유지 안 함'</b> 으로 프로세스 사망을 재현하고, <b>비행기 모드</b>와 <b>네트워크 스로틀</b>로 끊김을 만들고, <b>글꼴 크기 최대</b>·<b>RTL 강제</b>로 레이아웃을 흔들고, <code>adb shell dumpsys deviceidle force-idle</code> 로 Doze 에 넣습니다. 이 네 가지만 돌려도 출시 후 제보의 절반은 미리 잡힙니다."},{"h":"릴리스에서만 나는 버그는 종류가 정해져 있다","t":"디버그에서는 멀쩡한데 릴리스에서만 깨진다면 의심할 곳이 좁습니다 — <b>R8·ProGuard 난독화</b>(리플렉션으로 이름을 쓰는 JSON·직렬화가 깨짐), <b>네트워크 보안 설정</b>(평문 HTTP 차단), <b>서명·API 키 차이</b>, <b>최적화로 사라진 로그</b>. 릴리스 빌드를 <b>출시 전에 실제로 설치해 보는 것</b>이 유일한 방어입니다."}],"code":{"t":"재현부터 만든다","c":"# 프로세스 사망 재현 (개발자 옵션 대신 명령으로)\nadb shell am kill com.example.app\n\n# Doze 강제\nadb shell dumpsys deviceidle force-idle\n\n# 느린 네트워크\nadb shell settings put global captive_portal_mode 0","cap":"고치기 전에 '언제 나는지' 를 손에 쥔다"},"key":["증상보다 '어느 생명주기에서' 를 먼저 묻는다","프로세스 사망·비행기 모드·큰 글꼴·Doze 는 출시 전에 직접 만들어 본다","릴리스에서만 나는 버그는 난독화·보안 설정·서명을 먼저 본다","화면이 사라진 뒤 도착하는 콜백은 언제나 방어한다"]}},{"t":"디버깅 II","q":[{"t":"choice","k":"릴리스 전용 파싱 실패","cat":"debug","q":"디버그 빌드에서는 멀쩡한데 <b>릴리스 APK 에서만</b> 서버 응답의 모든 필드가 <code>null</code> 로 들어온다. 원인과 해결은?","code":"data class User(val userName: String, val age: Int)\n// 릴리스에서 user.userName == null","o":["난독화(R8)가 필드 이름을 바꿨는데 JSON 매핑이 이름에 의존한다. 모델 클래스를 <code>keep</code> 규칙으로 보호하거나 <code>@SerializedName</code> 으로 이름을 고정한다","릴리스는 서버 주소가 달라서다. 엔드포인트를 통일하면 해결된다","릴리스에서는 <code>data class</code> 의 기본값이 적용되지 않으므로 생성자를 직접 쓴다","네트워크 캐시가 오래된 응답을 주는 것이므로 캐시를 끄면 된다"],"a":0,"ex":"리플렉션으로 이름을 읽는 라이브러리는 난독화와 정면으로 충돌한다.\n💡 개념: R8 은 쓰이지 않아 보이는 이름을 짧게 바꾼다. JSON 파서는 실행 중에 '필드 이름' 으로 값을 찾으므로 이름이 바뀌면 매칭에 실패한다.\n🛠 실무: 모델에 keep 규칙을 두거나 직렬화 이름을 어노테이션으로 못 박는다. 출시 전 릴리스 빌드를 실제 기기에 설치해 한 바퀴 돌려 본다."},{"t":"choice","k":"릴리스 전용 네트워크 실패","cat":"debug","q":"사내 테스트 서버(<code>http://10.0.2.2:8080</code>)를 쓰는 화면이 릴리스 빌드에서만 연결에 실패한다. 예외는 <code>CleartextNotPermittedException</code> 이다. 원인과 해결은?","code":"<!-- AndroidManifest.xml -->\n<application android:usesCleartextTraffic=\"false\">","o":["에뮬레이터 전용 주소라서다. 실제 IP 로 바꾸면 릴리스에서도 된다","릴리스 빌드에 인터넷 권한이 빠진 것이므로 권한을 추가한다","안드로이드 9+ 는 평문 HTTP 를 기본 차단한다. HTTPS 로 바꾸거나, 개발 서버만 네트워크 보안 설정에서 예외로 허용한다","릴리스는 프록시를 타므로 프록시 설정을 꺼야 한다"],"a":2,"ex":"평문 HTTP 차단은 버그가 아니라 기본 정책이다.\n💡 개념: API 28 부터 앱은 기본적으로 HTTPS 만 쓴다. 디버그 빌드는 도구가 예외를 넣어 주는 경우가 많아 차이가 늦게 드러난다.\n🛠 실무: 운영은 무조건 HTTPS 로 가고, 개발 서버가 필요하면 network_security_config 에 도메인을 한정해 debug 빌드에만 적용한다."},{"t":"choice","k":"타임존 하루 밀림","cat":"debug","q":"일본·한국 사용자는 정상인데 <b>미국 사용자에게만</b> 주문 날짜가 하루 앞서 보인다는 제보가 온다. 원인과 해결은?","code":"// 서버: \"2026-03-05T15:00:00Z\"\nval d = SimpleDateFormat(\"yyyy-MM-dd\")\n         .format(Date(millis))   // 기기 로컬 타임존","o":["서버가 보낸 문자열의 <code>Z</code> 를 떼고 파싱하면 해결된다","UTC 시각을 기기 로컬 타임존으로 표시해 날짜 경계를 넘는다. '언제 일어났나' 는 UTC 로 저장하고, 표시할 타임존을 명시해 변환한다","미국은 서머타임이 있어 생기는 문제이므로 서머타임 보정을 더하면 된다","<code>SimpleDateFormat</code> 이 스레드 안전하지 않아 값이 섞인 것이다"],"a":1,"ex":"같은 순간도 어느 타임존에서 보느냐에 따라 날짜가 달라진다.\n💡 개념: UTC 15:00 은 한국에서는 다음 날 자정, 미국 서부에서는 같은 날 아침이다. 시각을 날짜로 줄이는 순간 타임존이 답을 바꾼다.\n🛠 실무: 저장·전송은 UTC(Instant), 표시만 사용자 타임존으로 변환한다. '생일' 처럼 타임존이 없는 값은 LocalDate 로 따로 다룬다."},{"t":"choice","k":"레이아웃 전 크기 측정","cat":"debug","q":"이미지를 화면 너비에 맞춰 자르려고 <code>onCreate</code> 에서 뷰 너비를 읽었더니 항상 0 이 나온다. 원인과 해결은?","code":"override fun onCreate(b: Bundle?) {\n  setContentView(R.layout.main)\n  val w = imageView.width   // 0\n}","o":["이미지가 아직 로드되지 않아서다. 이미지를 먼저 설정하면 너비가 잡힌다","<code>width</code> 대신 <code>measuredWidth</code> 를 쓰면 값이 들어온다","레이아웃 XML 의 <code>match_parent</code> 를 고정 dp 로 바꿔야 값이 생긴다","<code>onCreate</code> 시점에는 아직 측정·배치가 끝나지 않았다. <code>doOnLayout</code> 이나 <code>ViewTreeObserver</code> 로 배치 이후에 읽는다"],"a":3,"ex":"뷰의 크기는 '만들어질 때' 가 아니라 '배치될 때' 정해진다.\n💡 개념: onCreate 는 뷰 트리를 붙이기만 한다. 실제 measure/layout 패스는 그 뒤 프레임에서 일어나므로 그전에는 0 이다.\n🛠 실무: doOnLayout·post{} 로 배치 이후에 읽거나, 애초에 크기에 의존하지 않게 ConstraintLayout 비율·scaleType 으로 푼다."}],"th":{"sum":"모바일 버그의 상당수는 '내 기기에서는 됐는데' 로 시작합니다. 화면이 죽었다 살아나고, 네트워크가 끊기고, 시스템이 앱을 재우고, 사용자가 글꼴을 키우기 때문입니다.","body":[{"h":"증상은 대개 원인에서 멀리 떨어져 나타난다","t":"리스트를 스크롤했더니 <b>엉뚱한 항목에 배지가 붙는</b> 것은 리스트 코드의 버그가 아니라 <b>뷰를 재사용하면서 이전 상태를 지우지 않은</b> 탓이고, '가끔 크래시' 는 대개 <b>화면이 사라진 뒤 도착한 콜백</b>입니다. 그래서 모바일 디버깅은 <b>무엇이 일어났나</b> 보다 <b>언제·어떤 생명주기에서 일어났나</b> 를 먼저 묻습니다."},{"h":"재현 조건을 만들어야 고칠 수 있다","t":"가장 강력한 도구는 <b>강제로 나쁜 상황을 만드는 것</b>입니다 — 개발자 옵션의 <b>'액티비티 유지 안 함'</b> 으로 프로세스 사망을 재현하고, <b>비행기 모드</b>와 <b>네트워크 스로틀</b>로 끊김을 만들고, <b>글꼴 크기 최대</b>·<b>RTL 강제</b>로 레이아웃을 흔들고, <code>adb shell dumpsys deviceidle force-idle</code> 로 Doze 에 넣습니다. 이 네 가지만 돌려도 출시 후 제보의 절반은 미리 잡힙니다."},{"h":"릴리스에서만 나는 버그는 종류가 정해져 있다","t":"디버그에서는 멀쩡한데 릴리스에서만 깨진다면 의심할 곳이 좁습니다 — <b>R8·ProGuard 난독화</b>(리플렉션으로 이름을 쓰는 JSON·직렬화가 깨짐), <b>네트워크 보안 설정</b>(평문 HTTP 차단), <b>서명·API 키 차이</b>, <b>최적화로 사라진 로그</b>. 릴리스 빌드를 <b>출시 전에 실제로 설치해 보는 것</b>이 유일한 방어입니다."}],"code":{"t":"재현부터 만든다","c":"# 프로세스 사망 재현 (개발자 옵션 대신 명령으로)\nadb shell am kill com.example.app\n\n# Doze 강제\nadb shell dumpsys deviceidle force-idle\n\n# 느린 네트워크\nadb shell settings put global captive_portal_mode 0","cap":"고치기 전에 '언제 나는지' 를 손에 쥔다"},"key":["증상보다 '어느 생명주기에서' 를 먼저 묻는다","프로세스 사망·비행기 모드·큰 글꼴·Doze 는 출시 전에 직접 만들어 본다","릴리스에서만 나는 버그는 난독화·보안 설정·서명을 먼저 본다","화면이 사라진 뒤 도착하는 콜백은 언제나 방어한다"]}},{"t":"디버깅 III","q":[{"t":"choice","k":"키보드가 입력창을 가림","cat":"debug","q":"폼 화면 아래쪽 입력칸을 누르면 키보드가 올라오면서 <b>그 입력칸을 덮어</b> 무엇을 치는지 안 보인다. 원인과 해결은?","code":"<!-- 폼 전체가 스크롤 없는 ConstraintLayout -->\n<androidx.constraintlayout.widget.ConstraintLayout ...>","o":["키보드가 올라올 때 화면을 줄이거나 밀어 줄 방법이 없어서다. 폼을 스크롤 가능한 컨테이너에 넣고 <code>windowSoftInputMode=adjustResize</code> 를 준다","입력칸의 <code>inputType</code> 이 잘못돼서다. <code>textMultiLine</code> 으로 바꾸면 위로 올라온다","키보드 높이를 직접 계산해 <code>marginBottom</code> 을 코드로 넣는 수밖에 없다","전체 화면 테마를 쓰고 있어서다. 상태바를 보이게 하면 해결된다"],"a":0,"ex":"키보드는 화면을 덮는 창이라, 남은 공간에 맞춰 다시 배치해 줘야 한다.\n💡 개념: adjustResize 는 앱 영역을 키보드 위로 줄여 주고, 스크롤 컨테이너가 있어야 줄어든 공간 안에서 초점이 있는 곳으로 스크롤된다. 둘 중 하나만 있으면 효과가 없다.\n🛠 실무: 폼은 언제나 스크롤 가능하게 만들고, 최신 API 에서는 WindowInsets 로 키보드 높이를 받아 여백을 준다."},{"t":"choice","k":"알림이 뜨지 않음","cat":"debug","q":"푸시를 보내면 서버 로그에는 성공인데 <b>일부 기기에서만</b> 알림이 보이지 않는다. 오류도 없다. 가장 먼저 확인할 것은?","code":"NotificationCompat.Builder(ctx, \"orders\")\n  .setContentTitle(\"배송 시작\")\n  .build()","o":["알림 아이콘이 벡터라서 안 보이는 것이므로 PNG 로 바꾼다","푸시 토큰이 만료된 것이므로 앱 시작 시 토큰을 갱신한다","알림 채널 <code>orders</code> 가 만들어져 있는지, 그리고 안드로이드 13+ 의 알림 권한이 허용됐는지 확인한다","<code>build()</code> 만 하고 <code>notify()</code> 를 안 불렀는지 확인한다"],"a":2,"ex":"채널이 없거나 권한이 없으면 알림은 조용히 버려진다.\n💡 개념: 안드로이드 8+ 는 존재하지 않는 채널로 보낸 알림을 무시하고, 13+ 부터는 POST_NOTIFICATIONS 를 사용자가 허용해야 한다. 둘 다 예외를 던지지 않는다.\n🛠 실무: 앱 시작 시 채널을 미리 만들고, 권한은 알림이 필요한 맥락에서 요청한다. 사용자가 채널을 꺼 둔 경우도 확인해 안내한다."},{"t":"choice","k":"프로세스 사망 후 상태 소실","cat":"debug","q":"긴 글을 쓰다 카메라 앱으로 갔다 돌아오면 <b>가끔</b> 입력한 내용이 통째로 사라진다. 개발 기기에서는 재현이 잘 안 된다. 원인과 해결은?","code":"class WriteActivity : Activity() {\n  var draft = \"\"      // 메모리에만 있음\n}","o":["카메라 인텐트가 액티비티를 종료시키는 것이므로 <code>singleTask</code> 로 바꾼다","메모리가 부족하면 시스템이 백그라운드 프로세스를 죽인다. <code>onSaveInstanceState</code> 나 영구 저장소에 초안을 남겨 복원한다","가비지 컬렉터가 문자열을 회수한 것이므로 <code>draft</code> 를 <code>companion object</code> 로 옮긴다","화면 회전 때문이므로 <code>configChanges</code> 에 <code>orientation</code> 을 추가한다"],"a":1,"ex":"백그라운드 앱은 언제든 죽을 수 있고, 돌아올 때는 '처음부터' 다시 만들어진다.\n💡 개념: 시스템은 메모리가 필요하면 백그라운드 프로세스를 종료한다. 사용자는 뒤로 가기를 누른 적이 없으므로 앱이 상태를 복원해 주기를 기대한다.\n🛠 실무: 짧은 상태는 onSaveInstanceState·SavedStateHandle 로, 사용자가 공들인 입력은 로컬 DB 에 초안으로 저장한다. 개발자 옵션의 '액티비티 유지 안 함' 으로 상시 재현해 본다."},{"t":"choice","k":"사진이 눕는다","cat":"debug","q":"카메라로 찍은 사진을 앱에서 보면 <b>90도 돌아가 있는데</b> 갤러리 앱에서는 똑바로 보인다. 원인과 해결은?","code":"val bmp = BitmapFactory.decodeFile(path)\nimageView.setImageBitmap(bmp)","o":["이미지 뷰의 <code>scaleType</code> 이 잘못된 것이므로 <code>fitCenter</code> 로 바꾼다","카메라가 세로 모드를 지원하지 않아서다. 촬영 화면을 가로로 고정한다","디코딩할 때 <code>inPreferredConfig</code> 를 지정하지 않아 생기는 현상이다","JPEG 의 EXIF 방향 태그를 무시하고 픽셀만 읽어서다. EXIF 를 읽어 회전을 적용하거나, 그것을 처리해 주는 이미지 라이브러리를 쓴다"],"a":3,"ex":"많은 카메라는 픽셀을 돌리지 않고 '어느 방향으로 보라' 는 메모만 남긴다.\n💡 개념: JPEG 의 EXIF Orientation 태그가 그 메모다. 갤러리는 태그를 읽어 회전해 보여 주지만, 픽셀만 디코딩하면 원본 방향 그대로 나온다.\n🛠 실무: ExifInterface 로 태그를 읽어 Matrix 회전을 적용하거나, Glide·Coil 처럼 기본으로 처리해 주는 라이브러리를 쓴다. 서버에 올릴 때도 방향을 정규화해 두면 다른 클라이언트가 편하다."}],"th":{"sum":"모바일 버그의 상당수는 '내 기기에서는 됐는데' 로 시작합니다. 화면이 죽었다 살아나고, 네트워크가 끊기고, 시스템이 앱을 재우고, 사용자가 글꼴을 키우기 때문입니다.","body":[{"h":"증상은 대개 원인에서 멀리 떨어져 나타난다","t":"리스트를 스크롤했더니 <b>엉뚱한 항목에 배지가 붙는</b> 것은 리스트 코드의 버그가 아니라 <b>뷰를 재사용하면서 이전 상태를 지우지 않은</b> 탓이고, '가끔 크래시' 는 대개 <b>화면이 사라진 뒤 도착한 콜백</b>입니다. 그래서 모바일 디버깅은 <b>무엇이 일어났나</b> 보다 <b>언제·어떤 생명주기에서 일어났나</b> 를 먼저 묻습니다."},{"h":"재현 조건을 만들어야 고칠 수 있다","t":"가장 강력한 도구는 <b>강제로 나쁜 상황을 만드는 것</b>입니다 — 개발자 옵션의 <b>'액티비티 유지 안 함'</b> 으로 프로세스 사망을 재현하고, <b>비행기 모드</b>와 <b>네트워크 스로틀</b>로 끊김을 만들고, <b>글꼴 크기 최대</b>·<b>RTL 강제</b>로 레이아웃을 흔들고, <code>adb shell dumpsys deviceidle force-idle</code> 로 Doze 에 넣습니다. 이 네 가지만 돌려도 출시 후 제보의 절반은 미리 잡힙니다."},{"h":"릴리스에서만 나는 버그는 종류가 정해져 있다","t":"디버그에서는 멀쩡한데 릴리스에서만 깨진다면 의심할 곳이 좁습니다 — <b>R8·ProGuard 난독화</b>(리플렉션으로 이름을 쓰는 JSON·직렬화가 깨짐), <b>네트워크 보안 설정</b>(평문 HTTP 차단), <b>서명·API 키 차이</b>, <b>최적화로 사라진 로그</b>. 릴리스 빌드를 <b>출시 전에 실제로 설치해 보는 것</b>이 유일한 방어입니다."}],"code":{"t":"재현부터 만든다","c":"# 프로세스 사망 재현 (개발자 옵션 대신 명령으로)\nadb shell am kill com.example.app\n\n# Doze 강제\nadb shell dumpsys deviceidle force-idle\n\n# 느린 네트워크\nadb shell settings put global captive_portal_mode 0","cap":"고치기 전에 '언제 나는지' 를 손에 쥔다"},"key":["증상보다 '어느 생명주기에서' 를 먼저 묻는다","프로세스 사망·비행기 모드·큰 글꼴·Doze 는 출시 전에 직접 만들어 본다","릴리스에서만 나는 버그는 난독화·보안 설정·서명을 먼저 본다","화면이 사라진 뒤 도착하는 콜백은 언제나 방어한다"]}},{"t":"디버깅 IV","q":[{"t":"choice","k":"큰 글꼴에서 깨지는 레이아웃","cat":"debug","q":"접근성 설정에서 글꼴을 크게 한 사용자에게서 '버튼 글자가 잘려 보인다' 는 제보가 온다. 원인과 해결은?","code":"<Button\n  android:layout_height=\"40dp\"\n  android:textSize=\"14px\"\n  android:maxLines=\"1\" />","o":["글자 크기를 <code>px</code> 로 고정하고 높이도 고정해 늘어난 글자가 들어갈 자리가 없다. 글자는 <code>sp</code>, 높이는 내용에 맞게 두고 <code>minHeight</code> 로 최소만 보장한다","<code>maxLines</code> 를 2 로 늘리면 해결된다","시스템 글꼴 배율을 앱에서 1.0 으로 고정하는 것이 표준 해법이다","버튼 대신 텍스트뷰를 쓰면 잘리지 않는다"],"a":0,"ex":"고정 크기 + 고정 높이는 접근성 설정과 정면으로 충돌한다.\n💡 개념: sp 는 사용자의 글꼴 배율을 따르고 px·dp 는 따르지 않는다. 글자만 커지는데 담을 상자가 고정이면 잘리거나 밀려난다.\n🛠 실무: 글자는 sp, 상자는 wrap_content + minHeight. 출시 전 '글꼴 크기 최대' 로 주요 화면을 한 번 훑는다. 배율을 강제로 1.0 으로 막는 것은 접근성을 없애는 일이라 피한다."},{"t":"choice","k":"WebView 자바스크립트 다리","cat":"debug","q":"웹뷰에서 웹 페이지가 앱 기능을 부르도록 <code>addJavascriptInterface</code> 를 열어 두었다. 보안 검토에서 지적된 이유는?","code":"web.addJavascriptInterface(AppBridge(), \"App\")\nweb.loadUrl(userProvidedUrl)   // 외부 링크도 열림","o":["인터페이스 이름이 <code>App</code> 이라 흔해서 충돌한다. 고유한 이름으로 바꾸면 된다","메인 스레드에서 불리므로 ANR 위험이 있다. 스레드만 옮기면 보안 문제는 없다","웹뷰가 로드하는 <b>모든 페이지</b>가 그 다리를 부를 수 있다. 신뢰하는 도메인만 로드하도록 제한하고 노출 범위를 최소화한다","자바스크립트를 켜 두어서다. <code>javaScriptEnabled=false</code> 로 두면 인터페이스는 안전하게 유지된다"],"a":2,"ex":"다리는 '우리 페이지' 가 아니라 '웹뷰에 뜬 아무 페이지' 에게 열린다.\n💡 개념: 광고·리다이렉트·중간자 공격으로 다른 페이지가 로드되면 그 페이지의 스크립트가 그대로 네이티브 메서드를 호출할 수 있다.\n🛠 실무: 외부 링크는 웹뷰 대신 브라우저(Custom Tabs)로 열고, 다리를 꼭 써야 하면 허용 도메인을 검사한 뒤 @JavascriptInterface 로 최소한의 메서드만 노출한다."},{"t":"choice","k":"백그라운드 위치","cat":"debug","q":"달리기 기록 앱이 <b>화면이 켜져 있을 때는</b> 잘 되는데, 주머니에 넣고 화면을 끄면 경로가 뚝뚝 끊긴다. 원인과 해결은?","code":"// 매니페스트\n<uses-permission android:name=\"android.permission.ACCESS_FINE_LOCATION\"/>","o":["GPS 정확도 설정이 낮아서다. <code>PRIORITY_HIGH_ACCURACY</code> 로 바꾸면 화면이 꺼져도 계속 들어온다","화면이 꺼지면 시스템이 앱을 재우기 때문이다. 포그라운드 서비스로 승격하고, 필요하면 백그라운드 위치 권한을 따로 받는다","위치 갱신 주기가 너무 짧아 배터리 보호가 걸린 것이므로 주기를 늘리면 해결된다","화면이 꺼지면 좌표가 캐시에서 오므로 캐시를 끄면 된다"],"a":1,"ex":"'앱이 보이는 동안' 과 '보이지 않는 동안' 은 완전히 다른 규칙을 받는다.\n💡 개념: 화면이 꺼지면 앱은 백그라운드로 내려가 위치 갱신이 제한되고, 나아가 Doze 에 들어간다. 백그라운드 위치는 별도 권한이며 사용자가 따로 허용해야 한다.\n🛠 실무: 사용자가 인지하는 지속 작업은 알림을 띄우는 포그라운드 서비스로 만든다. 그것이 '지금 위치를 쓰고 있다' 를 사용자에게 알리는 정직한 방법이기도 하다."},{"t":"choice","k":"재설치 후 사라진 데이터","cat":"debug","q":"오프라인에서 저장한 메모가 <b>앱을 지웠다 다시 깔면</b> 사라지고, 기기를 바꿔도 넘어오지 않는다. 캐시 정리를 해도 사라진다는 제보가 있다. 원인과 해결은?","code":"val f = File(context.cacheDir, \"notes.json\")\nf.writeText(json)","o":["JSON 파일이 커서 시스템이 압축한 것이므로 DB 로 바꾸면 유지된다","<code>writeText</code> 가 버퍼를 비우지 않아서다. <code>flush()</code> 를 부르면 남는다","사용자 데이터를 캐시 디렉터리에 두었다. 지워도 되는 것만 캐시에 두고, 사라지면 안 되는 것은 파일·DB 영역에 저장한 뒤 자동 백업 대상에 포함한다","외부 저장소 권한이 없어서다. 권한을 받으면 유지된다"],"a":2,"ex":"캐시 디렉터리는 '언제 지워도 되는 곳' 이라고 시스템에 선언한 공간이다.\n💡 개념: 저장 공간이 부족하면 시스템이 캐시를 먼저 비우고, 사용자도 설정에서 캐시만 지울 수 있다. 앱 삭제 시에는 어느 쪽이든 사라진다.\n🛠 실무: 다시 만들 수 있는 것만 cacheDir 에, 사용자가 만든 것은 filesDir·Room 에 둔다. 기기 이동까지 살리려면 자동 백업이나 서버 동기화가 필요하다."}],"th":{"sum":"모바일 버그의 상당수는 '내 기기에서는 됐는데' 로 시작합니다. 화면이 죽었다 살아나고, 네트워크가 끊기고, 시스템이 앱을 재우고, 사용자가 글꼴을 키우기 때문입니다.","body":[{"h":"증상은 대개 원인에서 멀리 떨어져 나타난다","t":"리스트를 스크롤했더니 <b>엉뚱한 항목에 배지가 붙는</b> 것은 리스트 코드의 버그가 아니라 <b>뷰를 재사용하면서 이전 상태를 지우지 않은</b> 탓이고, '가끔 크래시' 는 대개 <b>화면이 사라진 뒤 도착한 콜백</b>입니다. 그래서 모바일 디버깅은 <b>무엇이 일어났나</b> 보다 <b>언제·어떤 생명주기에서 일어났나</b> 를 먼저 묻습니다."},{"h":"재현 조건을 만들어야 고칠 수 있다","t":"가장 강력한 도구는 <b>강제로 나쁜 상황을 만드는 것</b>입니다 — 개발자 옵션의 <b>'액티비티 유지 안 함'</b> 으로 프로세스 사망을 재현하고, <b>비행기 모드</b>와 <b>네트워크 스로틀</b>로 끊김을 만들고, <b>글꼴 크기 최대</b>·<b>RTL 강제</b>로 레이아웃을 흔들고, <code>adb shell dumpsys deviceidle force-idle</code> 로 Doze 에 넣습니다. 이 네 가지만 돌려도 출시 후 제보의 절반은 미리 잡힙니다."},{"h":"릴리스에서만 나는 버그는 종류가 정해져 있다","t":"디버그에서는 멀쩡한데 릴리스에서만 깨진다면 의심할 곳이 좁습니다 — <b>R8·ProGuard 난독화</b>(리플렉션으로 이름을 쓰는 JSON·직렬화가 깨짐), <b>네트워크 보안 설정</b>(평문 HTTP 차단), <b>서명·API 키 차이</b>, <b>최적화로 사라진 로그</b>. 릴리스 빌드를 <b>출시 전에 실제로 설치해 보는 것</b>이 유일한 방어입니다."}],"code":{"t":"재현부터 만든다","c":"# 프로세스 사망 재현 (개발자 옵션 대신 명령으로)\nadb shell am kill com.example.app\n\n# Doze 강제\nadb shell dumpsys deviceidle force-idle\n\n# 느린 네트워크\nadb shell settings put global captive_portal_mode 0","cap":"고치기 전에 '언제 나는지' 를 손에 쥔다"},"key":["증상보다 '어느 생명주기에서' 를 먼저 묻는다","프로세스 사망·비행기 모드·큰 글꼴·Doze 는 출시 전에 직접 만들어 본다","릴리스에서만 나는 버그는 난독화·보안 설정·서명을 먼저 본다","화면이 사라진 뒤 도착하는 콜백은 언제나 방어한다"]}}],"ord":7},{"t":"시뮬레이션 · 눈으로 보는 코드","l":[{"t":"시뮬레이션 I","q":[{"t":"sim","k":"생명주기 시뮬레이션","lv":2,"cat":"internals","q":"화면 <b>회전</b>이 일어날 때의 생명주기 콜백을 기록하세요. 회전은 액티비티를 <b>파괴하고 다시 만듭니다</b>: <code>onPause → onStop → onDestroy → onCreate → onStart → onResume</code>. 이때 <b>필드에만 담아 둔 값은 사라지고</b>, 저장 번들(<code>onSaveInstanceState</code>)에 넣은 값만 살아남습니다. 콜백마다 <code>snap(콜백, {field, bundle}, {phase})</code> 를 남기고 <b>[콜백 순서 배열, 회전 뒤 필드 값, 회전 뒤 복원된 값]</b> 을 돌려주세요. 사용자가 입력한 값은 <code>'초안'</code> 입니다.","src":"const TYPED = '초안';\nconst ROTATE = ['onPause', 'onSaveInstanceState', 'onStop', 'onDestroy', 'onCreate', 'onStart', 'onResume'];\n\nfunction rotate() {\n  return [[], null, ''];\n}\n\nRESULT = rotate();","tests":[{"d":"파괴와 재생성이 모두 일어난다","js":"RESULT[0].indexOf('onDestroy')>=0&&RESULT[0].indexOf('onCreate')>RESULT[0].indexOf('onDestroy')"},{"d":"필드에만 담은 값은 사라진다","js":"RESULT[1]===null"},{"d":"번들에 넣은 값은 복원된다","js":"RESULT[2]==='초안'"},{"d":"콜백마다 장면이 남는다","js":"FRAMES.length===7"},{"d":"저장은 onStop 보다 먼저 일어난다","js":"RESULT[0].indexOf('onSaveInstanceState')<RESULT[0].indexOf('onStop')"},{"d":"onDestroy 시점에 필드가 비워진다","js":"FRAMES[3].value.field===null&&FRAMES[3].value.bundle==='초안'"}],"ex":"회전은 단순한 화면 전환이 아니라 <b>액티비티를 통째로 다시 만드는</b> 사건입니다 — 그래서 필드에 담아 둔 입력값·스크롤 위치·진행 상태가 사라집니다. '회전하면 입력이 날아간다' 는 버그 신고의 정체이고, 같은 일이 <b>언어 변경·다크 모드 전환·시스템이 메모리를 회수할 때</b>도 일어납니다. 살릴 값은 <code>onSaveInstanceState</code> 번들에 넣거나 <b>ViewModel</b> 처럼 재생성을 견디는 곳에 둬야 합니다. 다만 번들은 <b>작은 값만</b>(수십 KB) 담아야 합니다 — 큰 목록이나 비트맵을 넣으면 <code>TransactionTooLargeException</code> 으로 앱이 죽습니다. 큰 데이터는 <b>다시 불러오거나 디스크</b>에 둡니다."},{"t":"sim","k":"성능 시뮬레이션","lv":3,"cat":"internals","q":"<b>60fps 프레임 예산은 16.7ms</b> 입니다. 메인 스레드에서 하는 일들의 시간을 더해 프레임을 넘기는지 보고, 넘긴 만큼 <b>프레임을 떨어뜨립니다</b>(드롭 수 = <code>floor(초과분 / 16.7)</code>). 작업마다 <code>snap(작업, {sum, over}, {ms})</code> 를 남기고 <b>[총 소요 ms(소수 첫째 자리), 예산 초과 ms(소수 첫째 자리), 떨어진 프레임 수, 이미지 디코딩을 백그라운드로 옮겼을 때의 총 ms]</b> 를 돌려주세요.","src":"const BUDGET = 16.7;\nconst WORK = [\n  { name: '레이아웃 측정', ms: 4.2, main: true },\n  { name: '이미지 디코딩', ms: 38.0, main: true, offloadable: true },\n  { name: '뷰 그리기',    ms: 6.1, main: true },\n  { name: '어댑터 바인딩', ms: 2.4, main: true }\n];\n\nfunction frame() {\n  return [0, 0, 0, 0];\n}\n\nRESULT = frame();","tests":[{"d":"총 50.7ms 가 걸린다","js":"RESULT[0]===50.7"},{"d":"예산을 34ms 넘긴다","js":"RESULT[1]===34"},{"d":"프레임 2개가 떨어진다","js":"RESULT[2]===2"},{"d":"디코딩을 옮기면 12.7ms 로 예산 안에 든다","js":"RESULT[3]===12.7&&RESULT[3]<16.7"},{"d":"작업마다 장면이 남는다","js":"FRAMES.length===4"},{"d":"디코딩 하나가 예산을 넘긴 주범이다","js":"FRAMES[0].value.over<=0&&FRAMES[1].value.over>0"}],"ex":"부드러움의 기준은 평균이 아니라 <b>가장 느린 프레임</b>입니다 — 16.7ms 를 한 번 넘길 때마다 화면이 눈에 띄게 끊깁니다(jank). 여기서 범인은 <b>이미지 디코딩 38ms</b> 하나이고, 그것만 백그라운드로 옮기면 나머지 12.7ms 는 예산 안에 들어옵니다. 메인 스레드에서 하면 안 되는 일의 목록은 늘 비슷합니다: <b>디코딩·파일 IO·네트워크·DB 쿼리·JSON 파싱</b>. 반대로 <b>반드시 메인에서</b> 해야 하는 것은 UI 갱신뿐입니다. 진단은 추측하지 말고 도구로 합니다 — 안드로이드는 Systrace·Perfetto, iOS 는 Instruments 로 <b>어느 프레임이 몇 ms 였는지</b>를 먼저 봅니다."},{"t":"sim","k":"네트워크 시뮬레이션","lv":3,"cat":"internals","q":"오프라인 동안 쌓인 요청을 <b>지수 백오프</b>로 다시 보내세요. 첫 재시도는 1초 뒤이고 실패할 때마다 <b>두 배</b>, 상한은 <b>32초</b> 입니다. 네트워크는 <b>7번째 시도 시각 이후</b>에 살아납니다. 시도마다 <code>snap('시도 '+n, {at, delay, ok}, {n})</code> 을 남기고 <b>[성공까지의 시도 횟수, 성공한 시각(초), 상한에 걸린 시도 수]</b> 를 돌려주세요.","src":"const FIRST = 1, MAX_DELAY = 32, ONLINE_AFTER = 6;   // 6번째 시도 뒤 복구\nconst LIMIT = 10;\n\nfunction retry() {\n  return [0, 0, 0];\n}\n\nRESULT = retry();","tests":[{"d":"7번째 시도에서 성공한다","js":"RESULT[0]===7"},{"d":"성공 시각은 95초","js":"RESULT[1]===95"},{"d":"상한 32초에 걸린 시도가 2번","js":"RESULT[2]===2"},{"d":"시도마다 장면이 남는다","js":"FRAMES.length===7"},{"d":"대기가 두 배씩 늘어난다","js":"FRAMES[1].value.delay===2&&FRAMES[2].value.delay===4"},{"d":"상한을 넘지 않는다","js":"FRAMES.every(function(f){return f.value.delay<=32;})"}],"ex":"모바일 네트워크는 <b>끊기는 것이 정상</b>이라 재시도는 선택이 아닙니다. 다만 즉시 재시도를 반복하면 <b>배터리와 서버를 함께 태웁니다</b> — 그래서 대기를 두 배씩 늘리고(지수 백오프) 상한을 둡니다. 여기서 성공까지 95초가 걸렸는데, 이 값이 크다고 나쁜 것이 아닙니다: 사용자는 이미 앱을 떠났고 <b>큐가 대신 기다려 주는 것</b>이 목적입니다. 실무에서 꼭 얹어야 할 것 둘 — <b>지터</b>(모두가 같은 순간에 몰려 서버를 때리는 것을 막습니다)와 <b>멱등 키</b>(성공 응답을 못 받고 재시도하면 주문이 두 번 들어갑니다). 그리고 실제 전송은 <code>WorkManager</code> 처럼 <b>OS 가 관리하는 작업</b>에 맡겨야 앱이 죽어도 이어집니다."},{"t":"sim","k":"성능 시뮬레이션","lv":3,"cat":"internals","q":"리스트의 <b>뷰 재활용</b>을 모델링하세요. 화면에는 <b>10개</b>가 보이고 재활용 풀은 <b>화면에서 벗어난 뷰</b>를 담습니다. 새 항목이 들어올 때 풀이 비어 있으면 <b>새로 만들고</b>(inflate), 있으면 꺼내 씁니다. 1,000개를 끝까지 스크롤하며 10칸마다 <code>snap(위치, {created, reused}, {pos})</code> 를 남기고 <b>[만들어진 뷰의 총 개수, 재사용 횟수, 재활용을 쓰지 않았다면 만들어졌을 개수]</b> 를 돌려주세요.","src":"const VISIBLE = 10, TOTAL = 1000;\n\nfunction recycler() {\n  return [0, 0, 0];\n}\n\nRESULT = recycler();","tests":[{"d":"뷰는 11개만 만들어진다","js":"RESULT[0]===11"},{"d":"989번 재사용된다","js":"RESULT[1]===989"},{"d":"재활용이 없었다면 1,000개를 만들어야 한다","js":"RESULT[2]===1000"},{"d":"10칸마다 장면이 남는다","js":"FRAMES.length===100"},{"d":"초반에 만들고 나면 더 만들지 않는다","js":"FRAMES[99].value.created===FRAMES[1].value.created"},{"d":"재사용 횟수만 계속 는다","js":"FRAMES[99].value.reused>FRAMES[1].value.reused"}],"ex":"리스트가 버벅이는 가장 흔한 이유는 <b>뷰를 계속 새로 만드는 것</b>입니다. 재활용이 있으면 화면에 보이는 수(+여유 1개)만 만들고 나머지 989번은 <b>있던 뷰에 데이터만 갈아 끼웁니다</b> — 뷰 하나 만드는 비용(XML 인플레이트·객체 할당)이 데이터 바인딩보다 훨씬 크기 때문에 이 차이가 곧 스크롤 성능입니다. 그래서 <code>onBindViewHolder</code> 는 <b>가볍게</b> 유지해야 하고(거기서 이미지를 디코딩하거나 날짜 포매터를 새로 만들면 안 됩니다), 재사용되는 뷰이므로 <b>이전 항목의 상태를 반드시 초기화</b>해야 합니다 — 안 하면 스크롤할 때 엉뚱한 항목에 체크 표시가 남는 유명한 버그가 납니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 II","q":[{"t":"sim","k":"전력 시뮬레이션","lv":3,"cat":"internals","q":"위치 갱신 <b>주기</b>가 배터리에 미치는 영향을 계산하세요. GPS 를 한 번 켜면 <b>3초</b> 동안 <b>80mA</b> 를 쓰고 대기 전류는 <b>2mA</b> 입니다. 배터리는 3,000mAh 입니다. 설정마다 <code>snap(라벨, {avgMa, hours}, {periodSec})</code> 을 남기고 <b>[5초 주기의 사용 가능 시간(시간, 반올림), 60초 주기의 시간, 몇 배 늘어나는지(반올림)]</b> 를 돌려주세요.","src":"const BATTERY = 3000, GPS_MA = 80, IDLE_MA = 2, FIX_SEC = 3;\nconst PERIODS = [5, 60];\n\nfunction location() {\n  return [0, 0, 0];\n}\n\nRESULT = location();","tests":[{"d":"5초 주기면 약 61시간","js":"RESULT[0]===61"},{"d":"60초 주기면 약 508시간","js":"RESULT[1]===508"},{"d":"8배 넘게 늘어난다","js":"RESULT[2]===8"},{"d":"설정마다 장면이 남는다","js":"FRAMES.length===2"},{"d":"5초 주기의 평균 전류는 48.8mA — 대기 전류의 24배","js":"FRAMES[0].value.avgMa===48.8"},{"d":"60초 주기는 대기 전류에 가까워진다","js":"FRAMES[1].value.avgMa<8"}],"ex":"위치 정확도와 배터리는 <b>정면으로 맞바꾸는</b> 관계입니다 — 5초마다 GPS 를 켜면 2.5일, 60초로 늘리면 21일을 갑니다. 그래서 실무의 질문은 '얼마나 정확하게' 가 아니라 <b>'이 화면에 정말 그 정확도가 필요한가'</b> 입니다. 배달 추적 화면이 열려 있을 때만 촘촘히 받고, 백그라운드에서는 주기를 늘리거나 <b>지오펜스·중요 위치 변경</b>처럼 OS 가 대신 감시해 주는 저전력 API 로 바꿉니다. 덧붙여 <b>정확도를 낮게 요청하면</b>(네트워크 기반 위치) GPS 칩을 켜지 않아 전류가 한 자릿수로 떨어집니다 — 사용자가 체감하는 배터리 평판은 대개 이 선택에서 갈립니다."},{"t":"sim","k":"메모리 시뮬레이션","lv":3,"cat":"internals","q":"이미지 <b>메모리 캐시</b>를 모델링하세요. 한 장은 <code>가로×세로×4바이트</code>(ARGB_8888)를 차지하고 캐시 한도는 <b>24MB</b> 입니다. 한도를 넘으면 <b>가장 오래 쓰지 않은 것부터</b> 버립니다. 이미지를 넣을 때마다 <code>snap(이미지, {usedMb, count}, {evicted})</code> 를 남기고 <b>[원본 크기로 담을 수 있는 장수, 목록 표시용으로 4분의 1 크기로 줄여 담을 때의 장수, 원본을 12장 넣는 동안 버려진 장수]</b> 를 돌려주세요. 이미지는 모두 2000×1500 입니다.","src":"const LIMIT_MB = 24, W = 2000, H = 1500, BYTES = 4;\nconst LOADS = 12;\n\nfunction imageCache() {\n  return [0, 0, 0];\n}\n\nRESULT = imageCache();","tests":[{"d":"원본은 2장밖에 못 담는다","js":"RESULT[0]===2"},{"d":"가로·세로를 절반으로 줄이면 8장","js":"RESULT[1]===8"},{"d":"12장을 넣는 동안 10장이 버려진다","js":"RESULT[2]===10"},{"d":"이미지마다 장면이 남는다","js":"FRAMES.length===12"},{"d":"캐시가 한도를 넘지 않는다","js":"FRAMES.every(function(f){return f.value.usedMb<=24;})"},{"d":"3장째부터 버리기 시작한다","js":"FRAMES[2].opt.evicted===1&&FRAMES[1].opt.evicted===0"}],"ex":"비트맵은 <b>파일 크기가 아니라 픽셀 수</b>로 메모리를 먹습니다 — 300KB 짜리 JPEG 도 2000×1500 으로 펼치면 <b>11.4MB</b> 입니다. 그래서 목록에 원본을 그대로 올리면 캐시가 두 장 만에 차고, 스크롤할 때마다 버리고 다시 디코딩하는 <b>최악의 반복</b>이 시작됩니다(그러다 <code>OutOfMemory</code>). 해법은 언제나 <b>표시할 크기로 줄여서 디코딩</b>하는 것입니다 — 가로·세로를 절반으로만 줄여도 메모리는 <b>4분의 1</b>이라 같은 한도에 8장이 들어갑니다. 여기에 <code>RGB_565</code> 같은 포맷 선택(절반), 디스크 캐시 병행, 화면 밖 이미지 요청 취소를 얹으면 됩니다."},{"t":"sim","k":"성능 시뮬레이션","lv":2,"cat":"internals","q":"<b>콜드 스타트</b> 시간을 단계별로 쌓아 보세요. 목표는 <b>2,000ms 안에 첫 화면</b>입니다. 초기화 중 <b>지연 가능</b>(lazy)으로 표시된 것은 첫 화면 뒤로 미룰 수 있습니다. 단계마다 <code>snap(단계, {sum, overBudget}, {ms, lazy})</code> 를 남기고 <b>[전부 앞에서 할 때의 총 ms, 지연 가능한 것을 미뤘을 때의 총 ms, 목표를 지키는지, 미룬 작업의 수]</b> 를 돌려주세요.","src":"const BUDGET_MS = 2000;\nconst STEPS = [\n  { name: '프로세스 생성',   ms: 300 },\n  { name: 'DI 그래프 구성',  ms: 250 },\n  { name: '분석 SDK 초기화', ms: 400, lazy: true },\n  { name: '광고 SDK 초기화', ms: 520, lazy: true },\n  { name: 'DB 마이그레이션', ms: 180, lazy: true },\n  { name: '첫 화면 레이아웃', ms: 260 },\n  { name: '첫 데이터 요청',   ms: 340 }\n];\n\nfunction coldStart() {\n  return [0, 0, false, 0];\n}\n\nRESULT = coldStart();","tests":[{"d":"전부 앞에서 하면 2,250ms","js":"RESULT[0]===2250"},{"d":"미루면 1,150ms","js":"RESULT[1]===1150"},{"d":"그때 2초 목표를 지킨다","js":"RESULT[2]===true"},{"d":"미룬 작업은 3개","js":"RESULT[3]===3"},{"d":"단계마다 장면이 남는다","js":"FRAMES.length===7"},{"d":"SDK 두 개만으로 920ms 를 쓴다","js":"FRAMES[3].value.sum-FRAMES[1].value.sum===920"},{"d":"그대로 두면 예산을 넘는다","js":"FRAMES[6].value.overBudget===true"}],"ex":"콜드 스타트는 <b>사용자가 앱을 처음 판단하는 2초</b>입니다. 그런데 그 2초를 갉아먹는 것은 대개 우리 코드가 아니라 <b>초기화되는 SDK 들</b>입니다 — 여기서도 분석·광고 SDK 둘이 920ms 를 씁니다. 규칙은 하나입니다: <b>첫 화면을 그리는 데 필요 없는 것은 전부 뒤로</b>. 안드로이드의 <code>App Startup</code> 라이브러리나 지연 초기화로 미루고, DB 마이그레이션처럼 무거운 작업은 <b>백그라운드 + 로딩 상태</b>로 처리합니다. 측정 없이 손대면 엉뚱한 곳을 고치게 되므로, 먼저 <b>단계별 시간</b>부터 찍어 봐야 합니다 — 우리 코드는 이미 충분히 빠른데 SDK 하나가 절반을 먹고 있는 경우가 흔합니다."},{"t":"sim","k":"네트워크 시뮬레이션","lv":4,"cat":"internals","q":"모바일 <b>라디오</b>는 한 번 깨면 전송이 끝난 뒤에도 <b>10초 동안 고전력 상태(tail)</b>로 남습니다. 요청을 따로따로 보낼 때와 <b>한 번에 묶어</b> 보낼 때의 고전력 시간을 비교하세요. 요청은 각각 1초씩 걸립니다. 방식마다 <code>snap(방식, {highPowerSec, wakeups}, {mode})</code> 를 남기고 <b>[따로 보낼 때의 고전력 시간(초), 묶어 보낼 때의 시간, 절감 비율(%, 반올림)]</b> 을 돌려주세요.","src":"const TAIL_SEC = 10, SEND_SEC = 1;\n// 요청이 발생하는 시각(초) — 서로 15초 넘게 떨어져 있어 따로 보내면 매번 라디오가 깬다\nconst REQUESTS = [0, 20, 40, 60, 80];\nconst BATCH_AT = 80;   // 묶으면 마지막 시점에 한 번에 보낸다\n\nfunction radio() {\n  return [0, 0, 0];\n}\n\nRESULT = radio();","tests":[{"d":"따로 보내면 고전력 55초","js":"RESULT[0]===55"},{"d":"묶어 보내면 15초","js":"RESULT[1]===15"},{"d":"73% 를 아낀다","js":"RESULT[2]===73"},{"d":"두 방식이 장면으로 남는다","js":"FRAMES.length===2"},{"d":"따로 보내면 라디오가 5번 깬다","js":"FRAMES[0].value.wakeups===5"},{"d":"묶으면 한 번만 깬다","js":"FRAMES[1].value.wakeups===1"}],"ex":"모바일 데이터에서 <b>비싼 것은 바이트가 아니라 라디오를 깨우는 일</b>입니다. 전송이 1초라도 라디오는 그 뒤 <b>10초 남짓 고전력 상태</b>로 머물다 내려가므로(tail energy), 5번 따로 보내면 55초를 태우고 한 번에 묶으면 15초로 끝납니다. 그래서 배터리를 아끼는 실무 기법은 압축보다 <b>스케줄링</b>입니다 — 급하지 않은 로그·분석·프리페치는 모아 두었다가 <b>다른 요청이 나갈 때 같이</b> 보내거나(piggyback), <code>WorkManager</code>·<code>JobScheduler</code> 에 맡겨 <b>충전 중·와이파이</b> 조건에서 처리합니다. 반대로 5초마다 상태를 폴링하는 코드는 화면이 꺼져 있어도 라디오를 계속 깨우는, 배터리 평판을 무너뜨리는 대표적인 패턴입니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 III","q":[{"t":"sim","k":"권한 시뮬레이션","lv":3,"cat":"internals","q":"런타임 권한 요청의 상태 변화를 재현하세요. 규칙 — 처음 요청하면 <b>시스템 다이얼로그</b>가 뜹니다. 한 번 거부당한 뒤 다시 요청할 때는 <b>왜 필요한지 먼저 설명해야</b> 하고(근거 화면), 다이얼로그는 뜹니다. <b>두 번 거부되면 영구 거부</b>가 되어 이후 요청은 <b>다이얼로그 없이 즉시 거부</b>되고, 남은 길은 <b>설정 화면으로 보내는 것</b>뿐입니다. 사건마다 <code>snap(사건, {상태, 거부수, 다이얼로그})</code> 를 남기고 <b>[다이얼로그가 뜬 횟수, 근거 화면이 필요했던 횟수, 자동 거부된 횟수, 최종 상태, 설정으로 보내야 하는가]</b> 를 돌려주세요.","src":"const EVENTS = ['요청', '거부', '요청', '거부', '요청', '요청'];\n\nfunction scene() {\n  return [0, 0, 0, '', false];\n}\n\nRESULT = scene();","tests":[{"d":"다이얼로그는 두 번만 뜬다","js":"RESULT[0]===2"},{"d":"두 번째 요청 전에 근거 화면이 필요하다","js":"RESULT[1]===1"},{"d":"영구 거부 뒤 두 번의 요청은 그냥 튕긴다","js":"RESULT[2]===2"},{"d":"최종 상태는 영구 거부","js":"RESULT[3]==='영구거부'"},{"d":"이제 설정 화면으로 보내는 수밖에 없다","js":"RESULT[4]===true"},{"d":"여섯 사건이 장면으로 남는다","js":"FRAMES.length===6"},{"d":"다섯 번째부터는 다이얼로그가 뜨지 않는다","js":"FRAMES[4].value.다이얼로그===false"}],"ex":"권한은 <b>'물어보면 되는 것' 이 아니라 기회가 정해진 자원</b>입니다 — 두 번 거부당하면 시스템이 <b>다이얼로그 자체를 띄워 주지 않고</b>, 그 뒤로는 사용자가 직접 설정에 들어가야 합니다. 그래서 설계 순서가 중요합니다: ① <b>앱을 켜자마자 몰아서 묻지 마세요</b> — 맥락 없이 뜬 권한 요청은 거부율이 훨씬 높고, 한 번 거부되면 두 번째 기회밖에 안 남습니다. ② <b>그 기능을 실제로 쓰려는 순간</b> 요청하세요(사진을 고르려 할 때 갤러리 권한). ③ 거부당한 뒤 다시 물을 때는 <code>shouldShowRequestPermissionRationale</code> 로 <b>먼저 이유를 설명</b>하고, 그래도 싫다면 <b>권한 없이 동작하는 대안</b>을 주세요(정확한 위치 대신 도시 직접 입력). ④ 영구 거부 상태에서는 요청을 반복해도 콜백이 <b>즉시 거부로 돌아올 뿐</b>이니, 안내 문구와 <b>설정 화면 딥링크</b>를 띄우는 것이 유일한 정답입니다. 참고로 사용자가 설정에서 권한을 껐다 켜면 상태가 <b>초기화</b>되기도 하므로, 영구 거부를 앱 안에 <b>영구히 기록해 두면 안 됩니다</b>."},{"t":"sim","k":"화면 시뮬레이션","lv":2,"cat":"internals","q":"<code>dp</code> 와 <code>px</code> 를 오가며 밀도별 자산이 몇 개나 필요한지 세세요. <b>1dp = 1px × 배율</b> 이고 배율은 mdpi 1 · hdpi 1.5 · xhdpi 2 · xxhdpi 3 · xxxhdpi 4 입니다. 48dp 버튼을 밀도마다 몇 px 로 그려야 하는지 계산하며 <code>snap(밀도, {배율, px, 픽셀수})</code> 를 남기고 <b>[xxhdpi 에서 48dp 는 몇 px, 가로 1080px 인 xxhdpi 기기의 dp 폭, 비트맵으로 전부 준비할 때 필요한 자산 수, 다섯 자산의 픽셀 수 합, 벡터로 만들면 필요한 자산 수]</b> 를 돌려주세요.","src":"const DENSITIES = [\n  { name: 'mdpi',    s: 1   },\n  { name: 'hdpi',    s: 1.5 },\n  { name: 'xhdpi',   s: 2   },\n  { name: 'xxhdpi',  s: 3   },\n  { name: 'xxxhdpi', s: 4   }\n];\nconst DP = 48, SCREEN_PX = 1080;\n\nfunction scene() {\n  return [0, 0, 0, 0, 0];\n}\n\nRESULT = scene();","tests":[{"d":"48dp × 3 = 144px","js":"RESULT[0]===144"},{"d":"1080px 을 3 으로 나누면 360dp","js":"RESULT[1]===360"},{"d":"비트맵은 밀도마다 하나씩 다섯 개","js":"RESULT[2]===5"},{"d":"다섯 자산의 픽셀 수를 더하면 74,304","js":"RESULT[3]===74304"},{"d":"벡터는 하나면 된다","js":"RESULT[4]===1"},{"d":"다섯 밀도가 장면으로 남는다","js":"FRAMES.length===5"},{"d":"배율이 오를수록 픽셀 수가 급격히 는다","js":"FRAMES[4].value.픽셀수 > FRAMES[0].value.픽셀수*15"}],"ex":"<b>dp 는 '어느 기기에서나 같은 크기로 보이는 단위'</b> 이고, px 는 그것을 그 기기의 밀도로 환산한 결과입니다. 그래서 레이아웃은 <b>언제나 dp 로</b> 적어야 하고, px 를 직접 쓰면 고밀도 기기에서 버튼이 손톱만 해집니다(반대로 글자는 <code>sp</code> 를 쓰세요 — 사용자가 키운 글꼴 크기를 따라갑니다). 자산 쪽에서 중요한 것은 <b>픽셀 수가 배율의 제곱으로 는다</b>는 점입니다: 4배 밀도 자산 하나가 1배 자산 <b>16장</b> 몫의 메모리와 용량을 씁니다. 그래서 실무 규칙은 셋입니다 — <b>아이콘·단순 도형은 벡터</b>(<code>VectorDrawable</code>·SVG)로 만들어 자산 하나로 끝내고, <b>사진은 서버가 기기 밀도에 맞는 크기를 내려주게</b> 하고, 어쩔 수 없이 비트맵을 넣는다면 <b>앱 번들의 밀도 분할</b>로 사용자가 자기 밀도 것만 받게 하세요. 그리고 <b>화면이 1080px 이어도 앱이 보는 것은 360dp</b> 라는 감각을 가지면, '왜 큰 화면인데 더 담기지 않지' 같은 오해가 사라집니다."},{"t":"sim","k":"성능 시뮬레이션","lv":4,"cat":"internals","q":"레이아웃을 깊게 중첩하면 <b>측정이 몇 배로 늘어나는지</b> 세세요. 규칙 — <b>가중치가 걸린 컨테이너는 자식을 두 번 측정</b>합니다(한 번은 크기를 알아보려고, 한 번은 남은 공간을 나눠 주려고). 이런 컨테이너가 <code>d</code> 겹 중첩되면 가장 안쪽 자식은 <b>2<sup>d</sup></b> 번 측정됩니다. 깊이 1~5 를 계산하며 <code>snap(\"깊이 \"+d, {자식1개, 자식10개})</code> 를 남기고 <b>[깊이 3 에서 자식 하나의 측정 횟수, 깊이 5 에서의 측정 횟수, 자식 10개를 깊이 3 에 둘 때 총 측정 횟수, 깊이 1 로 폈을 때 총 측정 횟수, 몇 배 줄었나]</b> 를 돌려주세요.","src":"const DEPTHS = [1, 2, 3, 4, 5];\nconst CHILDREN = 10;\n\nfunction scene() {\n  return [0, 0, 0, 0, 0];\n}\n\nRESULT = scene();","tests":[{"d":"깊이 3 이면 2³ = 8번","js":"RESULT[0]===8"},{"d":"깊이 5 면 32번","js":"RESULT[1]===32"},{"d":"자식 10개면 80번","js":"RESULT[2]===80"},{"d":"평평하게 펴면 20번","js":"RESULT[3]===20"},{"d":"네 배가 줄어든다","js":"RESULT[4]===4"},{"d":"다섯 깊이가 장면으로 남는다","js":"FRAMES.length===5"},{"d":"깊이가 하나 늘 때마다 두 배가 된다","js":"FRAMES.every(function(f,i){return i===0||f.value.자식1개===FRAMES[i-1].value.자식1개*2;})"}],"ex":"레이아웃이 느린 이유는 대개 <b>그리는 일이 아니라 재는 일</b>입니다. 가중치가 걸린 컨테이너는 '자식들이 얼마나 필요한가' 를 먼저 물어보고, 남는 공간을 비율대로 나눠 준 뒤 <b>다시 한 번</b> 묻습니다. 이 컨테이너가 중첩되면 안쪽 자식은 <b>바깥 층마다 두 배씩</b> 측정되어 지수로 늘어납니다 — 깊이 5 면 한 뷰를 32번 재는 셈이고, 스크롤하는 리스트라면 <b>매 프레임마다</b> 그 일이 반복됩니다. 그래서 실무 규칙은 <b>'깊게 쌓지 말고 평평하게'</b> 입니다: 중첩된 가중치 대신 <b>ConstraintLayout</b>(형제끼리 관계를 걸어 한 번에 배치) 이나 Compose 처럼 <b>한 번 측정을 원칙으로 하는</b> 시스템을 쓰세요. 진단은 도구가 대신해 줍니다 — <b>Layout Inspector</b> 로 깊이를 보고, <b>GPU 렌더링 프로파일</b>이나 <code>Systrace</code> 에서 measure/layout 구간이 길면 이 문제입니다. 참고로 <code>merge</code> 태그로 불필요한 래퍼를 없애는 것만으로도 한 층이 줄어듭니다."},{"t":"sim","k":"성능 시뮬레이션","lv":3,"cat":"internals","q":"설정 저장을 <code>commit()</code> 으로 하느냐 <code>apply()</code> 로 하느냐가 메인 스레드를 얼마나 막는지 재세요. 규칙 — <code>commit()</code> 은 <b>디스크 쓰기가 끝날 때까지 호출 스레드를 막고</b>(한 번에 30ms), <code>apply()</code> 는 <b>메모리에만 즉시 반영</b>하고(0.05ms) 디스크는 백그라운드로 미룹니다. 메인 스레드가 <b>5,000ms</b> 넘게 막히면 ANR 입니다. 40번마다 <code>snap(\"쓰기 \"+n, {commit누적, apply누적, ANR})</code> 을 남기고 <b>[commit 총 블로킹(ms), ANR 인가, apply 총 블로킹(ms), 몇 번째 commit 에서 5초를 넘기나, 몇 배 빠른가]</b> 를 돌려주세요.","src":"const WRITES = 200;\nconst COMMIT_MS = 30, APPLY_MS = 0.05, ANR_MS = 5000;\nconst CHECKPOINTS = [40, 80, 120, 160, 200];\n\nfunction scene() {\n  return [0, false, 0, 0, 0];\n}\n\nRESULT = scene();","tests":[{"d":"commit 200번이면 6초를 막는다","js":"RESULT[0]===6000"},{"d":"5초를 넘으므로 ANR","js":"RESULT[1]===true"},{"d":"apply 는 10ms 로 끝난다","js":"RESULT[2]===10"},{"d":"167번째 commit 에서 5초를 넘긴다","js":"RESULT[3]===167"},{"d":"600배 차이","js":"RESULT[4]===600"},{"d":"체크포인트 다섯 개가 장면으로 남는다","js":"FRAMES.length===5"},{"d":"세 번째 체크포인트에서 이미 ANR 선을 넘었다","js":"FRAMES[4].value.ANR===true && FRAMES[0].value.ANR===false"}],"ex":"<code>commit()</code> 은 <b>이름과 달리 위험한 기본값</b>입니다 — 성공 여부를 <code>boolean</code> 으로 돌려주니 안전해 보이지만, 그 반환값을 받으려면 <b>디스크 쓰기가 끝날 때까지 기다려야</b> 하고 그 자리가 메인 스레드라면 화면이 그대로 멈춥니다. 여기서는 200번 저장에 6초가 걸려 <b>ANR</b>(5초)을 넘겼습니다. <code>apply()</code> 는 <b>메모리에 먼저 반영</b>해 이후 읽기가 곧바로 새 값을 보고, 디스크 쓰기는 백그라운드로 넘깁니다 — 그래서 <b>거의 언제나 <code>apply()</code> 가 정답</b>입니다(반환값이 필요한 경우는 사실상 없습니다). 다만 공짜는 아닙니다: 밀린 쓰기는 <code>onPause</code>·<code>onStop</code> 시점에 <b>시스템이 기다려 주므로</b>, 화면 전환이 느려지는 형태로 대가가 돌아옵니다. 그리고 <b>SharedPreferences 는 파일 하나를 통째로 다시 쓰는 구조</b>라 항목이 많아질수록 한 번의 저장이 비싸집니다 — 값이 수백 개거나 자주 바뀐다면 <b>DataStore</b> 나 <b>Room</b> 으로 옮기는 것이 맞습니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 IV","q":[{"t":"sim","k":"전력 시뮬레이션","lv":3,"cat":"internals","q":"기기가 <b>Doze</b> 에 들어간 뒤 예약한 작업이 언제 실행되는지 계산하세요. 규칙 — 유지보수 창은 처음 <b>1시간</b> 뒤에 열리고, 그다음부터 간격이 <b>2 → 4 → 8시간</b> 으로 늘다 <b>6시간에서 멈춥니다</b>. 창이 열릴 때마다 <code>snap(\"창 \"+n, {시각, 간격})</code> 을 남기세요. 또 앱 대기 버킷별로 하루에 몇 번 작업을 돌릴 수 있는지도 세세요(working_set 2시간마다 · frequent 8시간마다 · restricted 하루 1번). <b>[첫 창이 열리는 시각(시간), 24시간 안에 열리는 창 수, working_set 이 24시간에 가능한 횟수, frequent 는, restricted 는]</b> 을 돌려주세요.","src":"const FIRST = 1;\nconst GAPS = [2, 4, 8, 6];        // 그다음부터의 간격 · 마지막 값에서 고정\nconst HORIZON = 24;\nconst BUCKETS = { working_set: 2, frequent: 8, restricted: 24 };\n\nfunction scene() {\n  return [0, 0, 0, 0, 0];\n}\n\nRESULT = scene();","tests":[{"d":"첫 유지보수 창은 1시간 뒤","js":"RESULT[0]===1"},{"d":"24시간 동안 다섯 번 열린다","js":"RESULT[1]===5"},{"d":"working_set 은 12번","js":"RESULT[2]===12"},{"d":"frequent 는 3번","js":"RESULT[3]===3"},{"d":"restricted 는 하루 한 번","js":"RESULT[4]===1"},{"d":"다섯 창이 장면으로 남는다","js":"FRAMES.length===5"},{"d":"창 사이 간격이 점점 벌어진다","js":"FRAMES[3].value.시각-FRAMES[2].value.시각 > FRAMES[1].value.시각-FRAMES[0].value.시각"}],"ex":"Doze 는 <b>화면이 꺼지고 움직임이 없는 기기에서 앱을 잠재우는 장치</b>입니다. 잠든 동안에는 네트워크와 예약 작업이 막히고, <b>유지보수 창</b>이라는 짧은 시간에만 밀린 일이 한꺼번에 처리됩니다 — 그 창은 <b>점점 뜸해집니다</b>(1 → 3 → 7 → 15 → 21시간). 그래서 '5분마다 동기화' 같은 코드는 <b>충전 중이 아닌 밤에는 사실상 5시간마다</b> 돌게 됩니다. 여기에 <b>앱 대기 버킷</b>이 겹칩니다: 사용자가 자주 여는 앱은 제약이 거의 없지만, 안 쓰는 앱은 <code>rare</code>·<code>restricted</code> 로 내려가 <b>하루 한 번</b> 수준이 됩니다. 설계 결론은 셋입니다 — <b>정확한 시각에 꼭 실행돼야 하는 일</b>(알람·캘린더)은 <code>AlarmManager</code> 의 정확 알람이나 <b>서버 푸시</b>로 깨우고, <b>언젠가는 되면 되는 일</b>(업로드·정리)은 <code>WorkManager</code> 에 <b>제약</b>(충전 중·와이파이)과 함께 맡기고, <b>주기를 앱이 정하려 들지 마세요</b>. 그리고 테스트는 반드시 <code>adb shell dumpsys deviceidle force-idle</code> 로 <b>Doze 를 강제해</b> 해 보세요 — 개발 중에는 늘 화면이 켜져 있어 이 문제가 보이지 않습니다."},{"t":"sim","k":"배포 시뮬레이션","lv":3,"cat":"internals","q":"앱을 <b>통째로 하나</b>로 배포할 때와 <b>기기에 맞는 조각만</b> 내려줄 때 사용자가 실제로 받는 크기를 비교하세요. 공통 코드 12MB 에, ABI 4종 × 8MB · 화면 밀도 5종 × 6MB · 언어 20종 × 0.5MB 가 붙습니다. 한 사용자는 <b>각 축에서 하나씩만</b> 필요합니다. 축마다 <code>snap(축, {통째로, 사용자몫})</code> 을 남기고 <b>[유니버설 크기(MB), 실제 다운로드(MB), 절감률(%, 소수 첫째), ABI 만 나눴을 때 크기(MB), 유니버설이 100MB 를 넘는가]</b> 를 돌려주세요.","src":"const COMMON = 12;\nconst AXES = [\n  { name: 'ABI',   n: 4,  each: 8   },\n  { name: '밀도',  n: 5,  each: 6   },\n  { name: '언어',  n: 20, each: 0.5 }\n];\nconst LIMIT = 100;\n\nfunction scene() {\n  return [0, 0, 0, 0, false];\n}\n\nRESULT = scene();","tests":[{"d":"전부 담으면 84MB","js":"RESULT[0]===84"},{"d":"필요한 것만 받으면 26.5MB","js":"RESULT[1]===26.5"},{"d":"68.5% 를 아낀다","js":"RESULT[2]===68.5"},{"d":"ABI 만 나누면 60MB","js":"RESULT[3]===60"},{"d":"100MB 선은 넘지 않는다","js":"RESULT[4]===false"},{"d":"세 축이 장면으로 남는다","js":"FRAMES.length===3"},{"d":"ABI 축에서 가장 크게 아낀다","js":"FRAMES[0].value.통째로-FRAMES[0].value.사용자몫 > FRAMES[2].value.통째로-FRAMES[2].value.사용자몫"}],"ex":"앱 크기는 <b>기능이 아니라 설치율</b>의 문제입니다 — 용량이 크면 데이터를 아끼려는 사용자가 설치 자체를 포기하고, 이미 설치한 사람도 업데이트를 미룹니다. 그런데 큰 부분의 대부분은 <b>그 사용자에게 필요 없는 것</b>입니다: ARM 기기에 x86 네이티브 라이브러리가, 저밀도 기기에 4배 밀도 이미지가, 한국어 사용자에게 19개 언어 리소스가 함께 들어 있습니다. <b>앱 번들</b>은 이 축들을 쪼개 두고 스토어가 <b>기기에 맞는 조합만 조립해</b> 내려주므로, 여기서는 84MB 가 26.5MB 로 줄었습니다. 축마다 효과가 다르다는 점도 기억하세요 — <b>ABI 가 보통 가장 크고</b>(네이티브 라이브러리), 언어는 개수는 많아도 총량이 작습니다. 함께 쓰는 수단으로 <b>Play Feature Delivery</b>(잘 안 쓰는 기능을 나중에 내려받기), <b>리소스 축소·난독화</b>(<code>shrinkResources</code>·R8), <b>WebP·벡터 전환</b>이 있습니다. 그리고 항상 <b>다운로드 크기</b>와 <b>설치 후 크기</b>를 나눠 보세요 — 스토어에 표시되는 것은 앞의 것입니다."},{"t":"sim","k":"입력 시뮬레이션","lv":4,"cat":"internals","q":"스크롤 안에 든 버튼을 누를 때 <b>이벤트가 누구에게 가는지</b> 추적하세요. 규칙 — 이벤트는 부모부터 내려가고, 부모가 <b>가로채지 않으면</b> 자식이 받습니다. 자식이 <code>DOWN</code> 을 처리하면 이후 이벤트도 그 자식에게 갑니다. 그러다 손가락이 <b>임계값(8px)보다 많이 움직이면</b> 스크롤 부모가 <b>가로채고</b>, 그 순간 자식은 <code>CANCEL</code> 을 한 번 받은 뒤 <b>더는 아무것도 받지 못합니다</b>. 이벤트마다 <code>snap(이름, {받는쪽, 누적이동})</code> 을 남기고 <b>[버튼이 받은 이벤트 수(CANCEL 포함), 부모가 처리한 이벤트 수, CANCEL 이 몇 번째 이벤트인가, 클릭이 성사되는가, 가로챈 뒤 자식이 받은 이벤트 수]</b> 를 돌려주세요.","src":"// [이름, 이번 이동량(px)]\nconst EVENTS = [['DOWN', 0], ['MOVE', 5], ['MOVE', 20], ['MOVE', 12], ['UP', 0]];\nconst SLOP = 8;\n\nfunction scene() {\n  return [0, 0, 0, true, 0];\n}\n\nRESULT = scene();","tests":[{"d":"버튼은 DOWN·MOVE·CANCEL 세 개를 받는다","js":"RESULT[0]===3"},{"d":"부모는 가로챈 뒤 셋을 처리한다","js":"RESULT[1]===3"},{"d":"세 번째 이벤트에서 CANCEL 이 난다","js":"RESULT[2]===3"},{"d":"CANCEL 을 받았으므로 클릭은 취소된다","js":"RESULT[3]===false"},{"d":"가로챈 뒤 자식은 아무것도 받지 않는다","js":"RESULT[4]===0"},{"d":"다섯 이벤트가 장면으로 남는다","js":"FRAMES.length===5"},{"d":"가로채기 전까지는 버튼이 받는다","js":"FRAMES[1].value.받는쪽==='버튼'"}],"ex":"'버튼을 눌렀는데 눌리지 않았다' 의 정체는 대개 <b>스크롤이 이벤트를 가져간 것</b>입니다. 안드로이드의 터치 전달은 <b>부모 → 자식</b> 으로 내려가면서 각 부모에게 <code>onInterceptTouchEvent</code> 로 '내가 가져갈까?' 를 묻는데, 스크롤 컨테이너는 <b>손가락이 <code>touchSlop</code> 을 넘게 움직이는 순간</b> 그렇다고 답합니다. 그러면 지금까지 이벤트를 받던 자식에게 <b><code>ACTION_CANCEL</code> 이 한 번</b> 전달되고 — 이것이 '눌린 상태' 를 되돌리라는 신호입니다 — 이후 스트림은 전부 부모가 가져갑니다. 그래서 <b>자식은 CANCEL 을 반드시 처리</b>해야 합니다(눌림 표시를 지우고, 진행 중인 동작을 되돌리기). 반대 방향의 조절 수단도 있습니다: 자식이 <b>지금은 스크롤에 뺏기면 안 된다</b>고 판단하면 <code>requestDisallowInterceptTouchEvent(true)</code> 로 <b>부모의 가로채기를 잠시 막을</b> 수 있습니다(가로 스와이프 카드가 세로 스크롤 안에 들어 있는 경우가 전형적입니다). 그리고 <b>클릭은 UP 까지 무사히 도착했을 때만</b> 성립한다는 점을 기억하면, '가끔 안 눌려요' 류의 제보를 훨씬 빨리 좁힐 수 있습니다."},{"t":"sim","k":"네트워크 시뮬레이션","lv":4,"cat":"internals","q":"두 기기가 <b>오프라인에서 같은 문서를 고친 뒤</b> 각각 동기화할 때 무엇이 남는지 비교하세요. 기준 문서는 <code>{title:'A', count:1}</code>(버전 1) 이고, 기기1 은 <b>t=10 에 title 을 'B'</b> 로, 기기2 는 <b>t=20 에 count 를 5</b> 로 바꿉니다. 올리는 순서는 <b>기기2(t=25) → 기기1(t=30)</b> 입니다. 세 전략을 각각 적용하며 <code>snap(전략, {title, count, 잃은변경, 거부})</code> 을 남기고 <b>[문서 통째 LWW 의 count, 필드별 LWW 의 count, 문서 LWW 에서 잃은 변경 수, 필드별에서 잃은 변경 수, 낙관적 잠금에서 거부된 쓰기 수]</b> 를 돌려주세요.","src":"const BASE = { title: 'A', count: 1, version: 1 };\nconst EDITS = [\n  { dev: '기기1', field: 'title', value: 'B', at: 10, pushedAt: 30 },\n  { dev: '기기2', field: 'count', value: 5,   at: 20, pushedAt: 25 }\n];\n\nfunction scene() {\n  return [0, 0, 0, 0, 0];\n}\n\nRESULT = scene();","tests":[{"d":"문서를 통째로 덮으면 기기2 의 count 가 사라진다","js":"RESULT[0]===1"},{"d":"필드별로 합치면 count 가 남는다","js":"RESULT[1]===5"},{"d":"문서 LWW 는 변경 하나를 잃는다","js":"RESULT[2]===1"},{"d":"필드별은 아무것도 잃지 않는다","js":"RESULT[3]===0"},{"d":"낙관적 잠금은 나중 쓰기를 거부한다","js":"RESULT[4]===1"},{"d":"세 전략이 장면으로 남는다","js":"FRAMES.length===3"},{"d":"필드별만 두 변경을 모두 지킨다","js":"FRAMES[1].value.잃은변경===0 && FRAMES[0].value.잃은변경===1"}],"ex":"오프라인을 지원하는 순간 <b>충돌은 예외가 아니라 정상 동작</b>이 됩니다 — 두 사람이 같은 것을 각자 고칠 수 있으니까요. 가장 흔한 <b>문서 통째 last-write-wins</b> 는 구현이 쉬운 대신 <b>나중에 올린 쪽이 앞사람의 편집을 통째로 덮습니다</b>. 여기서는 기기1 이 제목만 바꿨을 뿐인데, 그가 들고 있던 <b>오래된 count 값</b>까지 함께 올라가 기기2 의 변경이 사라졌습니다 — 사용자 눈에는 <b>'내가 바꾼 게 저절로 돌아갔다'</b> 로 보이는, 가장 신뢰를 깎는 종류의 버그입니다. <b>필드별 LWW</b> 는 바뀐 필드만 각각 최신으로 남겨 이 경우를 해결하지만, <b>같은 필드를 둘이 고치면</b> 여전히 하나를 잃습니다. <b>낙관적 잠금</b>(버전이 다르면 거부)은 아무것도 조용히 잃지 않는 대신 <b>사용자에게 해결을 떠넘깁니다</b>. 실무에서는 데이터 성격으로 고릅니다: <b>카운터·집합</b>처럼 합칠 수 있는 것은 <b>증감(delta)이나 CRDT</b> 로 보내고, <b>텍스트 문서</b>는 병합 알고리즘을, <b>돈·재고</b>처럼 틀리면 안 되는 것은 <b>서버가 단일 진실</b>이 되게 하고 거부하세요. 무엇을 고르든 <b>'졌을 때 사용자가 알 수 있는가'</b> 를 반드시 설계에 넣어야 합니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}}],"ord":9}]);
